import '../../data/models/models.dart';

class SupplementalQuestion {
  final String id, prompt;
  final List<String> choices;
  final int correctIndex;
  final String explanation;
  const SupplementalQuestion(this.id, this.prompt, this.choices, this.correctIndex, this.explanation);
}

class SupplementalLesson {
  final String id, subject, title, explanation, example;
  final SchoolLevel level;
  final List<SupplementalQuestion> questions;
  const SupplementalLesson(this.id, this.level, this.subject, this.title, this.explanation, this.example, this.questions);
}

