    [SupplementalQuestion('bonus_cp2_read_1','Qui arrose le jardin ?',['Komi','Afi','Le maître'],0,'La phrase indique que Komi arrose le jardin.'), SupplementalQuestion('bonus_cp2_read_2','Que fait Komi ?',['Il dort','Il arrose','Il court'],1,'Le verbe arrose indique son action.'), SupplementalQuestion('bonus_cp2_read_3','Où arrose-t-il ?',['À la maison','Au marché','Dans le jardin'],2,'Il arrose le jardin.')]),
  SupplementalLesson('cp2_addition_dizaines', SchoolLevel.cp2, 'Mathématiques', 'Additionner des dizaines et des unités',
    'Aligne les unités avec les unités et les dizaines avec les dizaines. Additionne d’abord les unités, puis les dizaines. Si les unités dépassent 9, fais une retenue.',
    '23 + 14 : 3 + 4 = 7 unités et 2 dizaines + 1 dizaine = 3 dizaines. Résultat : 37.',
    [SupplementalQuestion('bonus_cp2_add_tens_1','21 + 13 = ?',['32','34','35'],1,'1 + 3 = 4 unités et 2 + 1 = 3 dizaines : 34.'), SupplementalQuestion('bonus_cp2_add_tens_2','32 + 15 = ?',['47','46','57'],0,'2 + 5 = 7 et 3 + 1 = 4 : 47.'), SupplementalQuestion('bonus_cp2_add_tens_3','40 + 20 = ?',['50','60','70'],1,'4 dizaines + 2 dizaines = 6 dizaines, soit 60.')]),
  SupplementalLesson('cp2_soustraction', SchoolLevel.cp2, 'Mathématiques', 'Soustraire des nombres',
    'Soustraire, c’est enlever une quantité. Commence par les unités puis les dizaines. Quand c’est nécessaire, échange une dizaine contre dix unités.',
    '35 − 12 : 5 − 2 = 3 et 3 dizaines − 1 dizaine = 2 dizaines. Résultat : 23.',
    [SupplementalQuestion('bonus_cp2_sub_1','28 − 5 = ?',['22','23','24'],1,'8 − 5 = 3 et les 2 dizaines restent : 23.'), SupplementalQuestion('bonus_cp2_sub_2','46 − 20 = ?',['26','36','24'],0,'On enlève 2 dizaines à 4 dizaines : il reste 2 dizaines et 6 unités.'), SupplementalQuestion('bonus_cp2_sub_3','19 − 7 = ?',['11','12','13'],1,'9 − 7 = 2 : le résultat est 12.')]),
  SupplementalLesson('ce1_multiplication_groupes', SchoolLevel.ce1, 'Mathématiques', 'Découvrir les groupes égaux',
    'Quand plusieurs groupes contiennent le même nombre d’objets, tu peux compter de manière répétée. C’est une première façon de comprendre la multiplication.',
    '3 assiettes avec 2 mangues chacune : 2 + 2 + 2 = 6 mangues.',
    [SupplementalQuestion('bonus_ce1_groups_1','2 groupes de 3 objets font…',['5','6','7'],1,'3 + 3 = 6 objets.'), SupplementalQuestion('bonus_ce1_groups_2','4 + 4 correspond à…',['2 groupes de 4','4 groupes de 3','1 groupe de 4'],0,'Deux groupes de quatre donnent 8.'), SupplementalQuestion('bonus_ce1_groups_3','3 groupes de 2 donnent…',['5','6','9'],1,'2 + 2 + 2 = 6.')]),
  SupplementalLesson('ce1_problemes_addition', SchoolLevel.ce1, 'Mathématiques', 'Résoudre un problème d’addition',
    'Lis l’énoncé et repère les quantités. Quand on réunit ou reçoit encore des objets, on peut utiliser une addition. Écris le calcul puis la réponse avec l’unité.',
    'Ama a 12 billes. Elle en reçoit 5. 12 + 5 = 17 billes.',
    [SupplementalQuestion('bonus_ce1_problem_add_1','Kossi a 10 crayons et en reçoit 4. Combien en a-t-il ?',['14','6','40'],0,'10 + 4 = 14 crayons.'), SupplementalQuestion('bonus_ce1_problem_add_2','Il y a 8 élèves puis 3 arrivent. Combien sont-ils ?',['10','11','12'],1,'8 + 3 = 11 élèves.'), SupplementalQuestion('bonus_ce1_problem_add_3','Afi a 15 F et reçoit 2 F. Combien a-t-elle ?',['13 F','17 F','20 F'],1,'15 + 2 = 17 F.')]),
  SupplementalLesson('cp2_syllabes', SchoolLevel.cp2, 'Français', 'Lire des syllabes',
    'Une syllabe se prononce en un seul morceau de voix. Associe une consonne et une voyelle.',
    'M et A donnent MA ; M et I donnent MI.',
    [SupplementalQuestion('bonus_cp2_fr_1','Que donnent M et A ?',['MA','MO','LA'],0,'M associé à A donne MA.'), SupplementalQuestion('bonus_cp2_fr_2','Maman commence par…',['MO','MA','MI'],1,'Maman commence par MA.'), SupplementalQuestion('extra_review_cp2_syllabes','Que donnent les lettres M et O ?',['MO','MA','MI'],0,'La consonne M associée à la voyelle O forme MO.')]),
  SupplementalLesson('cp2_addition', SchoolLevel.cp2, 'Mathématiques', 'Additionner',
    'Additionner, c’est réunir des quantités. Le signe + signifie ajouter.',
    '3 + 2 = 5.',
    [SupplementalQuestion('bonus_cp2_math_1','4 + 3 = ?',['6','7','8'],1,'4 + 3 = 7.'), SupplementalQuestion('bonus_cp2_math_2','Quel nombre vient après 9 ?',['8','10','11'],1,'Après 9 vient 10.'), SupplementalQuestion('extra_review_cp2_addition','Calcule 5 + 3.',['7','8','9'],1,'5 + 3 = 8.')]),
  SupplementalLesson('ce1_comprendre_texte', SchoolLevel.ce1, 'Français', 'Lire un texte et retrouver les informations',
    'Lis le texte attentivement. Repère les personnages, le lieu, le moment et les actions. Pour répondre, appuie-toi sur les informations réellement données.',
    'Le samedi matin, Afi accompagne son père au marché. Ils achètent du maïs et des tomates.',
    [SupplementalQuestion('bonus_ce1_text_1','Quand Afi va-t-elle au marché ?',['Le lundi soir','Le samedi matin','Le dimanche'],1,'Le texte précise : le samedi matin.'), SupplementalQuestion('bonus_ce1_text_2','Avec qui Afi va-t-elle au marché ?',['Son père','Sa sœur','Son maître'],0,'Elle accompagne son père.'), SupplementalQuestion('bonus_ce1_text_3','Qu’achètent-ils ?',['Du riz et du poisson','Du maïs et des tomates','Des cahiers'],1,'Le texte cite le maïs et les tomates.')]),
  SupplementalLesson('ce1_multiplication_table_2', SchoolLevel.ce1, 'Mathématiques', 'Construire la table de 2',
    'Multiplier par 2 revient à compter deux fois la même quantité ou à ajouter deux à chaque étape. Apprends les résultats en les reliant à des groupes de deux objets.',
    '2 × 1 = 2 ; 2 × 2 = 4 ; 2 × 3 = 6 ; 2 × 4 = 8 ; 2 × 5 = 10.',
    [SupplementalQuestion('bonus_ce1_table2_1','2 × 3 = ?',['5','6','8'],1,'Deux groupes de trois font six.'), SupplementalQuestion('bonus_ce1_table2_2','Quel est le résultat de 2 × 5 ?',['7','10','12'],1,'2 + 2 + 2 + 2 + 2 = 10.'), SupplementalQuestion('bonus_ce1_table2_3','Complète : 2, 4, 6, …',['7','8','9'],1,'On ajoute 2 à chaque fois : le nombre suivant est 8.')]),
  SupplementalLesson('ce2_division_partage', SchoolLevel.ce2, 'Mathématiques', 'Comprendre le partage équitable',
    'Diviser, c’est partager une quantité en parts égales ou former des groupes de même taille. Vérifie que chaque groupe reçoit le même nombre.',
    '12 oranges partagées entre 3 enfants : chacun reçoit 4 oranges, car 4 + 4 + 4 = 12.',
    [SupplementalQuestion('bonus_ce2_share_1','8 biscuits sont partagés entre 2 enfants. Chacun reçoit…',['2','4','6'],1,'8 ÷ 2 = 4 biscuits par enfant.'), SupplementalQuestion('bonus_ce2_share_2','15 mangues sont partagées entre 5 personnes. Chacune reçoit…',['3','5','10'],0,'15 ÷ 5 = 3 mangues.'), SupplementalQuestion('bonus_ce2_share_3','Quelle opération sert à partager en parts égales ?',['Addition','Division','Soustraction seulement'],1,'La division permet de partager équitablement.')]),
  SupplementalLesson('ce2_phrase_types', SchoolLevel.ce2, 'Français', 'Distinguer les types de phrases',
    'Une phrase déclarative donne une information et se termine souvent par un point. Une phrase interrogative pose une question et se termine par un point d’interrogation. Une phrase impérative donne un ordre ou un conseil.',
    'Le soleil brille. (déclarative) — Où vas-tu ? (interrogative) — Ferme la porte. (impérative)',
    [SupplementalQuestion('bonus_ce2_types_1','« Où habites-tu ? » est une phrase…',['Interrogative','Déclarative','Impérative'],0,'Elle pose une question.'), SupplementalQuestion('bonus_ce2_types_2','« Le chien aboie. » est…',['Interrogative','Déclarative','Impérative'],1,'Elle donne une information.'), SupplementalQuestion('bonus_ce2_types_3','« Range tes affaires. » exprime…',['Une question','Un ordre ou conseil','Une information'],1,'La phrase demande de faire une action.')]),
  SupplementalLesson('ce1_phrase', SchoolLevel.ce1, 'Français', 'Reconnaître une phrase',
    'Une phrase commence généralement par une majuscule et se termine par un signe de ponctuation.',
    'Le chat dort.',
    [SupplementalQuestion('bonus_ce1_fr_1','Quelle phrase est bien écrite ?',['le chien court','Le chien court.','Le chien court!'],1,'Majuscule au début, point à la fin.'), SupplementalQuestion('bonus_ce1_fr_2','Quel signe termine une phrase déclarative ?',['.','? ',','],0,'Le point termine une phrase déclarative.'), SupplementalQuestion('extra_review_ce1_phrase','Quel signe termine une phrase qui pose une question ?',['Le point .','Le point d’interrogation ?','La virgule ,'],1,'Une question se termine par un point d’interrogation.')]),
  SupplementalLesson('ce1_dizaines', SchoolLevel.ce1, 'Mathématiques', 'Dizaines et unités',
    'Dans un nombre à deux chiffres, le chiffre de gauche indique les dizaines et celui de droite les unités.',
    'Dans 24 : 2 dizaines et 4 unités.',
    [SupplementalQuestion('bonus_ce1_math_1','Combien de dizaines dans 36 ?',['3','6','36'],0,'Le chiffre des dizaines est 3.'), SupplementalQuestion('bonus_ce1_math_2','24 + 13 = ?',['27','37','47'],1,'24 + 10 + 3 = 37.'), SupplementalQuestion('extra_review_ce1_dizaines','Dans le nombre 52, combien y a-t-il d’unités ?',['5','2','52'],1,'Dans 52, il y a 5 dizaines et 2 unités.')]),
  SupplementalLesson('ce2_verbe', SchoolLevel.ce2, 'Français', 'Trouver le verbe',
    'Le verbe indique souvent une action ou un état. Demande-toi ce que fait le sujet.',
