    [SupplementalQuestion('bonus_ce2_fr_1','Quel est le verbe dans « Awa dessine » ?',['Awa','dessine','dessin'],1,'Dessine indique l’action.'), SupplementalQuestion('bonus_ce2_fr_2','Nous ___ contents.',['sommes','est','suis'],0,'Avec nous, on dit sommes.'), SupplementalQuestion('extra_review_ce2_verbe','Dans « Les enfants jouent », quel est le verbe ?',['Les','enfants','jouent'],2,'« Jouent » indique l’action réalisée par les enfants.')]),
  SupplementalLesson('ce2_multiplication', SchoolLevel.ce2, 'Mathématiques', 'Comprendre la multiplication',
    'Multiplier, c’est additionner plusieurs fois la même quantité.',
    '4 × 3 = 3 + 3 + 3 + 3 = 12.',
    [SupplementalQuestion('bonus_ce2_math_1','5 × 2 = ?',['7','10','12'],1,'Cinq groupes de deux font dix.'), SupplementalQuestion('bonus_ce2_math_2','3 × 4 correspond à…',['3 + 4','4 + 4 + 4','3 + 3'],1,'Trois groupes de quatre.'), SupplementalQuestion('extra_review_ce2_multiplication','Calcule 3 × 5.',['8','15','20'],1,'3 groupes de 5 font 15.')]),
  SupplementalLesson('cm1_fraction_equivalentes', SchoolLevel.cm1, 'Mathématiques', 'Reconnaître les fractions équivalentes',
    'Deux fractions sont équivalentes lorsqu’elles représentent la même quantité. Multiplier ou diviser le numérateur et le dénominateur par un même nombre non nul conserve la valeur de la fraction.',
    '1/2 = 2/4 : la moitié d’un gâteau est la même quantité que deux quarts du même gâteau.',
    [SupplementalQuestion('bonus_cm1_equiv_1','Quelle fraction est égale à 1/2 ?',['1/3','2/4','3/4'],1,'2/4 se simplifie en 1/2.'), SupplementalQuestion('bonus_cm1_equiv_2','Complète : 1/3 = ?/6',['2','3','4'],0,'On multiplie le numérateur et le dénominateur par 2 : 2/6.'), SupplementalQuestion('bonus_cm1_equiv_3','La fraction 3/6 représente…',['La moitié','Le tiers','Le tout'],0,'3/6 = 1/2.')]),
  SupplementalLesson('cm1_perimetre_rectangle', SchoolLevel.cm1, 'Mathématiques', 'Calculer le périmètre du rectangle',
    'Le périmètre est la longueur du contour d’une figure. Pour un rectangle, additionne ses quatre côtés : longueur + largeur + longueur + largeur.',
    'Un rectangle de 6 cm sur 3 cm a un périmètre de 6 + 3 + 6 + 3 = 18 cm, soit 2 × (6 + 3).',
    [SupplementalQuestion('bonus_cm1_perim_1','Périmètre d’un rectangle de 5 cm sur 2 cm ?',['7 cm','14 cm','10 cm'],1,'2 × (5 + 2) = 14 cm.'), SupplementalQuestion('bonus_cm1_perim_2','Le périmètre mesure…',['La surface','Le contour','Le volume'],1,'Le périmètre mesure la longueur du contour.'), SupplementalQuestion('bonus_cm1_perim_3','Un carré de côté 4 cm a un périmètre de…',['8 cm','12 cm','16 cm'],2,'4 côtés de 4 cm : 4 × 4 = 16 cm.')]),
  SupplementalLesson('cm2_nombres_decimaux', SchoolLevel.cm2, 'Mathématiques', 'Lire et comparer les nombres décimaux',
    'Un nombre décimal possède une partie entière et une partie décimale séparées par une virgule. Pour comparer deux nombres, compare d’abord les parties entières, puis les dixièmes, les centièmes, etc.',
    '3,45 est plus grand que 3,4 car 3,45 = 3,40 + 0,05.',
    [SupplementalQuestion('bonus_cm2_decimal_1','Quel nombre est le plus grand ?',['2,8','2,35','2,5'],0,'2,80 est supérieur à 2,50 et à 2,35.'), SupplementalQuestion('bonus_cm2_decimal_2','Dans 4,27, le chiffre des dixièmes est…',['2','7','4'],0,'Le premier chiffre après la virgule indique les dixièmes.'), SupplementalQuestion('bonus_cm2_decimal_3','4,5 est égal à…',['4,05','4,50','45'],1,'On peut écrire un zéro après le dernier chiffre décimal : 4,50.')]),
  SupplementalLesson('cm2_proportionnalite_tableau', SchoolLevel.cm2, 'Mathématiques', 'Compléter un tableau de proportionnalité',
    'Dans un tableau de proportionnalité, on passe d’une ligne à l’autre en multipliant toujours par le même nombre. Utilise ce coefficient pour compléter les cases manquantes.',
    'Si 1 cahier coûte 250 F, alors 2 cahiers coûtent 500 F et 4 cahiers coûtent 1 000 F.',
    [SupplementalQuestion('bonus_cm2_prop_1','Si 1 kg coûte 300 F, 3 kg coûtent…',['600 F','900 F','1 200 F'],1,'3 × 300 = 900 F.'), SupplementalQuestion('bonus_cm2_prop_2','Si 2 objets coûtent 100 F, 4 objets coûtent…',['150 F','200 F','300 F'],1,'On double la quantité, donc le prix double.'), SupplementalQuestion('bonus_cm2_prop_3','Le coefficient pour passer de 5 à 20 est…',['2','3','4'],2,'5 × 4 = 20.')]),
  SupplementalLesson('cm1_accord', SchoolLevel.cm1, 'Français', 'Accorder le verbe',
    'Le verbe change selon le sujet. Repère qui fait l’action puis choisis la bonne forme.',
    'L’enfant joue. Les enfants jouent.',
    [SupplementalQuestion('bonus_cm1_fr_1','Les filles ___ dans la cour.',['joue','jouent','joues'],1,'Les filles est un sujet pluriel.'), SupplementalQuestion('bonus_cm1_fr_2','Mon frère et moi ___.',['marchons','marche','marchent'],0,'Mon frère et moi correspond à nous.'), SupplementalQuestion('extra_review_cm1_accord','Le garçon et sa sœur ___ à l’école.',['vont','va','vas'],0,'« Le garçon et sa sœur » correspond à « ils » : on écrit « vont ».')]),
  SupplementalLesson('cm1_fractions', SchoolLevel.cm1, 'Mathématiques', 'Découvrir les fractions',
    'Une fraction représente des parts égales d’un tout. Le dénominateur indique le nombre de parts.',
    '1/2 signifie une part sur deux parts égales.',
    [SupplementalQuestion('bonus_cm1_math_1','Dans 3/4, quel est le dénominateur ?',['3','4','7'],1,'Le dénominateur est le nombre du bas.'), SupplementalQuestion('bonus_cm1_math_2','Une moitié s’écrit…',['1/2','1/3','2/1'],0,'Une moitié est une part sur deux.'), SupplementalQuestion('extra_review_cm1_fractions','Quelle fraction représente une part parmi quatre parts égales ?',['1/4','1/2','4/1'],0,'Une part sur quatre s’écrit 1/4.')]),
  SupplementalLesson('cm2_temps', SchoolLevel.cm2, 'Français', 'Présent et passé',
    'Le présent exprime ce qui se passe maintenant ou habituellement. Le passé exprime une action déjà faite.',
    'Aujourd’hui, je lis. Hier, j’ai lu.',
