  SupplementalLesson('cm2_aire', SchoolLevel.cm2, 'Mathématiques', 'Aire du rectangle',
    'L’aire mesure la surface à l’intérieur d’une figure. Pour un rectangle, longueur × largeur.',
    '5 cm × 3 cm = 15 cm².',
    [SupplementalQuestion('bonus_cm2_math_1','Aire d’un rectangle de 6 cm sur 2 cm ?',['8 cm²','12 cm²','16 cm²'],1,'6 × 2 = 12 cm².'), SupplementalQuestion('bonus_cm2_math_2','Quelle unité mesure une aire ?',['cm','cm²','cm³'],1,'L’aire se mesure en unités carrées.'), SupplementalQuestion('extra_review_cm2_aire','Quelle est l’aire d’un rectangle de 5 cm sur 4 cm ?',['9 cm²','20 cm²','18 cm²'],1,'Aire = longueur × largeur = 5 × 4 = 20 cm².')]),
  SupplementalLesson('sixieme_nature', SchoolLevel.sixieme, 'Français', 'Nom et adjectif',
    'Le nom désigne une personne, un animal, une chose ou une idée. L’adjectif précise le nom.',
    'Dans « une grande maison », maison est le nom et grande l’adjectif.',
    [SupplementalQuestion('bonus_6e_fr_1','Dans « un ballon rouge », quel est l’adjectif ?',['ballon','un','rouge'],2,'Rouge précise la couleur.'), SupplementalQuestion('bonus_6e_fr_2','Quel mot est un nom ?',['courir','école','rapidement'],1,'École désigne un lieu.'), SupplementalQuestion('extra_review_sixieme_nature','Dans « une maison blanche », quel mot est le nom ?',['une','maison','blanche'],1,'« Maison » désigne une chose : c’est le nom.')]),
  SupplementalLesson('sixieme_fractions', SchoolLevel.sixieme, 'Mathématiques', 'Comparer des fractions',
    'Avec le même dénominateur, la fraction au plus grand numérateur est la plus grande.',
    '3/5 est plus grand que 2/5.',
    [SupplementalQuestion('bonus_6e_math_1','Quelle fraction est la plus grande ?',['1/8','5/8','3/8'],1,'Les dénominateurs sont égaux ; 5 est le plus grand numérateur.'), SupplementalQuestion('bonus_6e_math_2','1/4 + 2/4 = ?',['3/4','3/8','2/4'],0,'On additionne les numérateurs.'), SupplementalQuestion('extra_review_sixieme_fractions','Parmi ces fractions, laquelle est supérieure aux autres ?',['2/7','4/7','1/7'],1,'Les dénominateurs sont égaux : 4/7 est la plus grande fraction.')]),
  SupplementalLesson('cinquieme_present', SchoolLevel.cinquieme, 'Français', 'Conjuguer au présent',
    'Au présent, la terminaison dépend du sujet et du groupe du verbe.',
    'Je finis, tu finis, il finit, nous finissons.',
    [SupplementalQuestion('bonus_5e_fr_1','Vous ___ vos devoirs.',['finissez','finit','finissons'],0,'Avec vous : finissez.'), SupplementalQuestion('bonus_5e_fr_2','Elles ___ une chanson.',['chante','chantent','chantons'],1,'Avec elles : chantent.'), SupplementalQuestion('extra_review_cinquieme_present','Nous ___ nos leçons chaque soir.',['finissons','finit','finissez'],0,'Avec le sujet « nous », le verbe finir se conjugue « nous finissons ».')]),
  SupplementalLesson('cinquieme_proportion', SchoolLevel.cinquieme, 'Mathématiques', 'Proportionnalité',
    'Dans une situation proportionnelle, les deux quantités sont multipliées par le même nombre.',
    '1 cahier coûte 200 F ; 3 cahiers coûtent 600 F.',
    [SupplementalQuestion('bonus_5e_math_1','Un cahier coûte 200 F. 3 cahiers coûtent…',['400 F','600 F','800 F'],1,'3 × 200 = 600 F.'), SupplementalQuestion('bonus_5e_math_2','Le double de 5 est…',['7','10','15'],1,'Doubler signifie multiplier par 2.'), SupplementalQuestion('extra_review_cinquieme_proportion','Un cahier coûte 200 F. Combien coûtent 4 cahiers au même prix ?',['600 F','800 F','1 000 F'],1,'4 × 200 F = 800 F.')]),
  SupplementalLesson('quatrieme_cod', SchoolLevel.quatrieme, 'Français', 'Repérer le COD',
    'Le COD complète le verbe sans préposition. Pose la question qui ? ou quoi ? après le verbe.',
    'Afi lit un livre. Elle lit quoi ? Un livre.',
    [SupplementalQuestion('bonus_4e_fr_1','Dans « Kossi mange une mangue », quel est le COD ?',['Kossi','mange','une mangue'],2,'Kossi mange quoi ? Une mangue.'), SupplementalQuestion('bonus_4e_fr_2','Le COD complète le…',['verbe','point','déterminant seul'],0,'Le COD complète le verbe.'), SupplementalQuestion('extra_review_quatrieme_cod','Dans « Ama regarde le film », quel est le COD ?',['Ama','regarde','le film'],2,'Ama regarde quoi ? Le film : « le film » est le COD.')]),
  SupplementalLesson('quatrieme_equation', SchoolLevel.quatrieme, 'Mathématiques', 'Résoudre une équation',
    'Pour trouver l’inconnue, effectue la même opération des deux côtés de l’équation.',
    'x + 5 = 12, donc x = 12 − 5 = 7.',
    [SupplementalQuestion('bonus_4e_math_1','Résous x + 4 = 10.',['4','6','14'],1,'x = 10 − 4 = 6.'), SupplementalQuestion('bonus_4e_math_2','Résous 3x = 15.',['3','5','12'],1,'x = 15 ÷ 3 = 5.'), SupplementalQuestion('extra_review_quatrieme_equation','Résous x − 3 = 5.',['2','8','15'],1,'On ajoute 3 aux deux membres : x = 5 + 3 = 8.')]),
  SupplementalLesson('troisieme_argument', SchoolLevel.troisieme, 'Français', 'Paragraphe argumenté',
    'Un paragraphe argumenté présente une idée, une raison et un exemple qui l’illustre.',
    'Lire enrichit le vocabulaire : on découvre de nouveaux mots.',
    [SupplementalQuestion('bonus_3e_fr_1','Un argument contient…',['une idée et une raison','seulement un titre','des mots sans lien'],0,'Une raison soutient l’idée.'), SupplementalQuestion('bonus_3e_fr_2','Un exemple sert à…',['illustrer l’idée','changer de sujet','remplacer la conclusion'],0,'L’exemple rend l’argument concret.'), SupplementalQuestion('extra_review_troisieme_argument','À quoi sert un exemple dans un paragraphe argumenté ?',['À illustrer un argument','À remplacer le sujet','À ajouter une idée sans rapport'],0,'Un exemple rend l’argument plus concret et aide à le comprendre.')]),
  SupplementalLesson('troisieme_pythagore', SchoolLevel.troisieme, 'Mathématiques', 'Théorème de Pythagore',
    'Dans un triangle rectangle, le carré de l’hypoténuse égale la somme des carrés des deux autres côtés.',
    '3² + 4² = 9 + 16 = 25, donc l’hypoténuse mesure 5.',
    [SupplementalQuestion('bonus_3e_math_1','Côtés de l’angle droit : 3 et 4. Hypoténuse ?',['5','6','7'],0,'La longueur est 5 car 25 = 5².'), SupplementalQuestion('bonus_3e_math_2','L’hypoténuse est…',['en face de l’angle droit','toujours le plus petit côté','parallèle à un côté'],0,'Elle est opposée à l’angle droit.'), SupplementalQuestion('extra_review_troisieme_pythagore','Un triangle rectangle a des côtés de l’angle droit de 6 cm et 8 cm. Quelle est son hypoténuse ?',['10 cm','12 cm','14 cm'],0,'6² + 8² = 36 + 64 = 100 ; √100 = 10 cm.')]),
  SupplementalLesson('seconde_resume', SchoolLevel.seconde, 'Français', 'Réussir un résumé',
    'Un résumé garde les idées essentielles dans un ordre logique, sans ajouter son opinion.',
    'Repère les idées principales, puis reformule-les brièvement.',
    [SupplementalQuestion('bonus_2nde_fr_1','Un résumé garde…',['les idées essentielles','tous les détails','son opinion'],0,'Le résumé conserve l’essentiel.'), SupplementalQuestion('bonus_2nde_fr_2','Faut-il copier chaque phrase ?',['oui','non, reformule','seulement le titre'],1,'Il faut reformuler et raccourcir.'), SupplementalQuestion('extra_review_seconde_resume','Que faut-il éviter dans un résumé ?',['Ajouter son opinion personnelle','Garder les idées essentielles','Respecter l’ordre logique'],0,'Un résumé restitue les idées du texte sans ajouter son opinion.')]),
  SupplementalLesson('seconde_fonction', SchoolLevel.seconde, 'Mathématiques', 'Calculer une image',
    'Pour calculer l’image d’un nombre, remplace x par ce nombre dans l’expression de la fonction.',
    'f(x)=2x+3 ; f(4)=2×4+3=11.',
    [SupplementalQuestion('bonus_2nde_math_1','f(x)=x+5. f(3)=?',['8','15','2'],0,'3 + 5 = 8.'), SupplementalQuestion('bonus_2nde_math_2','g(x)=3x. g(4)=?',['7','12','34'],1,'3 × 4 = 12.'), SupplementalQuestion('extra_review_seconde_fonction','Si f(x) = 2x + 1, quelle est l’image de 3 ?',['6','7','8'],1,'f(3) = 2 × 3 + 1 = 7.')]),
  SupplementalLesson('premiere_method', SchoolLevel.premiere, 'Méthodologie', 'Organiser une réponse',
    'Présente une idée directrice, des arguments ordonnés et des exemples précis. Relis la consigne.',
    'Introduction courte, développement organisé, conclusion qui répond au sujet.',
    [SupplementalQuestion('bonus_1ere_method_1','Que faire avant de rédiger ?',['analyser la consigne','écrire au hasard','ignorer le sujet'],0,'Comprendre la consigne permet de répondre au sujet.'), SupplementalQuestion('bonus_1ere_method_2','Les exemples servent à…',['appuyer les arguments','allonger sans raison','éviter la réponse'],0,'Les exemples illustrent les idées.'), SupplementalQuestion('extra_review_premiere_method','Une réponse organisée doit…',['présenter des arguments liés au sujet','aligner des phrases sans ordre','ignorer la consigne'],0,'Une réponse organisée suit la consigne et développe des arguments cohérents.')]),
  SupplementalLesson('premiere_derivation', SchoolLevel.premiere, 'Mathématiques', 'Dériver x²',
    'La dérivée de f(x)=x² est f’(x)=2x. Elle aide à étudier les variations.',
    'f’(3)=2×3=6.',
    [SupplementalQuestion('bonus_1ere_math_1','Dérivée de x² ?',['x','2x','x³'],1,'La dérivée de x² est 2x.'), SupplementalQuestion('bonus_1ere_math_2','Si f’(x)=2x, f’(4)=?',['6','8','16'],1,'2 × 4 = 8.'), SupplementalQuestion('extra_review_premiere_derivation','Si f’(x) = 2x, combien vaut f’(5) ?',['7','10','25'],1,'On remplace x par 5 : f’(5) = 2 × 5 = 10.')]),
  SupplementalLesson('terminale_bac', SchoolLevel.terminale, 'Méthodologie', 'Gérer une épreuve du BAC',
    'Lis les consignes, répartis ton temps et garde quelques minutes pour vérifier tes réponses.',
    'Commence par les questions accessibles, puis reviens aux questions difficiles.',
    [SupplementalQuestion('bonus_terminale_method_1','Pourquoi relire ?',['repérer les erreurs','ne pas répondre','recopier le sujet'],0,'La relecture aide à corriger les oublis.'), SupplementalQuestion('bonus_terminale_method_2','Une question difficile :',['y consacrer tout le temps','passer provisoirement et revenir','quitter l’épreuve'],1,'Avance puis reviens si le temps le permet.'), SupplementalQuestion('extra_review_terminale_bac','Pourquoi faut-il répartir son temps pendant une épreuve ?',['Pour traiter les différentes questions','Pour rester longtemps sur une seule question','Pour ne pas relire sa copie'],0,'Une bonne gestion du temps permet de traiter le sujet et de garder un moment pour vérifier.')]),
  SupplementalLesson('terminale_derivation', SchoolLevel.terminale, 'Mathématiques', 'Utiliser une dérivée',
    'Une dérivée positive sur un intervalle indique que la fonction y est croissante.',
    'Pour f(x)=3x, la dérivée est f’(x)=3.',
    [SupplementalQuestion('bonus_terminale_math_1','Si f’ est positive, f est…',['croissante','toujours constante','toujours négative'],0,'Une dérivée positive indique une fonction croissante.'), SupplementalQuestion('bonus_terminale_math_2','Dérivée de 3x ?',['3','3x²','x'],0,'La dérivée de 3x est 3.') , SupplementalQuestion('extra_review_terminale_derivation','Si f’(x) est négative sur un intervalle, la fonction f y est…',['croissante','décroissante','nécessairement constante'],1,'Une dérivée négative sur un intervalle indique que la fonction y est décroissante.')]),

  SupplementalLesson('sixieme_operations_decimales', SchoolLevel.sixieme, 'Mathématiques', 'Additionner et soustraire des nombres décimaux',
    'Pour additionner ou soustraire des nombres décimaux, aligne les virgules, puis les chiffres de même rang. Tu peux ajouter des zéros pour compléter les rangs manquants.',
    '12,5 + 3,25 = 12,50 + 3,25 = 15,75. Pour 8,4 − 2,15, calcule 8,40 − 2,15 = 6,25.',
    [SupplementalQuestion('bonus_6e_decimal_1','Calcule 2,4 + 1,3.',['3,5','3,7','4,7'],1,'2,4 + 1,3 = 3,7.'), SupplementalQuestion('bonus_6e_decimal_2','Calcule 5,60 − 2,25.',['3,25','3,35','4,35'],1,'5,60 − 2,25 = 3,35.'), SupplementalQuestion('bonus_6e_decimal_3','Pourquoi aligne-t-on les virgules ?',['Pour aligner les unités de même rang','Pour supprimer les unités','Pour multiplier les nombres'],0,'Les virgules alignées placent les dixièmes sous les dixièmes et les unités sous les unités.')]),
  SupplementalLesson('cinquieme_fractions_addition', SchoolLevel.cinquieme, 'Mathématiques', 'Additionner des fractions de même dénominateur',
    'Lorsque deux fractions ont le même dénominateur, on additionne leurs numérateurs et on conserve le dénominateur. Les parts doivent être de même taille.',
    '2/7 + 3/7 = 5/7. On additionne 2 et 3, mais on garde 7.',
    [SupplementalQuestion('bonus_5e_fraction_1','Calcule 1/5 + 2/5.',['3/5','3/10','2/5'],0,'Les dénominateurs sont égaux : 1 + 2 = 3, donc 3/5.'), SupplementalQuestion('bonus_5e_fraction_2','Calcule 3/8 + 4/8.',['7/16','7/8','1/8'],1,'3/8 + 4/8 = 7/8.'), SupplementalQuestion('bonus_5e_fraction_3','Dans 2/9 + 5/9, quel dénominateur conserve-t-on ?',['7','9','18'],1,'On conserve le dénominateur commun 9.')]),
  SupplementalLesson('quatrieme_thales', SchoolLevel.quatrieme, 'Mathématiques', 'Découvrir le théorème de Thalès',
    'Dans un triangle, si une droite est parallèle à un côté et coupe les deux autres côtés, le théorème de Thalès permet d’établir des rapports de longueurs correspondantes. Vérifie toujours le parallélisme et l’ordre des points.',
    'Si (MN) est parallèle à (BC) dans le triangle ABC, alors AM/AB = AN/AC = MN/BC.',
    [SupplementalQuestion('bonus_4e_thales_1','Quelle condition est essentielle pour appliquer cette configuration du théorème de Thalès ?',['Une droite parallèle à un côté du triangle','Un angle droit obligatoire','Un triangle équilatéral'],0,'Le parallélisme est la condition qui permet d’établir les rapports.'), SupplementalQuestion('bonus_4e_thales_2','Si AM/AB = 2/5 et AB = 10 cm, alors AM vaut…',['2 cm','4 cm','5 cm'],1,'AM = (2/5) × 10 = 4 cm.'), SupplementalQuestion('bonus_4e_thales_3','Les rapports de Thalès comparent…',['Des longueurs correspondantes','Des aires uniquement','Des angles uniquement'],0,'Le théorème établit des égalités entre rapports de longueurs correspondantes.')]),
  SupplementalLesson('troisieme_equation_second_degre', SchoolLevel.troisieme, 'Mathématiques', 'Résoudre une équation-produit simple',
    'Pour résoudre une équation-produit A × B = 0, utilise la règle du produit nul : A = 0 ou B = 0. Résous ensuite chaque équation.',
    '(x − 3)(x + 2) = 0 donne x − 3 = 0 ou x + 2 = 0, donc x = 3 ou x = −2.',
    [SupplementalQuestion('bonus_3e_prod_1','Si (x − 4)(x + 1) = 0, quelles sont les solutions ?',['4 et −1','−4 et 1','4 seulement'],0,'x − 4 = 0 donne 4 ; x + 1 = 0 donne −1.'), SupplementalQuestion('bonus_3e_prod_2','La règle du produit nul s’applique lorsque le produit est égal à…',['0','1','−1'],0,'Si un produit est nul, au moins un de ses facteurs est nul.'), SupplementalQuestion('bonus_3e_prod_3','Résous (x + 5)(x − 2) = 0.',['−5 et 2','5 et −2','−5 seulement'],0,'Les deux facteurs donnent x = −5 ou x = 2.')]),

  SupplementalLesson('seconde_equation_lineaire', SchoolLevel.seconde, 'Mathématiques', 'Résoudre une équation du premier degré',
    'Une équation du premier degré contient une inconnue à la puissance 1. Pour isoler x, effectue la même opération dans les deux membres.',
    '3x + 5 = 17 ; 3x = 12 ; x = 4.',
    [SupplementalQuestion('bonus_2nde_eq_1','Résous 2x + 6 = 14.',['x = 3','x = 4','x = 5'],1,'2x = 14 − 6 = 8, donc x = 4.'), SupplementalQuestion('bonus_2nde_eq_2','Résous 5x = 35.',['x = 5','x = 7','x = 30'],1,'On divise les deux membres par 5 : x = 7.'), SupplementalQuestion('bonus_2nde_eq_3','Quelle opération annule une addition de 9 ?',['Ajouter 9','Soustraire 9','Multiplier par 9'],1,'L’opération inverse de +9 est −9.')]),
  SupplementalLesson('premiere_suite_arithmetique_renforce', SchoolLevel.premiere, 'Mathématiques', 'Reconnaître une suite arithmétique',
    'Une suite est arithmétique lorsque l’on ajoute toujours le même nombre, appelé raison, pour passer d’un terme au suivant.',
    '4, 7, 10, 13 : la raison est 3 car chaque terme augmente de 3.',
    [SupplementalQuestion('bonus_1ere_suite_1','Quelle est la raison de 2, 6, 10, 14 ?',['2','4','6'],1,'Chaque terme augmente de 4.'), SupplementalQuestion('bonus_1ere_suite_2','Après 5, 8, 11, quel est le terme suivant ?',['12','13','14'],2,'On ajoute 3 : 11 + 3 = 14.'), SupplementalQuestion('bonus_1ere_suite_3','Dans une suite arithmétique, on passe au terme suivant en…',['multipliant toujours','ajoutant la raison','divisant par le rang'],1,'La différence entre deux termes consécutifs est constante.')]),
  SupplementalLesson('terminale_probabilite_conditionnelle', SchoolLevel.terminale, 'Mathématiques', 'Comprendre une probabilité conditionnelle',
    'La probabilité de A sachant B se note P(A|B). Lorsque P(B) est non nulle, elle vaut P(A intersection B) divisée par P(B).',
    'Si P(A intersection B) = 0,12 et P(B) = 0,30, alors P(A|B) = 0,12 / 0,30 = 0,4.',
    [SupplementalQuestion('bonus_terminale_cond_1','Si P(A∩B)=0,2 et P(B)=0,5, P(A|B) vaut…',['0,1','0,4','0,7'],1,'P(A|B) = 0,2 ÷ 0,5 = 0,4.'), SupplementalQuestion('bonus_terminale_cond_2','Que signifie P(A|B) ?',['Probabilité de A sachant B','Probabilité de B sachant A','Somme de P(A) et P(B)'],0,'La barre verticale signifie « sachant que B est réalisé ».'), SupplementalQuestion('bonus_terminale_cond_3','La formule P(A|B)=P(A∩B)/P(B) exige…',['P(B) différent de 0','P(A) égal à 0','P(B) égal à 1'],0,'On ne peut pas diviser par zéro : P(B) doit être non nulle.')]),

  SupplementalLesson('seconde_systeme_equations', SchoolLevel.seconde, 'Mathématiques', 'Résoudre un système de deux équations',
    'Un système de deux équations à deux inconnues cherche un couple (x ; y) qui vérifie les deux égalités. On peut utiliser la substitution : exprimer une inconnue, puis la remplacer dans l’autre équation.',
    'x + y = 10 et x − y = 2. En additionnant, 2x = 12, donc x = 6 et y = 4.',
    [SupplementalQuestion('bonus_2nde_systeme_1','Si x + y = 9 et x = 4, y vaut…',['3','5','13'],1,'y = 9 − 4 = 5.'), SupplementalQuestion('bonus_2nde_systeme_2','Quel couple vérifie x + y = 7 et x = 2 ?',['(2 ; 5)','(2 ; 4)','(3 ; 4)'],0,'2 + 5 = 7.'), SupplementalQuestion('bonus_2nde_systeme_3','Après avoir trouvé x, que fait-on pour trouver y ?',['On remplace x dans une équation','On multiplie toujours par zéro','On ignore la deuxième équation'],0,'La substitution permet de calculer l’autre inconnue.')]),
  SupplementalLesson('premiere_trinome_signe', SchoolLevel.premiere, 'Mathématiques', 'Étudier le signe d’un produit factorisé',
    'Pour étudier le signe d’un produit de facteurs, on repère les valeurs qui annulent chaque facteur, puis on détermine le signe sur chaque intervalle. Un tableau de signes aide à ne pas oublier les changements de signe.',
    '(x − 2)(x + 1) s’annule pour x = 2 et x = −1. Le produit est positif à l’extérieur des deux racines et négatif entre elles.',
    [SupplementalQuestion('bonus_1ere_trinome_1','Quelles valeurs annulent (x − 3)(x + 2) ?',['3 et −2','−3 et 2','3 seulement'],0,'Chaque facteur s’annule séparément : x = 3 ou x = −2.'), SupplementalQuestion('bonus_1ere_trinome_2','Si deux facteurs sont tous les deux négatifs, leur produit est…',['négatif','positif','nul obligatoirement'],1,'Le produit de deux nombres négatifs est positif.'), SupplementalQuestion('bonus_1ere_trinome_3','À quoi sert un tableau de signes ?',['À étudier le signe selon les intervalles','À calculer une moyenne','À mesurer un angle'],0,'Il organise les signes des facteurs et du produit.')]),
  SupplementalLesson('terminale_limite_simple', SchoolLevel.terminale, 'Mathématiques', 'Comprendre une limite à l’infini',
    'La limite décrit le comportement d’une fonction lorsque x devient très grand ou très petit. Pour un polynôme, le terme de plus haut degré domine souvent le comportement à l’infini.',
    'Lorsque x tend vers +∞, 3x + 2 tend vers +∞ car le terme 3x devient de plus en plus grand.',
    [SupplementalQuestion('bonus_terminale_limite_1','Quand x tend vers +∞, 2x + 5 tend vers…',['+∞','−∞','5'],0,'Le terme 2x devient arbitrairement grand.'), SupplementalQuestion('bonus_terminale_limite_2','Dans 4x² + 3x + 1, quel terme domine à l’infini ?',['4x²','3x','1'],0,'Le terme de plus haut degré domine le comportement.'), SupplementalQuestion('bonus_terminale_limite_3','Une limite décrit…',['Le comportement d’une fonction près d’une valeur ou à l’infini','Uniquement la valeur de x','La longueur d’un segment'],0,'La limite étudie le comportement des valeurs de la fonction.') ]),

  SupplementalLesson('ce2_sujet_verbe', SchoolLevel.ce2, 'Français', 'Reconnaître le sujet et le verbe',
    'Le verbe indique souvent une action ou un état. Le sujet indique qui fait l’action ou de qui l’on parle. Pour trouver le sujet, pose la question « qui est-ce qui ? » avant le verbe.',
    'Dans « Les élèves chantent », qui est-ce qui chante ? Les élèves : c’est le sujet. Chantent est le verbe.',
    [SupplementalQuestion('bonus_ce2_sujet_1','Dans « Afi court », quel est le sujet ?',['Afi','court','aucun'],0,'Qui est-ce qui court ? Afi.'), SupplementalQuestion('bonus_ce2_sujet_2','Dans « Les oiseaux volent », quel est le verbe ?',['Les','oiseaux','volent'],2,'Volent indique l’action.'), SupplementalQuestion('bonus_ce2_sujet_3','Quelle question aide à trouver le sujet ?',['Combien ça coûte ?','Qui est-ce qui ?','Quand finit-il ?'],1,'On pose « qui est-ce qui ? » avant le verbe.')]),
  SupplementalLesson('cm1_cycle_eau', SchoolLevel.cm1, 'Sciences', 'Comprendre le cycle de l’eau',
    'Sous l’effet de la chaleur du Soleil, une partie de l’eau s’évapore. La vapeur se refroidit et forme des nuages par condensation. L’eau retombe ensuite sous forme de précipitations et rejoint les sols, les rivières et les océans.',
    'Évaporation → condensation → précipitations → ruissellement ou infiltration : ce cycle recommence continuellement.',
    [SupplementalQuestion('bonus_cm1_eau_1','Quel phénomène transforme l’eau liquide en vapeur ?',['La condensation','L’évaporation','La solidification'],1,'La chaleur favorise l’évaporation.'), SupplementalQuestion('bonus_cm1_eau_2','Comment se forment les nuages ?',['Par condensation de la vapeur d’eau','Par combustion','Par solidification du sol'],0,'La vapeur se refroidit et se condense en fines gouttelettes.'), SupplementalQuestion('bonus_cm1_eau_3','La pluie correspond à…',['Une précipitation','Une évaporation','Une infiltration'],0,'La pluie est une forme de précipitation.')]),
  SupplementalLesson('quatrieme_circuit_electrique', SchoolLevel.quatrieme, 'Physique-Chimie', 'Comprendre un circuit électrique simple',
    'Un circuit électrique simple comporte un générateur, des fils conducteurs et un récepteur, par exemple une lampe. Le courant circule lorsque le circuit est fermé. Un interrupteur permet d’ouvrir ou de fermer le circuit.',
    'Pile + fils + lampe dans une boucle fermée : la lampe peut s’allumer. Si le circuit est ouvert, le courant ne circule pas.',
    [SupplementalQuestion('bonus_4e_circuit_1','Quand la lampe peut-elle s’allumer ?',['Quand le circuit est fermé','Quand le fil est coupé','Quand le circuit est ouvert'],0,'Un circuit fermé permet au courant de circuler.'), SupplementalQuestion('bonus_4e_circuit_2','Quel élément fournit l’énergie électrique dans ce montage ?',['La lampe','La pile','Le fil seul'],1,'La pile est le générateur.'), SupplementalQuestion('bonus_4e_circuit_3','Quel est le rôle de l’interrupteur ?',['Ouvrir ou fermer le circuit','Créer les fils','Mesurer la masse'],0,'L’interrupteur commande l’ouverture et la fermeture du circuit.')]),

  SupplementalLesson('ce1_soustraction_emprunt', SchoolLevel.ce1, 'Mathématiques', 'Soustraire avec une retenue',
    'Quand le chiffre des unités du nombre du haut est plus petit, on échange une dizaine contre dix unités. On effectue ensuite la soustraction colonne par colonne.',
    '52 − 28 : échange 1 dizaine, 12 − 8 = 4 unités et 4 − 2 = 2 dizaines. Résultat : 24.',
    [SupplementalQuestion('bonus_ce1_retenue_1','Calcule 41 − 16.',['25','35','27'],0,'41 − 16 = 25.'), SupplementalQuestion('bonus_ce1_retenue_2','Dans 52 − 28, combien d’unités obtient-on après échange ?',['2','12','10'],1,'On échange une dizaine : 2 unités deviennent 12 unités.'), SupplementalQuestion('bonus_ce1_retenue_3','Calcule 63 − 27.',['36','46','34'],0,'63 − 27 = 36.')]),
  SupplementalLesson('cm2_aire_triangle', SchoolLevel.cm2, 'Mathématiques', 'Calculer l’aire d’un triangle',
    'L’aire d’un triangle est la moitié de l’aire du rectangle qui a la même base et la même hauteur. La formule est : base × hauteur ÷ 2.',
    'Base 8 cm et hauteur 5 cm : aire = 8 × 5 ÷ 2 = 20 cm².',
    [SupplementalQuestion('bonus_cm2_aire_tri_1','Base 6 cm et hauteur 4 cm : quelle aire ?',['10 cm²','12 cm²','24 cm²'],1,'6 × 4 ÷ 2 = 12 cm².'), SupplementalQuestion('bonus_cm2_aire_tri_2','Quelle formule donne l’aire d’un triangle ?',['base × hauteur','base × hauteur ÷ 2','base + hauteur'],1,'On divise par deux le produit de la base et de la hauteur.'), SupplementalQuestion('bonus_cm2_aire_tri_3','Si base = 10 cm et hauteur = 3 cm, l’aire vaut…',['15 cm²','30 cm²','13 cm²'],0,'10 × 3 ÷ 2 = 15 cm².')]),
  SupplementalLesson('cinquieme_respiration', SchoolLevel.cinquieme, 'Sciences', 'Comprendre la respiration des êtres vivants',
    'La plupart des êtres vivants utilisent du dioxygène pour la respiration et rejettent du dioxyde de carbone. Les organes respiratoires varient selon les espèces : poumons, branchies ou surfaces d’échanges.',
    'Le poisson prélève le dioxygène dissous dans l’eau grâce à ses branchies.',
    [SupplementalQuestion('bonus_5e_resp_1','Quel gaz est généralement prélevé lors de la respiration ?',['Dioxygène','Dioxyde de carbone','Azote uniquement'],0,'Le dioxygène est utilisé par les organes.'), SupplementalQuestion('bonus_5e_resp_2','Quel organe permet au poisson de respirer dans l’eau ?',['Les poumons','Les branchies','Les feuilles'],1,'Les branchies prélèvent le dioxygène dissous dans l’eau.'), SupplementalQuestion('bonus_5e_resp_3','Quel gaz est rejeté lors de la respiration ?',['Dioxygène','Dioxyde de carbone','Hydrogène'],1,'La respiration rejette du dioxyde de carbone.')]),

  SupplementalLesson('ce2_multiplication_dizaines', SchoolLevel.ce2, 'Mathématiques', 'Multiplier par une dizaine entière',
    'Pour multiplier un nombre par 10, on décale chaque chiffre d’un rang vers la gauche dans le tableau de numération. Pour multiplier par 20, 30 ou 40, on multiplie d’abord par 2, 3 ou 4, puis par 10.',
    '23 × 20 = 23 × 2 × 10 = 46 × 10 = 460.',
    [SupplementalQuestion('bonus_ce2_mult_diz_1','Calcule 14 × 20.',['280','240','140'],0,'14 × 2 = 28, puis 28 × 10 = 280.'), SupplementalQuestion('bonus_ce2_mult_diz_2','Calcule 32 × 30.',['960','9600','930'],0,'32 × 3 = 96, puis 96 × 10 = 960.'), SupplementalQuestion('bonus_ce2_mult_diz_3','20 × 15 vaut…',['150','300','35'],1,'2 × 15 = 30, puis on multiplie par 10 : 300.')]),
  SupplementalLesson('cm1_adjectif_qualificatif', SchoolLevel.cm1, 'Français', 'Reconnaître l’adjectif qualificatif',
    'L’adjectif qualificatif donne une précision sur un nom. Il peut indiquer une qualité, une couleur, une taille ou un caractère. Il s’accorde généralement en genre et en nombre avec le nom qu’il accompagne.',
    'Dans « une grande maison blanche », grande et blanche sont des adjectifs qui précisent le nom maison.',
    [SupplementalQuestion('bonus_cm1_adj_1','Dans « un petit chat noir », quels mots sont des adjectifs ?',['petit et noir','un et chat','chat seulement'],0,'Petit et noir donnent des précisions sur le nom chat.'), SupplementalQuestion('bonus_cm1_adj_2','Quel adjectif complète « une robe… » ?',['joli','jolie','jolis'],1,'Robe est féminin singulier : jolie s’accorde avec robe.'), SupplementalQuestion('bonus_cm1_adj_3','À quoi sert un adjectif qualificatif ?',['À préciser un nom','À remplacer toujours le verbe','À compter les syllabes'],0,'Il apporte une information sur le nom.')]),
  SupplementalLesson('troisieme_loi_ohm', SchoolLevel.troisieme, 'Physique-Chimie', 'Utiliser la loi d’Ohm',
    'Pour un conducteur ohmique, la tension U, la résistance R et l’intensité I sont liées par la loi d’Ohm : U = R × I. Les unités sont le volt (V), l’ohm (Ω) et l’ampère (A).',
    'Si R = 4 Ω et I = 2 A, alors U = 4 × 2 = 8 V.',
    [SupplementalQuestion('bonus_3e_ohm_1','Quelle formule exprime la loi d’Ohm ?',['U = R × I','U = R + I','I = U × R'],0,'La tension est égale à la résistance multipliée par l’intensité.'), SupplementalQuestion('bonus_3e_ohm_2','R = 5 Ω et I = 3 A. U vaut…',['8 V','15 V','2 V'],1,'U = 5 × 3 = 15 V.'), SupplementalQuestion('bonus_3e_ohm_3','Quelle unité mesure la résistance ?',['Volt','Ampère','Ohm'],2,'La résistance électrique se mesure en ohms (Ω).')]),

  SupplementalLesson('cm2_fraction_nombre_decimal', SchoolLevel.cm2, 'Mathématiques', 'Relier fraction décimale et nombre décimal',
    'Une fraction dont le dénominateur est 10, 100 ou 1 000 peut s’écrire sous forme de nombre décimal. Le numérateur indique les dixièmes, centièmes ou millièmes.',
    '35/100 = 0,35 : 35 centièmes correspondent à 0,35.',
    [SupplementalQuestion('bonus_cm2_frac_dec_1','Écris 7/10 sous forme décimale.',['0,7','0,07','7,0'],0,'Sept dixièmes s’écrivent 0,7.'), SupplementalQuestion('bonus_cm2_frac_dec_2','0,42 correspond à…',['42/10','42/100','4/100'],1,'0,42 représente 42 centièmes.'), SupplementalQuestion('bonus_cm2_frac_dec_3','Écris 9/100 sous forme décimale.',['0,9','0,09','0,99'],1,'Neuf centièmes s’écrivent 0,09.')]),
  SupplementalLesson('sixieme_etats_matiere', SchoolLevel.sixieme, 'Sciences', 'Identifier les états de la matière',
    'La matière peut se présenter principalement sous trois états : solide, liquide et gazeux. Un solide garde sa forme propre, un liquide prend la forme du récipient et un gaz occupe tout l’espace disponible.',
    'La glace est solide, l’eau du verre est liquide et la vapeur d’eau est à l’état gazeux.',
    [SupplementalQuestion('bonus_6e_matiere_1','Quel état garde une forme propre ?',['Solide','Liquide','Gazeux'],0,'Un solide garde sa forme propre.'), SupplementalQuestion('bonus_6e_matiere_2','Un liquide…',['garde toujours sa forme','prend la forme du récipient','remplit tout l’espace comme un gaz'],1,'Un liquide prend la forme du récipient qui le contient.'), SupplementalQuestion('bonus_6e_matiere_3','Quel état occupe tout l’espace disponible ?',['Solide','Liquide','Gazeux'],2,'Un gaz se répartit dans tout l’espace disponible.')]),
  SupplementalLesson('seconde_pourcentage_evolution', SchoolLevel.seconde, 'Mathématiques', 'Calculer une évolution en pourcentage',
    'Pour calculer une hausse de t %, on multiplie la valeur initiale par 1 + t/100. Pour une baisse de t %, on multiplie par 1 − t/100.',
    'Un prix de 8 000 F augmente de 10 % : 8 000 × 1,10 = 8 800 F.',
    [SupplementalQuestion('bonus_2nde_pct_1','Une valeur de 200 augmente de 5 %. Nouvelle valeur ?',['205','210','195'],1,'5 % de 200 vaut 10 ; 200 + 10 = 210.'), SupplementalQuestion('bonus_2nde_pct_2','Un prix de 500 baisse de 20 %. Il devient…',['400','480','600'],0,'20 % de 500 vaut 100 ; 500 − 100 = 400.'), SupplementalQuestion('bonus_2nde_pct_3','Le coefficient multiplicateur d’une hausse de 15 % est…',['0,15','1,15','1,5'],1,'Pour une hausse, le coefficient est 1 + 15/100 = 1,15.')]),

  SupplementalLesson('ce1_mesurer_longueurs', SchoolLevel.ce1, 'Mathématiques', 'Mesurer des longueurs',
    'La longueur peut se mesurer avec une règle ou un mètre. Le centimètre (cm) sert aux petits objets et le mètre (m) aux longueurs plus grandes. 1 m = 100 cm.',
    'Un ruban de 1 m et 25 cm mesure 125 cm au total.',
    [SupplementalQuestion('bonus_ce1_long_1','1 mètre équivaut à…',['10 cm','100 cm','1 000 cm'],1,'Un mètre contient 100 centimètres.'), SupplementalQuestion('bonus_ce1_long_2','Une règle de 30 cm mesure…',['0,3 m','3 m','30 m'],0,'30 cm = 30/100 m = 0,3 m.'), SupplementalQuestion('bonus_ce1_long_3','2 m et 15 cm font…',['215 cm','25 cm','2 015 cm'],0,'2 m = 200 cm ; 200 + 15 = 215 cm.')]),
  SupplementalLesson('cm2_volume_pave', SchoolLevel.cm2, 'Mathématiques', 'Calculer le volume d’un pavé droit',
    'Le volume d’un pavé droit se calcule en multipliant sa longueur par sa largeur et sa hauteur. Les dimensions doivent être exprimées dans la même unité.',
    'Longueur 5 cm, largeur 3 cm, hauteur 2 cm : V = 5 × 3 × 2 = 30 cm³.',
    [SupplementalQuestion('bonus_cm2_vol_1','Un pavé mesure 4 cm × 3 cm × 2 cm. Son volume est…',['24 cm³','9 cm³','12 cm²'],0,'V = 4 × 3 × 2 = 24 cm³.'), SupplementalQuestion('bonus_cm2_vol_2','Quelle formule calcule le volume d’un pavé droit ?',['L + l + h','L × l × h','L × l'],1,'On multiplie les trois dimensions.'), SupplementalQuestion('bonus_cm2_vol_3','Quelle unité convient pour un volume ?',['cm','cm²','cm³'],2,'Le volume s’exprime en unités cubiques.')]),
  SupplementalLesson('quatrieme_vitesse_moyenne', SchoolLevel.quatrieme, 'Physique-Chimie', 'Calculer une vitesse moyenne',
    'La vitesse moyenne se calcule en divisant la distance parcourue par la durée du trajet : v = d/t. Il faut utiliser des unités cohérentes, par exemple kilomètres et heures pour obtenir des km/h.',
    'Un véhicule parcourt 120 km en 2 h : v = 120 ÷ 2 = 60 km/h.',
    [SupplementalQuestion('bonus_4e_vit_1','Une voiture parcourt 150 km en 3 h. Sa vitesse moyenne est…',['50 km/h','45 km/h','150 km/h'],0,'v = 150 ÷ 3 = 50 km/h.'), SupplementalQuestion('bonus_4e_vit_2','Quelle formule donne la vitesse moyenne ?',['v = d × t','v = d ÷ t','v = t ÷ d'],1,'La vitesse moyenne est la distance divisée par la durée.'), SupplementalQuestion('bonus_4e_vit_3','À 40 km/h pendant 2 h, quelle distance parcourt-on ?',['20 km','42 km','80 km'],2,'d = v × t = 40 × 2 = 80 km.')]),

  SupplementalLesson('cp2_addition_retenue_dizaines', SchoolLevel.cp2, 'Mathématiques', 'Additionner avec une retenue',
    'Quand les unités totalisent 10 ou plus, on écrit les unités et on ajoute une dizaine aux dizaines. On calcule les colonnes de droite à gauche.',
    '27 + 15 : 7 + 5 = 12. On écrit 2 unités et on ajoute 1 dizaine. 2 + 1 + 1 = 4 dizaines. Résultat : 42.',
    [SupplementalQuestion('bonus_cp2_add_ret_1','Calcule 36 + 7.',['43','33','42'],0,'6 + 7 = 13 : on écrit 3 et on ajoute une dizaine.'), SupplementalQuestion('bonus_cp2_add_ret_2','Calcule 28 + 14.',['32','42','52'],1,'8 + 4 = 12 ; on écrit 2 et on ajoute 1 dizaine : 42.'), SupplementalQuestion('bonus_cp2_add_ret_3','Dans 19 + 5, le chiffre des unités du résultat est…',['2','4','1'],1,'19 + 5 = 24 : le chiffre des unités est 4.')]),
  SupplementalLesson('ce2_animaux_regimes_alimentaires', SchoolLevel.ce2, 'Sciences', 'Classer les animaux selon leur alimentation',
    'Les herbivores mangent des végétaux, les carnivores mangent d’autres animaux et les omnivores consomment des aliments d’origine végétale et animale.',
    'La vache est herbivore ; le lion est carnivore ; l’être humain est omnivore.',
    [SupplementalQuestion('bonus_ce2_regime_1','Le lion est généralement…',['Herbivore','Carnivore','Omnivore'],1,'Le lion se nourrit d’autres animaux.'), SupplementalQuestion('bonus_ce2_regime_2','Quel animal est herbivore ?',['La chèvre','Le crocodile','Le chat'],0,'La chèvre se nourrit principalement de végétaux.'), SupplementalQuestion('bonus_ce2_regime_3','Un omnivore mange…',['Seulement des plantes','Seulement de la viande','Des aliments végétaux et animaux'],2,'Un omnivore consomme les deux types d’aliments.')]),
  SupplementalLesson('cinquieme_proportionnalite_tableau', SchoolLevel.cinquieme, 'Mathématiques', 'Utiliser un tableau de proportionnalité',
    'Dans une situation de proportionnalité, on passe d’une ligne à l’autre en multipliant toujours par le même nombre : le coefficient de proportionnalité.',
    '3 cahiers coûtent 600 F. Un cahier coûte 600 ÷ 3 = 200 F ; 5 cahiers coûtent 5 × 200 = 1 000 F.',
    [SupplementalQuestion('bonus_5e_prop_1','4 stylos coûtent 800 F. Un stylo coûte…',['200 F','400 F','800 F'],0,'800 ÷ 4 = 200 F.'), SupplementalQuestion('bonus_5e_prop_2','Si 1 kg coûte 750 F, 3 kg coûtent…',['1 500 F','2 250 F','750 F'],1,'750 × 3 = 2 250 F.'), SupplementalQuestion('bonus_5e_prop_3','Le coefficient pour passer de 5 à 20 est…',['4','5','15'],0,'20 ÷ 5 = 4.')]),

  SupplementalLesson('cp1_nombres_ordonner', SchoolLevel.cp1, 'Mathématiques', 'Comparer et ranger les nombres',
    'Pour comparer deux nombres, on regarde d’abord lequel est le plus grand. On peut utiliser les signes <, > et =. Pour ranger plusieurs nombres, on les place du plus petit au plus grand ou du plus grand au plus petit.',
    'Avec 4, 9 et 6 : ordre croissant 4, 6, 9 ; ordre décroissant 9, 6, 4.',
    [SupplementalQuestion('bonus_cp1_ordre_1','Quel nombre est le plus grand ?',['7','5','3'],0,'7 est plus grand que 5 et 3.'), SupplementalQuestion('bonus_cp1_ordre_2','Complète : 8 … 6.',['<','>','='],1,'8 est plus grand que 6 : on écrit >.'), SupplementalQuestion('bonus_cp1_ordre_3','Range 2, 5, 1 du plus petit au plus grand.',['1, 2, 5','5, 2, 1','2, 1, 5'],0,'On commence par 1, puis 2, puis 5.')]),
  SupplementalLesson('cm2_conjugaison_futur', SchoolLevel.cm2, 'Français', 'Conjuguer les verbes au futur simple',
    'Le futur simple exprime une action qui se déroulera plus tard. Pour les verbes réguliers en -er, on garde l’infinitif et on ajoute : -ai, -as, -a, -ons, -ez, -ont.',
    'Demain, je chanterai ; tu chanteras ; nous chanterons.',
    [SupplementalQuestion('bonus_cm2_futur_1','Demain, nous … au marché. (aller)',['irons','allions','sommes allés'],0,'Le futur du verbe aller avec nous est irons.'), SupplementalQuestion('bonus_cm2_futur_2','Je … mes devoirs ce soir. (terminer)',['termine','terminerai','terminais'],1,'Au futur simple : je terminerai.'), SupplementalQuestion('bonus_cm2_futur_3','Ils … bientôt. (arriver)',['arrivent','arrivaient','arriveront'],2,'Le futur simple avec ils est arriveront.')]),
  SupplementalLesson('troisieme_gene_expression', SchoolLevel.troisieme, 'SVT', 'Comprendre les gènes et l’information héréditaire',
    'L’information héréditaire est portée par l’ADN, organisé en chromosomes dans le noyau de nombreuses cellules. Un gène est une portion d’ADN qui participe à la détermination d’un caractère ou à la fabrication d’un produit biologique.',
    'Les chromosomes portent l’ADN ; les gènes sont des segments de cet ADN.',
    [SupplementalQuestion('bonus_3e_gene_1','Quelle molécule porte l’information génétique ?',['ADN','Eau','Amidon'],0,'L’ADN porte l’information génétique.'), SupplementalQuestion('bonus_3e_gene_2','Où se trouvent les chromosomes dans une cellule humaine typique ?',['Dans le noyau','Dans l’air','À l’extérieur du corps'],0,'Les chromosomes sont généralement situés dans le noyau des cellules.'), SupplementalQuestion('bonus_3e_gene_3','Un gène est…',['Une cellule entière','Une portion d’ADN','Un organe'],1,'Un gène correspond à une portion d’ADN.')]),

  SupplementalLesson('cp2_monnaie_fcfa', SchoolLevel.cp2, 'Mathématiques', 'Calculer avec le franc CFA',
    'La monnaie utilisée au Togo est le franc CFA (F CFA). Pour calculer une dépense, on additionne les prix. Pour trouver la monnaie rendue, on soustrait le prix de la somme donnée.',
    'Un cahier coûte 250 F et un crayon coûte 100 F. Ensemble, ils coûtent 250 + 100 = 350 F. Si tu donnes 500 F, on te rend 500 - 350 = 150 F.',
    [SupplementalQuestion('bonus_cp2_fcfa_1','Un cahier coûte 250 F et un crayon 100 F. Quel est le prix total ?',['300 F','350 F','400 F'],1,'250 + 100 = 350 F.'),
     SupplementalQuestion('bonus_cp2_fcfa_2','Tu achètes un article à 300 F et tu donnes 500 F. Quelle somme doit-on te rendre ?',['100 F','200 F','300 F'],1,'500 - 300 = 200 F.'),
     SupplementalQuestion('bonus_cp2_fcfa_3','Deux oranges coûtent 50 F chacune. Combien coûtent-elles ?',['50 F','100 F','150 F'],1,'50 + 50 = 100 F.')]),
  SupplementalLesson('cp2_lire_heure_calendrier', SchoolLevel.cp2, 'Mathématiques', 'Lire l’heure et utiliser le calendrier',
    'Une journée compte 24 heures. Sur une horloge à aiguilles, la petite aiguille indique les heures et la grande aiguille les minutes. Le calendrier permet de repérer les jours de la semaine et les dates. Une semaine compte 7 jours.',
    'Quand la grande aiguille est sur 12 et la petite sur 8, il est 8 heures. Après lundi vient mardi.',
    [SupplementalQuestion('bonus_cp2_time_1','La petite aiguille est sur 8 et la grande sur 12. Quelle heure est-il ?',['8 heures','12 heures','6 heures'],0,'La grande aiguille sur 12 indique une heure exacte ; la petite indique 8.'), SupplementalQuestion('bonus_cp2_time_2','Quel jour vient après jeudi ?',['Mercredi','Vendredi','Dimanche'],1,'Dans l’ordre des jours, après jeudi vient vendredi.'), SupplementalQuestion('bonus_cp2_time_3','Combien de jours compte une semaine ?',['5 jours','6 jours','7 jours'],2,'Une semaine compte sept jours.')]),

  SupplementalLesson('ce1_achats_fcfa', SchoolLevel.ce1, 'Mathématiques', 'Préparer un petit achat en franc CFA',
    'Pour préparer un achat, lis le prix de chaque objet, additionne les dépenses et compare le total à la somme dont tu disposes. Si tu paies avec une somme plus grande, calcule la monnaie à recevoir.',
    'Un cahier coûte 300 F et un stylo 150 F. Le total est 300 + 150 = 450 F. Avec 1 000 F, la monnaie est 1 000 - 450 = 550 F.',
    [SupplementalQuestion('bonus_ce1_fcfa_1','Un cahier coûte 300 F et un stylo 150 F. Quel est le total ?',['400 F','450 F','500 F'],1,'300 + 150 = 450 F.'),
     SupplementalQuestion('bonus_ce1_fcfa_2','Tu paies 1 000 F pour un achat de 450 F. Quelle monnaie reçois-tu ?',['450 F','500 F','550 F'],2,'1 000 - 450 = 550 F.'),
     SupplementalQuestion('bonus_ce1_fcfa_3','Trois crayons coûtent 100 F chacun. Quel est leur prix total ?',['200 F','300 F','400 F'],1,'3 × 100 = 300 F.')]),

  SupplementalLesson('ce2_budget_fcfa', SchoolLevel.ce2, 'Mathématiques', 'Préparer un budget et vérifier la monnaie',
    'Un budget est une somme prévue pour acheter ce dont on a besoin. Additionne les prix pour connaître la dépense, puis soustrais cette dépense de la somme disponible pour trouver ce qu’il reste.',
    'Tu disposes de 1 500 F. Deux cahiers coûtent 400 F chacun et un stylo coûte 500 F. La dépense est 400 + 400 + 500 = 1 300 F. Il reste 1 500 - 1 300 = 200 F.',
    [SupplementalQuestion('bonus_ce2_budget_1','Tu as 1 500 F. Tu achètes deux cahiers à 400 F chacun et un stylo à 500 F. Combien dépenses-tu ?',['1 200 F','1 300 F','1 400 F'],1,'400 + 400 + 500 = 1 300 F.'),
     SupplementalQuestion('bonus_ce2_budget_2','Avec 1 500 F, après une dépense de 1 300 F, combien te reste-t-il ?',['100 F','200 F','300 F'],1,'1 500 - 1 300 = 200 F.'),
     SupplementalQuestion('bonus_ce2_budget_3','Tu as 1 000 F. Peux-tu acheter trois cahiers à 250 F chacun ?',['Oui, il reste 250 F','Non, il manque 250 F','Oui, il reste 500 F'],0,'3 × 250 = 750 F ; 1 000 - 750 = 250 F.')]),


  SupplementalLesson('ce2_mesures_longueurs', SchoolLevel.ce2, 'Mathématiques', 'Mesurer et convertir des longueurs',
    'On utilise le centimètre (cm) pour les petits objets, le mètre (m) pour les longueurs plus grandes et le kilomètre (km) pour les longues distances. 1 m = 100 cm et 1 km = 1 000 m.',
    'Une corde mesure 3 m et 40 cm. Comme 3 m = 300 cm, la corde mesure 300 + 40 = 340 cm.',
    [SupplementalQuestion('bonus_ce2_mesure_1','1 kilomètre équivaut à…',['100 m','1 000 m','10 000 m'],1,'1 km = 1 000 m.'),
     SupplementalQuestion('bonus_ce2_mesure_2','Une planche mesure 2 m et 50 cm. Quelle est sa longueur en centimètres ?',['205 cm','250 cm','2 050 cm'],1,'2 m = 200 cm ; 200 + 50 = 250 cm.'),
     SupplementalQuestion('bonus_ce2_mesure_3','Une corde mesure 340 cm. Cela correspond à…',['3 m et 40 cm','34 m','3 m et 4 cm'],0,'300 cm = 3 m ; il reste 40 cm.')]),


  SupplementalLesson('ce2_mesures_masses', SchoolLevel.ce2, 'Mathématiques', 'Mesurer et convertir des masses',
    'On utilise le gramme (g) pour les petites masses et le kilogramme (kg) pour les masses plus grandes. 1 kg = 1 000 g. Pour convertir des kilogrammes en grammes, on multiplie par 1 000.',
    'Un sac de riz pèse 2 kg. Comme 1 kg = 1 000 g, alors 2 kg = 2 000 g. Une masse de 1 500 g correspond à 1 kg et 500 g.',
    [SupplementalQuestion('bonus_ce2_masse_1','1 kilogramme équivaut à…',['100 g','1 000 g','10 000 g'],1,'1 kg = 1 000 g.'),
     SupplementalQuestion('bonus_ce2_masse_2','Un sac pèse 2 kg. Quelle est sa masse en grammes ?',['200 g','2 000 g','20 000 g'],1,'2 × 1 000 = 2 000 g.'),
     SupplementalQuestion('bonus_ce2_masse_3','1 500 g correspondent à…',['1 kg et 500 g','15 kg','1 kg et 50 g'],0,'1 000 g + 500 g = 1 500 g.')]),


  SupplementalLesson('ce2_mesures_capacites', SchoolLevel.ce2, 'Mathématiques', 'Mesurer des capacités : litre et millilitre',
    'Le litre (L) sert à mesurer la capacité des récipients. Le millilitre (mL) sert à mesurer de petites quantités de liquide. 1 L = 1 000 mL. Pour convertir des litres en millilitres, on multiplie par 1 000.',
    'Une bouteille contient 2 L d’eau. Cela correspond à 2 000 mL. Un demi-litre correspond à 500 mL.',
    [SupplementalQuestion('bonus_ce2_capacite_1','1 litre équivaut à…',['100 mL','1 000 mL','10 000 mL'],1,'1 L = 1 000 mL.'),
     SupplementalQuestion('bonus_ce2_capacite_2','Une bouteille contient 3 L. Quelle quantité cela représente-t-il en millilitres ?',['300 mL','3 000 mL','30 000 mL'],1,'3 × 1 000 = 3 000 mL.'),
     SupplementalQuestion('bonus_ce2_capacite_3','500 mL correspondent à…',['un demi-litre','5 litres','50 litres'],0,'500 mL est la moitié de 1 000 mL, donc un demi-litre.')]),


  SupplementalLesson('ce2_mesures_duree', SchoolLevel.ce2, 'Mathématiques', 'Lire l’heure et mesurer une durée',
    'Une heure contient 60 minutes. Pour convertir des heures en minutes, on multiplie par 60. Pour exprimer une durée en heures et minutes, on partage les minutes en groupes de 60.',
    '2 heures = 2 × 60 = 120 minutes. Donc 2 h 30 min = 120 + 30 = 150 minutes. Et 90 minutes = 60 minutes + 30 minutes = 1 h 30 min.',
    [SupplementalQuestion('bonus_ce2_duree_1','1 heure équivaut à…',['30 minutes','60 minutes','100 minutes'],1,'1 h = 60 min.'),
     SupplementalQuestion('bonus_ce2_duree_2','Combien de minutes y a-t-il dans 2 h 30 min ?',['120 min','150 min','230 min'],1,'2 × 60 + 30 = 150 min.'),
     SupplementalQuestion('bonus_ce2_duree_3','90 minutes correspondent à…',['1 h 30 min','9 h','1 h 9 min'],0,'90 min = 60 min + 30 min = 1 h 30 min.')]),


  SupplementalLesson('ce2_partage_division', SchoolLevel.ce2, 'Mathématiques', 'Partager en parts égales et découvrir la division',
    'Partager en parts égales signifie donner la même quantité à chaque personne. On peut utiliser une division pour trouver la quantité reçue par chacun. Par exemple, 12 objets partagés entre 3 enfants donnent 4 objets à chacun, car 3 × 4 = 12.',
    'Pour partager 15 mangues entre 5 personnes : 15 ÷ 5 = 3. Chaque personne reçoit 3 mangues.',
    [SupplementalQuestion('bonus_ce2_partage_1','12 crayons sont partagés également entre 3 élèves. Combien chacun reçoit-il ?',['3 crayons','4 crayons','5 crayons'],1,'12 ÷ 3 = 4 crayons.'),
     SupplementalQuestion('bonus_ce2_partage_2','15 mangues sont partagées entre 5 personnes. Combien chacun reçoit-il ?',['2 mangues','3 mangues','5 mangues'],1,'15 ÷ 5 = 3 mangues.'),
     SupplementalQuestion('bonus_ce2_partage_3','20 biscuits sont partagés également entre 4 enfants. Combien chacun reçoit-il ?',['4 biscuits','5 biscuits','6 biscuits'],1,'20 ÷ 4 = 5 biscuits.')]),


  SupplementalLesson('ce2_problemes_multiplication', SchoolLevel.ce2, 'Mathématiques', 'Résoudre des problèmes avec la multiplication',
    'Quand plusieurs groupes contiennent la même quantité, on peut utiliser une multiplication. Repère le nombre de groupes, puis la quantité dans chaque groupe. Multiplie ces deux nombres pour trouver le total.',
    'Exemple : 3 paquets contiennent chacun 4 cahiers. Il y a 3 groupes de 4 cahiers : 3 × 4 = 12 cahiers. On peut vérifier en additionnant 4 + 4 + 4 = 12.',
    [SupplementalQuestion('bonus_ce2_probleme_mult_1','Awa achète 3 paquets de 4 cahiers. Combien de cahiers a-t-elle ?',['7 cahiers','12 cahiers','14 cahiers'],1,'3 paquets de 4 : 3 × 4 = 12 cahiers.'),
     SupplementalQuestion('bonus_ce2_probleme_mult_2','Un vendeur prépare 5 paniers de 6 mangues. Combien de mangues utilise-t-il ?',['11 mangues','25 mangues','30 mangues'],2,'5 paniers de 6 : 5 × 6 = 30 mangues.'),
     SupplementalQuestion('bonus_ce2_probleme_mult_3','Il y a 4 boîtes contenant chacune 5 crayons. Combien y a-t-il de crayons ?',['20 crayons','9 crayons','25 crayons'],0,'4 boîtes de 5 : 4 × 5 = 20 crayons.')]),

  SupplementalLesson('ce2_table_multiplication_2', SchoolLevel.ce2, 'Mathématiques', 'Apprendre la table de 2',
    'Multiplier par 2, c’est compter de deux en deux ou ajouter deux fois le même nombre. Pour trouver 2 × 4, on peut calculer 2 + 2 + 2 + 2 = 8.',
    '2 × 1 = 2 ; 2 × 2 = 4 ; 2 × 3 = 6 ; 2 × 4 = 8 ; 2 × 5 = 10.',
    [SupplementalQuestion('bonus_ce2_table2_1','2 × 2 = ?',['2','4','6'],1,'2 + 2 = 4.'),
     SupplementalQuestion('bonus_ce2_table2_2','2 × 4 = ?',['6','8','10'],1,'2 + 2 + 2 + 2 = 8.'),
     SupplementalQuestion('bonus_ce2_table2_3','2 × 5 = ?',['8','10','12'],1,'5 groupes de 2 font 10.')]),

  SupplementalLesson('ce2_table_multiplication_3', SchoolLevel.ce2, 'Mathématiques', 'Apprendre la table de 3',
    'Multiplier par 3, c’est ajouter trois fois le même nombre ou compter de trois en trois. Pour trouver 3 × 4, on peut calculer 3 + 3 + 3 + 3 = 12.',
    '3 × 1 = 3 ; 3 × 2 = 6 ; 3 × 3 = 9 ; 3 × 4 = 12 ; 3 × 5 = 15.',
    [SupplementalQuestion('bonus_ce2_table3_1','3 × 2 = ?',['5','6','8'],1,'3 + 3 = 6.'),
     SupplementalQuestion('bonus_ce2_table3_2','3 × 4 = ?',['10','12','14'],1,'3 + 3 + 3 + 3 = 12.'),
     SupplementalQuestion('bonus_ce2_table3_3','3 × 5 = ?',['12','15','18'],1,'3 + 3 + 3 + 3 + 3 = 15.')]),


  SupplementalLesson('ce2_table_multiplication_4', SchoolLevel.ce2, 'Mathématiques', 'Apprendre la table de 4',
    'Multiplier par 4, c’est ajouter quatre fois le même nombre ou compter de quatre en quatre. Pour trouver 4 × 3, on peut calculer 4 + 4 + 4 = 12.',
    '4 × 1 = 4 ; 4 × 2 = 8 ; 4 × 3 = 12 ; 4 × 4 = 16 ; 4 × 5 = 20.',
    [SupplementalQuestion('bonus_ce2_table4_1','4 × 2 = ?',['6','8','10'],1,'4 + 4 = 8.'),
     SupplementalQuestion('bonus_ce2_table4_2','4 × 3 = ?',['10','12','14'],1,'4 + 4 + 4 = 12.'),
     SupplementalQuestion('bonus_ce2_table4_3','4 × 5 = ?',['16','20','24'],1,'4 + 4 + 4 + 4 + 4 = 20.')]),

  SupplementalLesson('ce2_table_multiplication_5', SchoolLevel.ce2, 'Mathématiques', 'Apprendre la table de 5',
    'Multiplier par 5, c’est compter de cinq en cinq. Les résultats se terminent toujours par 0 ou 5. Pour trouver 5 × 4, on ajoute 5 quatre fois : 5 + 5 + 5 + 5 = 20.',
    '5 × 1 = 5 ; 5 × 2 = 10 ; 5 × 3 = 15 ; 5 × 4 = 20 ; 5 × 5 = 25.',
    [SupplementalQuestion('bonus_ce2_table5_1','5 × 2 = ?',['10','12','15'],0,'5 + 5 = 10.'),
     SupplementalQuestion('bonus_ce2_table5_2','5 × 4 = ?',['15','20','25'],1,'5 + 5 + 5 + 5 = 20.'),
     SupplementalQuestion('bonus_ce2_table5_3','5 × 5 = ?',['20','25','30'],1,'5 groupes de 5 font 25.')]),

  SupplementalLesson('ce2_table_multiplication_6', SchoolLevel.ce2, 'Mathématiques', 'Apprendre la table de 6',
    'Multiplier par 6, c’est compter de six en six ou additionner six fois le même nombre. Pour trouver 6 × 4, on peut calculer 6 + 6 + 6 + 6 = 24.',
    '6 × 1 = 6 ; 6 × 2 = 12 ; 6 × 3 = 18 ; 6 × 4 = 24 ; 6 × 5 = 30.',
    [SupplementalQuestion('bonus_ce2_table6_1','6 × 2 = ?',['10','12','14'],1,'6 + 6 = 12.'),
     SupplementalQuestion('bonus_ce2_table6_2','6 × 4 = ?',['18','24','30'],1,'6 + 6 + 6 + 6 = 24.'),
     SupplementalQuestion('bonus_ce2_table6_3','6 × 5 = ?',['25','30','36'],1,'5 groupes de 6 font 30.')]),


  SupplementalLesson('ce2_table_multiplication_7', SchoolLevel.ce2, 'Mathématiques', 'Apprendre la table de 7',
    'Multiplier par 7, c’est compter de sept en sept. Pour trouver 7 × 4, on peut additionner 7 + 7 + 7 + 7 = 28.',
    '7 × 1 = 7 ; 7 × 2 = 14 ; 7 × 3 = 21 ; 7 × 4 = 28 ; 7 × 5 = 35.',
    [SupplementalQuestion('bonus_ce2_table7_1','7 × 2 = ?',['12','14','16'],1,'7 + 7 = 14.'),
     SupplementalQuestion('bonus_ce2_table7_2','7 × 4 = ?',['21','28','35'],1,'7 + 7 + 7 + 7 = 28.'),
     SupplementalQuestion('bonus_ce2_table7_3','7 × 5 = ?',['30','35','40'],1,'5 groupes de 7 font 35.')]),


  SupplementalLesson('ce2_table_multiplication_8', SchoolLevel.ce2, 'Mathématiques', 'Apprendre la table de 8',
    'Multiplier par 8, c’est compter de huit en huit. Pour trouver 8 × 4, on peut additionner 8 + 8 + 8 + 8 = 32.',
    '8 × 1 = 8 ; 8 × 2 = 16 ; 8 × 3 = 24 ; 8 × 4 = 32 ; 8 × 5 = 40.',
    [SupplementalQuestion('bonus_ce2_table8_1','8 × 2 = ?',['14','16','18'],1,'8 + 8 = 16.'),
     SupplementalQuestion('bonus_ce2_table8_2','8 × 4 = ?',['24','32','40'],1,'8 + 8 + 8 + 8 = 32.'),
     SupplementalQuestion('bonus_ce2_table8_3','8 × 5 = ?',['35','40','45'],1,'5 groupes de 8 font 40.')]),

  SupplementalLesson('ce2_table_multiplication_9', SchoolLevel.ce2, 'Mathématiques', 'Apprendre la table de 9',
    'Multiplier par 9, c’est compter de neuf en neuf. Pour trouver 9 × 4, on peut additionner 9 + 9 + 9 + 9 = 36.',
    '9 × 1 = 9 ; 9 × 2 = 18 ; 9 × 3 = 27 ; 9 × 4 = 36 ; 9 × 5 = 45.',
    [SupplementalQuestion('bonus_ce2_table9_1','9 × 2 = ?',['16','18','20'],1,'9 + 9 = 18.'),
     SupplementalQuestion('bonus_ce2_table9_2','9 × 4 = ?',['27','36','45'],1,'9 + 9 + 9 + 9 = 36.'),
     SupplementalQuestion('bonus_ce2_table9_3','9 × 5 = ?',['40','45','50'],1,'5 groupes de 9 font 45.')]),

  SupplementalLesson('ce2_table_multiplication_10', SchoolLevel.ce2, 'Mathématiques', 'Apprendre la table de 10',
    'Multiplier par 10, c’est ajouter un zéro au nombre entier. Pour trouver 10 × 4, on compte quatre dizaines : 40.',
    '10 × 1 = 10 ; 10 × 2 = 20 ; 10 × 3 = 30 ; 10 × 4 = 40 ; 10 × 5 = 50.',
    [SupplementalQuestion('bonus_ce2_table10_1','10 × 2 = ?',['10','20','30'],1,'Deux dizaines font 20.'),
     SupplementalQuestion('bonus_ce2_table10_2','10 × 4 = ?',['30','40','50'],1,'Quatre dizaines font 40.'),
     SupplementalQuestion('bonus_ce2_table10_3','10 × 5 = ?',['40','50','60'],1,'Cinq dizaines font 50.')]),


  SupplementalLesson('ce2_choisir_operation', SchoolLevel.ce2, 'Mathématiques', 'Choisir la bonne opération dans un problème',
    'Avant de calculer, demande-toi ce qui se passe. Si on réunit des quantités, on additionne (+). Si on cherche ce qui reste ou la différence, on soustrait (−). Si plusieurs groupes ont la même quantité, on multiplie (×). Si on partage en parts égales, on divise (÷). Lis toute la situation : un seul mot ne suffit pas toujours pour choisir.',
    'Exemple : Afi a 200 F et reçoit encore 100 F. Les sommes sont réunies : on additionne. 200 + 100 = 300 F.',
    [SupplementalQuestion('bonus_ce2_operation_1','Kossi a 125 F. Sa sœur lui donne encore 75 F. Quelle opération faut-il choisir pour trouver la somme totale ?',['Addition (+)','Soustraction (−)','Multiplication (×)'],0,'On réunit 125 F et 75 F : addition. 125 + 75 = 200 F.'),
     SupplementalQuestion('bonus_ce2_operation_2','Ama a 500 F. Elle dépense 200 F. Quelle opération faut-il choisir pour connaître son argent restant ?',['Addition (+)','Soustraction (−)','Division (÷)'],1,'On cherche ce qui reste après une dépense : soustraction. 500 − 200 = 300 F.'),
     SupplementalQuestion('bonus_ce2_operation_3','Il y a 4 sachets contenant chacun 6 bonbons. Quelle opération faut-il choisir pour trouver le total ?',['Soustraction (−)','Multiplication (×)','Division (÷)'],1,'Il y a plusieurs groupes égaux : multiplication. 4 × 6 = 24 bonbons.'),
     SupplementalQuestion('bonus_ce2_operation_4','18 mangues sont partagées également entre 3 enfants. Quelle opération faut-il choisir ?',['Addition (+)','Multiplication (×)','Division (÷)'],2,'On partage en parts égales : division. 18 ÷ 3 = 6 mangues par enfant.')]),
  SupplementalLesson('ce2_figures_geometriques', SchoolLevel.ce2, 'Mathématiques', 'Reconnaître les figures géométriques planes',
    'Une figure plane est une forme dessinée sur une feuille. Le triangle a 3 côtés. Le carré a 4 côtés égaux et 4 angles droits. Le rectangle a 4 côtés et ses côtés opposés sont égaux. Le cercle est rond et n’a ni côté droit ni sommet.',
    'Un panneau triangulaire a 3 côtés. Un carreau carré a 4 côtés égaux. Une porte rectangulaire a 4 côtés.',
    [SupplementalQuestion('bonus_ce2_geo_1','Combien de côtés possède un triangle ?',['2','3','4'],1,'Un triangle possède 3 côtés.'),
     SupplementalQuestion('bonus_ce2_geo_2','Quelle figure a 4 côtés égaux et 4 angles droits ?',['Le carré','Le cercle','Le triangle'],0,'Le carré a quatre côtés de même longueur et quatre angles droits.'),
     SupplementalQuestion('bonus_ce2_geo_3','Quelle figure est ronde et n’a pas de sommet ?',['Le rectangle','Le triangle','Le cercle'],2,'Le cercle est rond et ne possède aucun sommet.'),
     SupplementalQuestion('bonus_ce2_geo_4','Dans un rectangle, quels côtés ont la même longueur ?',['Tous les côtés sont toujours égaux','Les côtés opposés','Aucun côté'],1,'Dans un rectangle, les côtés opposés ont la même longueur.')]),
  SupplementalLesson('ce2_moitie_quart', SchoolLevel.ce2, 'Mathématiques', 'Comprendre la moitié et le quart',
    'Partager en deux parts égales, c’est chercher la moitié. La moitié d’une quantité se calcule en divisant par 2. Partager en quatre parts égales, c’est chercher le quart. Le quart d’une quantité se calcule en divisant par 4. Chaque part doit avoir la même quantité.',
    'La moitié de 12 mangues est 12 ÷ 2 = 6 mangues. Le quart de 12 mangues est 12 ÷ 4 = 3 mangues.',
    [SupplementalQuestion('bonus_ce2_fraction_1','Quelle est la moitié de 10 ?',['2','5','8'],1,'10 ÷ 2 = 5. La moitié de 10 est 5.'),
     SupplementalQuestion('bonus_ce2_fraction_2','Quel est le quart de 12 ?',['3','4','6'],0,'12 ÷ 4 = 3. Le quart de 12 est 3.'),
     SupplementalQuestion('bonus_ce2_fraction_3','On partage 8 biscuits en 2 parts égales. Combien y a-t-il de biscuits dans chaque part ?',['2','4','6'],1,'8 ÷ 2 = 4 biscuits dans chaque part.'),
     SupplementalQuestion('bonus_ce2_fraction_4','On partage 20 oranges en 4 paniers égaux. Combien d’oranges dans chaque panier ?',['4','5','10'],1,'20 ÷ 4 = 5 oranges dans chaque panier.')]),

  SupplementalLesson('ce2_nombres_jusqua_1000', SchoolLevel.ce2, 'Mathématiques', 'Lire et décomposer les nombres jusqu’à 1 000',
    'Un nombre peut être formé de centaines, de dizaines et d’unités. 100 unités font 1 centaine. 10 dizaines font 1 centaine. Pour lire un nombre, on lit d’abord les centaines, puis les dizaines et les unités. Le zéro peut indiquer qu’une position est vide.',
    'Dans 347, il y a 3 centaines, 4 dizaines et 7 unités : 347 = 300 + 40 + 7. Dans 506, il y a 5 centaines, 0 dizaine et 6 unités : 506 = 500 + 6.',
    [SupplementalQuestion('bonus_ce2_nombre_1','Combien de centaines y a-t-il dans 428 ?',['4','2','8'],0,'428 contient 4 centaines.'),
     SupplementalQuestion('bonus_ce2_nombre_2','Quelle décomposition correspond à 365 ?',['300 + 6 + 5','300 + 60 + 5','30 + 60 + 5'],1,'365 = 300 + 60 + 5.'),
     SupplementalQuestion('bonus_ce2_nombre_3','Quel nombre correspond à 7 centaines, 0 dizaine et 9 unités ?',['790','709','79'],1,'7 centaines et 9 unités donnent 709.'),
     SupplementalQuestion('bonus_ce2_nombre_4','Comment écrit-on « cinq cent vingt » en chiffres ?',['502','520','250'],1,'Cinq cent vingt s’écrit 520.')]),
  SupplementalLesson('ce2_comparer_nombres_1000', SchoolLevel.ce2, 'Mathématiques', 'Comparer et ranger les nombres jusqu’à 1 000',
    'Pour comparer deux nombres, regarde d’abord le nombre de centaines. Si les centaines sont égales, compare les dizaines. Si les dizaines sont aussi égales, compare les unités. Le signe < signifie « plus petit que », le signe > signifie « plus grand que » et le signe = signifie « égal à ». Pour ranger des nombres dans l’ordre croissant, on va du plus petit au plus grand.',
    '472 > 427 car les centaines sont égales (4), mais 7 dizaines est supérieur à 2 dizaines. Dans l’ordre croissant : 215, 251, 512.',
    [SupplementalQuestion('bonus_ce2_compare_1','Quel signe convient : 348 __ 384 ?',['>','<','='],1,'348 est plus petit que 384 : 348 < 384.'),
     SupplementalQuestion('bonus_ce2_compare_2','Quel nombre est le plus grand ?',['609','690','906'],2,'906 possède 9 centaines, donc il est le plus grand.'),
     SupplementalQuestion('bonus_ce2_compare_3','Quel est l’ordre croissant ?',['430, 403, 340','340, 403, 430','403, 340, 430'],1,'On commence par 340, puis 403, puis 430.'),
     SupplementalQuestion('bonus_ce2_compare_4','Complète : 725 __ 725.',['<','>','='],2,'Les deux nombres sont identiques : 725 = 725.')]),
  SupplementalLesson('ce2_addition_soustraction_1000', SchoolLevel.ce2, 'Mathématiques', 'Additionner et soustraire jusqu’à 1 000',
    'Pour additionner, on peut réunir les centaines, les dizaines et les unités. Pour soustraire, on enlève une quantité ou on cherche la différence. Quand une colonne dépasse 9 unités, on échange 10 unités contre 1 dizaine. Quand il manque des unités, on peut échanger 1 dizaine contre 10 unités.',
    '246 + 132 = 378. On calcule 200 + 100 = 300, 40 + 30 = 70 et 6 + 2 = 8. Donc 300 + 70 + 8 = 378. Pour 452 − 131 : 400 − 100 = 300, 50 − 30 = 20 et 2 − 1 = 1. Résultat : 321.',
    [SupplementalQuestion('bonus_ce2_addsub_1','Calcule : 235 + 142.',['367','377','387'],1,'235 + 142 = 377.'),
     SupplementalQuestion('bonus_ce2_addsub_2','Calcule : 326 + 158.',['474','484','494'],1,'326 + 158 = 484.'),
     SupplementalQuestion('bonus_ce2_addsub_3','Calcule : 568 − 243.',['325','335','345'],0,'568 − 243 = 325.'),
     SupplementalQuestion('bonus_ce2_addsub_4','Calcule : 700 − 265.',['435','445','425'],0,'700 − 265 = 435.')]),
  SupplementalLesson('ce2_multiplication_posee', SchoolLevel.ce2, 'Mathématiques', 'Multiplier un nombre par un chiffre',
    'Pour multiplier un nombre par un chiffre, on commence par les unités, puis les dizaines et enfin les centaines. Si un résultat dépasse 9, on écrit le chiffre des unités et on reporte les dizaines dans la colonne suivante. On vérifie ensuite le résultat en estimant ou en additionnant les groupes.',
    '124 × 3 : 4 × 3 = 12, j’écris 2 et je retiens 1 dizaine. 2 dizaines × 3 = 6 dizaines, plus la dizaine retenue = 7 dizaines. 1 centaine × 3 = 3 centaines. Donc 124 × 3 = 372.',
    [SupplementalQuestion('bonus_ce2_multposee_1','Calcule : 124 × 3.',['362','372','382'],1,'124 × 3 = 372.'),
     SupplementalQuestion('bonus_ce2_multposee_2','Calcule : 213 × 4.',['842','852','862'],1,'213 × 4 = 852.'),
     SupplementalQuestion('bonus_ce2_multposee_3','Calcule : 132 × 5.',['650','660','670'],1,'132 × 5 = 660.'),
     SupplementalQuestion('bonus_ce2_multposee_4','Calcule : 206 × 3.',['618','608','628'],0,'206 × 3 = 618.')]),
  SupplementalLesson('ce2_division_exacte', SchoolLevel.ce2, 'Mathématiques', 'Diviser exactement par un chiffre',
    'Diviser, c’est partager une quantité en parts égales ou former des groupes égaux. Dans une division exacte, il ne reste rien. Pour vérifier, multiplie le nombre de chaque part par le nombre de parts : tu dois retrouver la quantité de départ.',
    '24 ÷ 3 = 8 : 24 objets partagés entre 3 élèves donnent 8 objets à chacun. Vérification : 8 × 3 = 24.',
    [SupplementalQuestion('bonus_ce2_division_exacte_1','Calcule : 24 ÷ 3.',['6','8','9'],1,'24 partagé en 3 parts égales donne 8 dans chaque part. 8 × 3 = 24.'),
     SupplementalQuestion('bonus_ce2_division_exacte_2','Calcule : 36 ÷ 4.',['8','9','10'],1,'36 partagé en 4 parts égales donne 9. 9 × 4 = 36.'),
     SupplementalQuestion('bonus_ce2_division_exacte_3','Calcule : 42 ÷ 6.',['6','7','8'],1,'42 partagé en 6 parts égales donne 7. 7 × 6 = 42.'),
     SupplementalQuestion('bonus_ce2_division_exacte_4','Calcule : 56 ÷ 7.',['7','8','9'],1,'56 partagé en 7 parts égales donne 8. 8 × 7 = 56.')]),
  SupplementalLesson('ce2_problemes_partage_fcfa', SchoolLevel.ce2, 'Mathématiques', 'Résoudre des problèmes de partage en francs CFA',
    'Dans un problème de partage, on distribue une somme en parts égales. On divise la somme totale par le nombre de personnes. Chaque personne reçoit la même somme. Pour vérifier, multiplie la somme reçue par le nombre de personnes.',
    'Afi partage 600 F entre 3 enfants. 600 ÷ 3 = 200 F. Chaque enfant reçoit 200 F. Vérification : 200 × 3 = 600 F.',
    [SupplementalQuestion('bonus_ce2_partage_fcfa_1','On partage 600 F entre 3 enfants. Combien reçoit chaque enfant ?',['100 F','200 F','300 F'],1,'600 ÷ 3 = 200 F pour chaque enfant.'),
     SupplementalQuestion('bonus_ce2_partage_fcfa_2','Quatre élèves se partagent 1 200 F également. Quelle somme reçoit chacun ?',['200 F','300 F','400 F'],1,'1 200 ÷ 4 = 300 F pour chaque élève.'),
     SupplementalQuestion('bonus_ce2_partage_fcfa_3','Trois frères partagent 900 F également. Combien reçoit chacun ?',['200 F','300 F','400 F'],1,'900 ÷ 3 = 300 F pour chaque frère.'),
     SupplementalQuestion('bonus_ce2_partage_fcfa_4','Cinq enfants se partagent 1 500 F également. Combien reçoit chacun ?',['200 F','300 F','500 F'],1,'1 500 ÷ 5 = 300 F pour chaque enfant.')]),
  SupplementalLesson('ce2_problemes_deux_etapes', SchoolLevel.ce2, 'Mathématiques', 'Résoudre un problème en deux étapes',
    'Certains problèmes demandent deux opérations. Lis toute la situation, trouve d’abord ce qu’il faut calculer, puis utilise le résultat pour répondre à la question finale. Tu peux souligner les nombres utiles et vérifier chaque étape.',
    'Une vendeuse a 125 mangues. Elle en reçoit 48, puis vend 37 mangues. D’abord : 125 + 48 = 173 mangues. Ensuite : 173 − 37 = 136 mangues. Il lui reste 136 mangues.',
    [SupplementalQuestion('bonus_ce2_deux_etapes_1','Awa a 125 mangues et en reçoit 48. Elle en vend 37. Combien lui en reste-t-il ?',['126','136','146'],1,'125 + 48 = 173, puis 173 − 37 = 136 mangues.'),
     SupplementalQuestion('bonus_ce2_deux_etapes_2','Kossi a 250 F. Il reçoit 150 F puis dépense 175 F. Combien lui reste-t-il ?',['215 F','225 F','235 F'],1,'250 + 150 = 400 F, puis 400 − 175 = 225 F.'),
     SupplementalQuestion('bonus_ce2_deux_etapes_3','Une classe reçoit 6 rangées de 8 livres. Elle en prête 12. Combien de livres restent ?',['34','36','38'],1,'6 × 8 = 48 livres, puis 48 − 12 = 36 livres.'),
     SupplementalQuestion('bonus_ce2_deux_etapes_4','Un vendeur a 4 paniers de 15 oranges. Il vend 18 oranges. Combien lui en reste-t-il ?',['40','42','44'],1,'4 × 15 = 60 oranges, puis 60 − 18 = 42 oranges.')]),
  SupplementalLesson('ce2_problemes_multiplication_soustraction', SchoolLevel.ce2, 'Mathématiques', 'Multiplier puis soustraire dans un problème',
    'Pour résoudre certains problèmes, il faut d’abord calculer le nombre total d’objets dans des groupes égaux. Ensuite, on enlève les objets vendus, utilisés ou distribués. Fais les opérations dans l’ordre et écris une phrase réponse.',
    'Une boutique reçoit 5 cartons contenant chacun 12 cahiers. Elle vend 18 cahiers. D’abord : 5 × 12 = 60 cahiers. Ensuite : 60 − 18 = 42 cahiers. Il reste 42 cahiers.',
    [SupplementalQuestion('bonus_ce2_mult_soust_1','Une boutique reçoit 5 cartons de 12 cahiers et en vend 18. Combien reste-t-il de cahiers ?',['40','42','44'],1,'5 × 12 = 60, puis 60 − 18 = 42 cahiers.'),
     SupplementalQuestion('bonus_ce2_mult_soust_2','Un jardinier plante 4 rangées de 15 fleurs. 17 fleurs fanent. Combien restent en bon état ?',['41','43','45'],1,'4 × 15 = 60, puis 60 − 17 = 43 fleurs.'),
     SupplementalQuestion('bonus_ce2_mult_soust_3','Une école achète 6 paquets de 10 crayons. Elle distribue 25 crayons. Combien restent ?',['30','35','40'],1,'6 × 10 = 60, puis 60 − 25 = 35 crayons.'),
     SupplementalQuestion('bonus_ce2_mult_soust_4','Un commerçant range 3 paniers de 24 oranges. Il vend 20 oranges. Combien lui en reste-t-il ?',['50','52','54'],1,'3 × 24 = 72, puis 72 − 20 = 52 oranges.')]),
  SupplementalLesson('cp2_regle_graduee', SchoolLevel.cp2, 'Mathématiques', 'Utiliser une règle graduée',
    'Pour mesurer une longueur, place le zéro de la règle au début de l’objet. Garde la règle droite et lis le nombre indiqué à l’autre extrémité. Les graduations numérotées de la règle sont en centimètres (cm). Si le bord de la règle est abîmé ou si le zéro n’est pas au bord, commence toujours au repère 0, pas au bord de la règle.',
    'Un crayon commence au repère 0 cm et se termine au repère 8 cm : sa longueur est 8 cm. Si un objet commence au repère 2 cm et se termine au repère 7 cm, sa longueur est 7 − 2 = 5 cm.',
    [SupplementalQuestion('bonus_cp2_regle_1','Le début d’un objet est placé sur 0 cm et sa fin sur 6 cm. Quelle est sa longueur ?',['4 cm','6 cm','8 cm'],1,'La longueur se lit entre 0 cm et 6 cm : 6 cm.'),
     SupplementalQuestion('bonus_cp2_regle_2','Un objet commence au repère 3 cm et finit au repère 9 cm. Quelle est sa longueur ?',['6 cm','9 cm','12 cm'],0,'On calcule 9 − 3 = 6 cm.'),
     SupplementalQuestion('bonus_cp2_regle_3','Pour mesurer correctement avec une règle, quel repère faut-il placer au début de l’objet ?',['Le repère 0','Le repère 5','N’importe quel repère sans calcul'],0,'On place le repère 0 au début, puis on lit la longueur à l’autre extrémité.'),
     SupplementalQuestion('bonus_cp2_regle_4','Une longueur va du repère 1 cm au repère 7 cm. Quelle est sa mesure ?',['5 cm','6 cm','7 cm'],1,'7 − 1 = 6 cm.')]),
  SupplementalLesson('cp2_nom_propre_commun', SchoolLevel.cp2, 'Français', 'Distinguer le nom propre et le nom commun',
    'Le nom commun désigne une personne, un animal, un lieu ou une chose de manière générale : une fille, un chien, une ville. Le nom propre désigne une personne ou un lieu précis : Afi, Kossi, Lomé. Il commence par une majuscule. Le nom commun prend aussi une majuscule lorsqu’il est au début d’une phrase, mais ce n’est pas ce qui en fait un nom propre.',
    'Dans « Afi habite à Lomé », Afi et Lomé sont des noms propres. « fille », « chien » et « ville » sont des noms communs.',
    [SupplementalQuestion('bonus_cp2_nom_1','Quel mot est un nom propre ?',['école','Kossi','garçon'],1,'Kossi est le nom précis d’une personne : c’est un nom propre.'),
     SupplementalQuestion('bonus_cp2_nom_2','Quel mot est un nom commun ?',['Lomé','Afi','marché'],2,'Marché désigne un lieu en général : c’est un nom commun.'),
     SupplementalQuestion('bonus_cp2_nom_3','Dans « Ama voit un chat », quel mot est un nom propre ?',['Ama','voit','chat'],0,'Ama désigne une personne précise et commence par une majuscule : nom propre.'),
     SupplementalQuestion('bonus_cp2_nom_4','Quel groupe contient seulement des noms communs ?',['Kossi, Lomé','fille, école','Afi, marché'],1,'Fille et école désignent des catégories : ce sont deux noms communs.')]),
  SupplementalLesson('cp2_reconnaitre_verbe', SchoolLevel.cp2, 'Français', 'Reconnaître le verbe dans une phrase',
    'Le verbe indique souvent ce que fait une personne, un animal ou une chose, ou dans quel état elle se trouve. Pour le trouver, demande-toi : « Que fait le sujet ? » Le verbe change selon le sujet et le temps. Exemple : Afi chante. Le mot « chante » indique ce qu’Afi fait.',
    'Dans « Le chien court », le chien est celui qui fait l’action. Le verbe est « court ». Dans « Les enfants jouent », le verbe est « jouent ».',
    [SupplementalQuestion('bonus_cp2_verbe_1','Dans « Ama danse », quel est le verbe ?',['Ama','danse','la'],1,'« Danse » indique ce qu’Ama fait : c’est le verbe.'),
     SupplementalQuestion('bonus_cp2_verbe_2','Dans « Le bébé dort », quel mot indique l’action ?',['bébé','le','dort'],2,'« Dort » indique ce que fait le bébé : c’est le verbe.'),
     SupplementalQuestion('bonus_cp2_verbe_3','Choisis le verbe dans la phrase : « Les élèves écrivent. »',['élèves','écrivent','les'],1,'« Écrivent » est le verbe de la phrase.'),
     SupplementalQuestion('bonus_cp2_verbe_4','Dans « Le soleil brille », quel est le verbe ?',['soleil','brille','le'],1,'« Brille » indique ce que fait le soleil dans cette phrase.')]),
  SupplementalLesson('cp2_singulier_pluriel', SchoolLevel.cp2, 'Français', 'Reconnaître le singulier et le pluriel',
    'Le singulier désigne une seule personne, un seul animal ou une seule chose : un chat, la maison. Le pluriel désigne plusieurs personnes, animaux ou choses : des chats, les maisons. Les mots les et des indiquent souvent le pluriel. Beaucoup de noms prennent un s au pluriel, mais certains mots changent autrement.',
    '« Une fleur » est au singulier : il y a une fleur. « Des fleurs » est au pluriel : il y en a plusieurs. Dans « Les enfants jouent », le groupe « les enfants » est au pluriel.',
    [SupplementalQuestion('bonus_cp2_pluriel_1','« un chat » est au…',['singulier','pluriel','verbe'],0,'« Un chat » désigne un seul chat : singulier.'),
     SupplementalQuestion('bonus_cp2_pluriel_2','« des fleurs » est au…',['singulier','pluriel','adjectif'],1,'« Des fleurs » désigne plusieurs fleurs : pluriel.'),
     SupplementalQuestion('bonus_cp2_pluriel_3','Quel groupe est au pluriel ?',['la table','les tables','une table'],1,'« Les tables » désigne plusieurs tables : pluriel.'),
     SupplementalQuestion('bonus_cp2_pluriel_4','Complète : « ___ enfants jouent. »',['Le','Les','Un'],1,'« Les » accompagne un nom pluriel : les enfants.')]),
  SupplementalLesson('cp2_reconnaitre_figures_planes', SchoolLevel.cp2, 'Mathématiques', 'Reconnaître quelques figures géométriques',
    'Une figure géométrique est une forme. Le triangle a 3 côtés. Le carré a 4 côtés de même longueur et 4 angles droits. Le rectangle a 4 côtés et 4 angles droits ; ses côtés opposés ont la même longueur. Le cercle est rond et son contour est courbe.',
    'Observe les formes : un panneau triangulaire peut avoir la forme d’un triangle ; une fenêtre peut avoir la forme d’un rectangle ; une pièce ronde peut avoir la forme d’un cercle.',
    [SupplementalQuestion('bonus_cp2_figures_1','Combien de côtés possède un triangle ?',['2','3','4'],1,'Un triangle possède 3 côtés.'),
     SupplementalQuestion('bonus_cp2_figures_2','Quelle figure a 4 côtés de même longueur et 4 angles droits ?',['Le cercle','Le rectangle','Le carré'],2,'Le carré a 4 côtés égaux et 4 angles droits.'),
     SupplementalQuestion('bonus_cp2_figures_3','Quelle figure a un contour courbe et aucun côté droit ?',['Le cercle','Le triangle','Le carré'],0,'Le contour du cercle est courbe : il ne possède pas de côté droit.'),
     SupplementalQuestion('bonus_cp2_figures_4','Combien de côtés possède un rectangle ?',['3','4','5'],1,'Un rectangle possède 4 côtés.')]),
  SupplementalLesson('cp2_etapes_addition_soustraction', SchoolLevel.cp2, 'Mathématiques', 'Résoudre un problème avec une addition ou une soustraction',
    'Lis le problème jusqu’au bout et cherche ce que l’on te demande. Si on ajoute, on fait une addition (+). Si on enlève ou si l’on cherche ce qui reste, on fait une soustraction (−). Choisis l’opération, calcule, puis écris la réponse avec son unité.',
    'Afi a 12 mangues. Sa mère lui en donne 5. On ajoute : 12 + 5 = 17. Afi a maintenant 17 mangues. Kossi a 18 billes et en perd 4. On enlève : 18 − 4 = 14. Il lui reste 14 billes.',
    [SupplementalQuestion('bonus_cp2_probleme_op_1','Ama a 9 oranges. Elle en reçoit 6. Combien en a-t-elle maintenant ?',['3','15','16'],1,'On ajoute les oranges reçues : 9 + 6 = 15 oranges.'),
     SupplementalQuestion('bonus_cp2_probleme_op_2','Kossi a 17 billes. Il en donne 5. Combien lui en reste-t-il ?',['12','22','13'],0,'On enlève les billes données : 17 − 5 = 12 billes.'),
     SupplementalQuestion('bonus_cp2_probleme_op_3','Une classe a 11 cahiers et reçoit encore 8 cahiers. Quel calcul faut-il faire ?',['11 − 8','11 + 8','11 × 8'],1,'On reçoit des cahiers : il faut ajouter, donc 11 + 8.'),
     SupplementalQuestion('bonus_cp2_probleme_op_4','Un vendeur a 20 œufs et en vend 7. Quel calcul donne le nombre restant ?',['20 + 7','20 − 7','20 × 7'],1,'On vend des œufs : on enlève 7, donc 20 − 7 = 13 œufs.')]),
  SupplementalLesson('cp2_etats_eau', SchoolLevel.cp2, 'Sciences', 'Découvrir les états de l’eau',
    'L’eau existe sous plusieurs formes. L’eau liquide coule et prend la forme du récipient. La glace est de l’eau solide : elle garde une forme. La vapeur d’eau est un gaz que l’on ne voit généralement pas. Quand on chauffe de l’eau, une partie peut se transformer en vapeur ; quand on refroidit de l’eau suffisamment, elle peut devenir de la glace.',
    'Dans un verre, l’eau est liquide. Dans un congélateur, l’eau peut devenir de la glace. Au-dessus d’une eau très chaude, la vapeur d’eau peut se former ; attention, il ne faut jamais approcher le visage d’une casserole chaude.',
    [SupplementalQuestion('bonus_cp2_eau_1','Quel est l’état de l’eau dans un verre ?',['Solide','Liquide','Pierre'],1,'Dans un verre, l’eau est à l’état liquide.'),
     SupplementalQuestion('bonus_cp2_eau_2','Comment appelle-t-on l’eau devenue solide par le froid ?',['La glace','La fumée','Le sable'],0,'La glace est de l’eau à l’état solide.'),
     SupplementalQuestion('bonus_cp2_eau_3','Quel état correspond à la vapeur d’eau ?',['Solide','Liquide','Gazeux'],2,'La vapeur d’eau est un gaz.'),
     SupplementalQuestion('bonus_cp2_eau_4','Que peut devenir l’eau si elle gèle suffisamment ?',['Du bois','De la glace','Du métal'],1,'En gelant, l’eau liquide devient de la glace.')]),
  SupplementalLesson('cp2_hygiene_mains', SchoolLevel.cp2, 'Sciences', 'Comprendre l’importance du lavage des mains',
    'Les mains touchent beaucoup d’objets et peuvent porter des microbes invisibles. Se laver les mains avec de l’eau propre et du savon aide à enlever les saletés et à réduire les microbes. Il faut se laver les mains avant de manger, après être allé aux toilettes et après avoir joué dehors ou touché des déchets. Frotte les paumes, le dos des mains, entre les doigts et autour des ongles, puis rince et sèche avec un linge propre.',
    'Avant le repas, Afi se lave les mains avec de l’eau et du savon. Elle frotte entre les doigts, rince et sèche ses mains. Ce geste aide à éviter la transmission de certaines maladies.',
    [SupplementalQuestion('bonus_cp2_hygiene_1','Avec quoi faut-il se laver les mains pour bien les nettoyer ?',['Avec de l’eau et du savon','Avec du sable seulement','Avec de la poussière'],0,'L’eau propre et le savon aident à enlever les saletés et à réduire les microbes.'),
     SupplementalQuestion('bonus_cp2_hygiene_2','Quand faut-il se laver les mains ?',['Seulement le dimanche','Avant de manger','Jamais avant le repas'],1,'Il faut se laver les mains avant de manger.'),
     SupplementalQuestion('bonus_cp2_hygiene_3','Quelle partie faut-il aussi frotter ?',['Entre les doigts','Seulement les poignets','Aucune partie'],0,'Il faut frotter les paumes, le dos des mains et entre les doigts.'),
     SupplementalQuestion('bonus_cp2_hygiene_4','Que fait-on après avoir frotté les mains avec du savon ?',['On les couvre de poussière','On les rince et on les sèche','On les essuie sur le sol'],1,'Après le savonnage, on rince les mains et on les sèche avec un linge propre.')]),
  SupplementalLesson('cp2_besoins_animaux', SchoolLevel.cp2, 'Sciences', 'Découvrir les besoins essentiels des animaux',
    'Pour vivre, les animaux ont besoin de nourriture, d’eau et d’air. Ils ont aussi besoin d’un milieu adapté à leur vie : par exemple, un poisson vit dans l’eau et un chien peut vivre sur la terre ferme. Les animaux ne mangent pas tous la même nourriture. Il faut respecter les animaux et ne pas les priver d’eau ou de nourriture.',
    'Le chien a besoin d’eau, de nourriture et d’un endroit adapté pour se reposer. Le poisson a besoin d’eau propre et d’un milieu aquatique adapté. Chaque animal doit vivre dans un environnement qui répond à ses besoins.',
    [SupplementalQuestion('bonus_cp2_besoins_animaux_1','De quoi les animaux ont-ils besoin pour vivre ?',['D’eau et de nourriture','De jouets seulement','De vêtements'],0,'Les animaux ont besoin d’eau et de nourriture pour vivre.'),
     SupplementalQuestion('bonus_cp2_besoins_animaux_2','Quel milieu convient à un poisson ?',['Un arbre','L’eau','Une armoire'],1,'Le poisson vit dans un milieu aquatique.'),
     SupplementalQuestion('bonus_cp2_besoins_animaux_3','Pourquoi faut-il donner de l’eau à un animal ?',['Parce qu’il en a besoin pour vivre','Pour le colorer','Pour le faire voler'],0,'L’eau est indispensable à la vie des animaux.'),
     SupplementalQuestion('bonus_cp2_besoins_animaux_4','Que faut-il faire pour bien respecter un animal ?',['Le priver de nourriture','Le laisser sans eau','Répondre à ses besoins et le traiter avec soin'],2,'Il faut répondre aux besoins de l’animal et le traiter avec soin.')]),
  SupplementalLesson('cp2_deplacements_animaux', SchoolLevel.cp2, 'Sciences', 'Observer comment les animaux se déplacent',
    'Les animaux se déplacent de différentes façons pour chercher leur nourriture, se protéger ou trouver un abri. Le chien marche et court avec ses pattes. Le poisson nage avec ses nageoires. Beaucoup d’oiseaux, comme le pigeon, volent avec leurs ailes. Le serpent rampe en faisant onduler son corps. Tous les animaux ne se déplacent pas de la même façon.',
    'Observe : le chien court sur le sol ; le poisson nage dans l’eau ; le pigeon vole dans l’air ; le serpent rampe sur le sol. Ce sont des exemples de déplacements.',
    [SupplementalQuestion('bonus_cp2_animaux_move_1','Quel animal nage avec ses nageoires ?',['Le chien','Le poisson','Le pigeon'],1,'Le poisson nage avec ses nageoires.'),
     SupplementalQuestion('bonus_cp2_animaux_move_2','Comment le pigeon se déplace-t-il habituellement ?',['Il vole','Il nage','Il rampe'],0,'Le pigeon est un oiseau qui vole habituellement.'),
     SupplementalQuestion('bonus_cp2_animaux_move_3','Quel animal rampe ?',['Le serpent','Le chien','Le poisson'],0,'Le serpent rampe en faisant onduler son corps.'),
     SupplementalQuestion('bonus_cp2_animaux_move_4','Avec quoi le chien marche et court ?',['Ses pattes','Ses nageoires','Ses ailes'],0,'Le chien marche et court avec ses pattes.')]),
  SupplementalLesson('cp2_parties_plante', SchoolLevel.cp2, 'Sciences', 'Identifier les principales parties d’une plante',
    'Une plante a plusieurs parties. Les racines se trouvent généralement dans la terre et absorbent l’eau et les sels minéraux. La tige soutient la plante et transporte la sève. Les feuilles aident la plante à fabriquer sa nourriture grâce à la lumière. Beaucoup de plantes portent aussi des fleurs, puis des fruits contenant des graines.',
    'Observe un jeune plant : les racines sont sous la terre, la tige porte les feuilles, et les feuilles sont souvent vertes. Une fleur peut ensuite donner un fruit qui contient des graines.',
    [SupplementalQuestion('bonus_cp2_plante_1','Quelle partie de la plante se trouve généralement dans la terre ?',['La fleur','Les racines','Le fruit'],1,'Les racines se trouvent généralement dans la terre.'),
     SupplementalQuestion('bonus_cp2_plante_2','Quelle partie soutient la plante ?',['La tige','La graine','Le fruit'],0,'La tige soutient la plante et porte les feuilles.'),
     SupplementalQuestion('bonus_cp2_plante_3','Quelle partie aide la plante à fabriquer sa nourriture grâce à la lumière ?',['La pierre','Les feuilles','Le sable'],1,'Les feuilles utilisent la lumière pour aider la plante à fabriquer sa nourriture.'),
     SupplementalQuestion('bonus_cp2_plante_4','Que peut contenir un fruit ?',['Des graines','Des cailloux','Du métal'],0,'Beaucoup de fruits contiennent des graines.')]),

  SupplementalLesson('cp2_multiplication_groupes', SchoolLevel.cp2, 'Mathématiques', 'Comprendre la multiplication avec des groupes égaux',
    'La multiplication permet de compter rapidement des groupes qui contiennent le même nombre d’objets. On peut d’abord additionner les groupes. Par exemple, 3 groupes de 4 objets donnent 4 + 4 + 4 = 12. On écrit aussi 3 × 4 = 12 : cela signifie 3 groupes de 4. Le résultat s’appelle le produit.',
    'Dans 4 assiettes, il y a 2 mangues dans chaque assiette. On compte 2 + 2 + 2 + 2 = 8 mangues. C’est 4 groupes de 2, donc 4 × 2 = 8.',
    [SupplementalQuestion('bonus_cp2_mult_groupes_1','2 groupes de 3 crayons : combien de crayons en tout ?',['5','6','9'],1,'2 groupes de 3 donnent 3 + 3 = 6 crayons.'),
     SupplementalQuestion('bonus_cp2_mult_groupes_2','Que signifie 4 × 2 ?',['4 groupes de 2','2 groupes de 4 seulement','4 + 2'],0,'4 × 2 signifie 4 groupes de 2.'),
     SupplementalQuestion('bonus_cp2_mult_groupes_3','3 × 5 = ?',['8','15','10'],1,'3 groupes de 5 donnent 5 + 5 + 5 = 15.'),
     SupplementalQuestion('bonus_cp2_mult_groupes_4','5 groupes de 2 cahiers : quel calcul convient ?',['5 + 2','5 × 2','5 − 2'],1,'5 groupes de 2 se représentent par 5 × 2.')]),

  SupplementalLesson('cp2_partage_equitable', SchoolLevel.cp2, 'Mathématiques', 'Partager une quantité en parts égales',
    'Partager équitablement, c’est donner la même quantité à chaque personne ou à chaque groupe. Pour trouver la quantité de chacun, distribue les objets un par un en faisant des tours, jusqu’à ce qu’il n’en reste plus. Vérifie que chaque personne a reçu le même nombre.',
    'On partage 12 noix entre 3 enfants. Chaque enfant reçoit 4 noix, car 4 + 4 + 4 = 12. Le partage est équitable : chacun reçoit la même quantité.',
    [SupplementalQuestion('bonus_cp2_partage_1','8 biscuits sont partagés entre 2 enfants également. Combien chacun reçoit-il ?',['3','4','6'],1,'8 biscuits partagés également entre 2 enfants donnent 4 biscuits chacun.'),
     SupplementalQuestion('bonus_cp2_partage_2','10 crayons sont partagés entre 5 élèves. Combien chaque élève reçoit-il ?',['2','5','10'],0,'Chaque élève reçoit 2 crayons : 2 × 5 = 10.'),
     SupplementalQuestion('bonus_cp2_partage_3','Quel partage est équitable entre 3 enfants ?',['2, 2 et 4 bonbons','3, 3 et 3 bonbons','1, 2 et 3 bonbons'],1,'Le partage 3, 3 et 3 est équitable car chacun reçoit 3 bonbons.'),
     SupplementalQuestion('bonus_cp2_partage_4','12 oranges sont partagées également entre 4 paniers. Combien d’oranges par panier ?',['2','3','4'],1,'12 oranges réparties en 4 parts égales donnent 3 oranges par panier.')]),

  SupplementalLesson('cp2_identifier_sujet', SchoolLevel.cp2, 'Français', 'Identifier le sujet dans une phrase simple',
    'Dans une phrase, le sujet indique de qui ou de quoi on parle. Pour le trouver, demande : « Qui est-ce qui fait l’action ? » Le sujet peut être un nom ou un groupe de mots. Le verbe indique ce que fait le sujet ou ce qui lui arrive.',
    'Dans la phrase « Ama chante », on parle d’Ama : Ama est le sujet. Dans « Le petit garçon joue », le sujet est « Le petit garçon ». Pour trouver le sujet, cherche qui fait l’action.',
    [SupplementalQuestion('bonus_cp2_sujet_1','Dans « Kossi court », quel est le sujet ?',['court','Kossi','la cour'],1,'On parle de Kossi : Kossi est le sujet.'),
     SupplementalQuestion('bonus_cp2_sujet_2','Dans « La fille lit », qui fait l’action ?',['La fille','lit','le livre'],0,'La fille fait l’action de lire : c’est le sujet.'),
     SupplementalQuestion('bonus_cp2_sujet_3','Quel est le sujet dans « Les élèves chantent » ?',['chantent','Les élèves','une chanson'],1,'Le sujet est « Les élèves », car ce sont eux qui chantent.'),
     SupplementalQuestion('bonus_cp2_sujet_4','Dans « Le chat dort », quel groupe est le sujet ?',['dort','Le chat','le lit'],1,'Le chat est celui dont on parle : « Le chat » est le sujet.')]),
  SupplementalLesson('cp2_pronoms_personnels_sujets', SchoolLevel.cp2, 'Français', 'Employer les pronoms personnels sujets',
    'Les pronoms personnels sujets remplacent le nom ou le groupe de mots qui fait l’action. Au singulier, on utilise je, tu, il ou elle. Au pluriel, on utilise nous, vous, ils ou elles. Le pronom doit correspondre à la personne ou aux personnes dont on parle.',
    'Exemples : « Ama chante » devient « Elle chante ». « Kossi et moi jouons » devient « Nous jouons ». « Les garçons courent » devient « Ils courent ». « Les filles dansent » devient « Elles dansent ».',
    [SupplementalQuestion('bonus_cp2_pronoms_1','Quel pronom peut remplacer « Afi » ?',['Il','Elle','Nous'],1,'Afi est une fille : on peut dire « elle ».'),
     SupplementalQuestion('bonus_cp2_pronoms_2','« Kossi et moi » peut être remplacé par…',['Nous','Vous','Ils'],0,'Kossi et moi = nous.'),
     SupplementalQuestion('bonus_cp2_pronoms_3','Quel pronom remplace « les garçons » ?',['Elle','Ils','Tu'],1,'« Les garçons » est masculin pluriel : ils.'),
     SupplementalQuestion('bonus_cp2_pronoms_4','Complète : « ___ êtes dans la classe. »',['Vous','Il','Je'],0,'On dit « Vous êtes » pour s’adresser à plusieurs personnes ou à une personne avec politesse.')]),

  SupplementalLesson('cp2_comparer_nombres_100', SchoolLevel.cp2, 'Mathématiques', 'Comparer les nombres jusqu’à 100',
    'Pour comparer deux nombres, regarde d’abord les dizaines. Le nombre qui a le plus de dizaines est le plus grand. Si les dizaines sont égales, compare les unités. Le signe < signifie « plus petit que », > signifie « plus grand que » et = signifie « égal à ».',
    'Exemples : 46 > 39 car 4 dizaines sont plus que 3 dizaines. 52 < 57 car les dizaines sont égales et 2 unités sont moins que 7 unités. 64 = 64 car les deux nombres sont identiques.',
    [SupplementalQuestion('bonus_cp2_compare_1','Quel nombre est le plus grand ?',['28','32','23'],1,'32 a 3 dizaines, tandis que 28 et 23 en ont 2.'),
     SupplementalQuestion('bonus_cp2_compare_2','Complète : 45 … 48.',['>','<','='],1,'45 est plus petit que 48 : 45 < 48.'),
     SupplementalQuestion('bonus_cp2_compare_3','Quel signe convient : 61 … 61 ?',['<','>','='],2,'Les deux nombres sont égaux : on écrit =.'),
     SupplementalQuestion('bonus_cp2_compare_4','Quel nombre est le plus petit ?',['70','67','76'],1,'67 est plus petit que 70 et 76.')]),

  SupplementalLesson('cp2_proteger_dents', SchoolLevel.cp2, 'Sciences', 'Prendre soin de ses dents',
    'Les dents servent à couper et à mâcher les aliments. Pour les garder propres, on se brosse les dents chaque jour avec une brosse adaptée. On limite les grignotages sucrés et on demande l’aide d’un adulte si une dent fait mal.',
    'Le brossage aide à retirer les restes d’aliments et la plaque qui se forme sur les dents. Il faut brosser doucement toutes les faces des dents et ne pas partager sa brosse à dents.',
    [SupplementalQuestion('bonus_cp2_dents_1','À quoi servent les dents ?',['À mâcher les aliments','À entendre les sons','À respirer'],0,'Les dents servent notamment à couper et mâcher les aliments.'),
     SupplementalQuestion('bonus_cp2_dents_2','Quel geste aide à garder les dents propres ?',['Les brosser chaque jour','Les laver avec du sable','Ne jamais les nettoyer'],0,'Le brossage régulier aide à garder les dents propres.'),
     SupplementalQuestion('bonus_cp2_dents_3','Que faut-il faire si une dent fait mal ?',['Le dire à un adulte','Cacher la douleur','Mordre un objet dur'],0,'Il faut prévenir un adulte pour obtenir de l’aide appropriée.'),
     SupplementalQuestion('bonus_cp2_dents_4','Pourquoi limiter les grignotages sucrés ?',['Ils peuvent favoriser les caries','Ils rendent les dents plus longues','Ils remplacent le brossage'],0,'Les prises fréquentes d’aliments sucrés peuvent favoriser les caries.')]),
  SupplementalLesson('cp2_mots_position_espace', SchoolLevel.cp2, 'Français', 'Employer les mots pour situer dans l’espace',
    'Les mots de position aident à dire où se trouve une personne ou un objet. « Sur » indique qu’un objet est posé au-dessus et touche généralement un support. « Sous » indique qu’il est en dessous. « Devant » et « derrière » indiquent la place par rapport à un repère. « Entre » indique une place au milieu de deux objets.',
    'Observe la scène : le livre est sur la table ; le ballon est sous la chaise ; Afi se tient devant la porte ; le sac est derrière Afi ; le crayon est entre deux cahiers. Ces mots permettent de décrire précisément la place des objets.',
    [SupplementalQuestion('bonus_cp2_position_1','Le livre est posé sur la table. Où est le livre ?',['Sous la table','Sur la table','Dans la table'],1,'Le livre touche le dessus de la table : il est sur la table.'),
     SupplementalQuestion('bonus_cp2_position_2','Le ballon est en dessous de la chaise. Où est-il ?',['Sous la chaise','Sur la chaise','Devant la chaise'],0,'En dessous de la chaise signifie sous la chaise.'),
     SupplementalQuestion('bonus_cp2_position_3','Afi se place à l’avant de la porte. Où se trouve Afi ?',['Derrière la porte','Devant la porte','Sous la porte'],1,'À l’avant du repère, on dit devant.'),
     SupplementalQuestion('bonus_cp2_position_4','Le crayon est au milieu de deux cahiers. Où est le crayon ?',['Entre les cahiers','Sur les cahiers','Derrière les cahiers'],0,'Au milieu de deux objets, le crayon est entre les cahiers.')]),
  SupplementalLesson('cp2_observer_temps', SchoolLevel.cp2, 'Sciences', 'Observer le temps qu’il fait',
    'Le temps qu’il fait peut changer d’un jour à l’autre. On peut observer le ciel et décrire le temps : ensoleillé, nuageux, pluvieux ou venteux. La météo aide à choisir des vêtements et à préparer les activités de la journée. Il faut observer sans se mettre en danger.',
    'Le matin, Afi regarde le ciel depuis la cour avec son enseignant. Le ciel est couvert de nuages : elle dit qu’il fait nuageux. Si la pluie tombe, on peut utiliser un parapluie ou un imperméable avec l’aide d’un adulte.',
    [SupplementalQuestion('bonus_cp2_meteo_1','Le ciel est rempli de nuages. Comment décrit-on le temps ?',['Nuageux','Ensoleillé','Neigeux'],0,'Quand le ciel est couvert de nuages, on peut dire qu’il est nuageux.'),
     SupplementalQuestion('bonus_cp2_meteo_2','Que peut-on utiliser lorsqu’il pleut ?',['Un parapluie','Une paire de lunettes de soleil seulement','Un éventail pour arrêter la pluie'],0,'Un parapluie peut aider à se protéger de la pluie.'),
     SupplementalQuestion('bonus_cp2_meteo_3','Quel temps fait-il quand le soleil brille et que le ciel est dégagé ?',['Pluvieux','Ensoleillé','Venteux'],1,'Quand le soleil brille et que le ciel est dégagé, il fait ensoleillé.'),
     SupplementalQuestion('bonus_cp2_meteo_4','Comment observer la météo en sécurité ?',['Regarder le ciel depuis un endroit sûr','Sortir pendant un orage','Monter sur un toit'],0,'On observe le temps depuis un endroit sûr, sans s’exposer aux dangers.')]),
  SupplementalLesson('cp2_nombres_pairs_impairs', SchoolLevel.cp2, 'Mathématiques', 'Reconnaître les nombres pairs et impairs',
    'Un nombre est pair lorsqu’on peut ranger ses objets par deux sans en laisser seul. Un nombre est impair lorsqu’il reste un objet seul après avoir fait des paires. Pour les nombres écrits en chiffres, ceux qui se terminent par 0, 2, 4, 6 ou 8 sont pairs. Ceux qui se terminent par 1, 3, 5, 7 ou 9 sont impairs.',
    'Exemple : 6 noix peuvent former 3 paires : 6 est pair. Avec 7 noix, on forme 3 paires et il reste 1 noix : 7 est impair. On peut aussi regarder le chiffre des unités.',
    [SupplementalQuestion('bonus_cp2_pair_1','Le nombre 8 est…',['Pair','Impair','Ni pair ni impair'],0,'8 objets forment 4 paires : 8 est pair.'),
     SupplementalQuestion('bonus_cp2_pair_2','Quel nombre est impair ?',['12','15','20'],1,'15 se termine par 5 : c’est un nombre impair.'),
     SupplementalQuestion('bonus_cp2_pair_3','Quel chiffre peut terminer un nombre pair ?',['3','7','6'],2,'Les nombres pairs se terminent par 0, 2, 4, 6 ou 8.'),
     SupplementalQuestion('bonus_cp2_pair_4','Avec 9 cailloux, après avoir formé des paires, que reste-t-il ?',['Aucun caillou','Un caillou seul','Deux cailloux seuls'],1,'9 cailloux forment 4 paires et il reste 1 caillou : 9 est impair.')]),
  SupplementalLesson('cp2_accord_adjectif_simple', SchoolLevel.cp2, 'Français', 'Accorder un adjectif simple avec le nom',
    'Un adjectif donne une précision sur un nom. Il doit s’accorder avec le nom qu’il accompagne. Avec un nom masculin singulier, on peut dire « un petit sac ». Avec un nom féminin singulier, on dit « une petite boîte ». Au pluriel, on ajoute souvent un s à l’adjectif : « des petits sacs », « des petites boîtes ». Certains adjectifs ont des formes particulières : il faut les apprendre.',
    'Observe les exemples : un chat noir ; une chatte noire ; des chats noirs ; des chattes noires. Le nom et l’adjectif changent ensemble selon le genre et le nombre.',
    [SupplementalQuestion('bonus_cp2_adj_1','Complète : « une ___ fille »',['petit','petite','petits'],1,'Fille est féminin singulier : on écrit petite.'),
     SupplementalQuestion('bonus_cp2_adj_2','Complète : « des sacs ___ »',['lourd','lourds','lourde'],1,'Sacs est masculin pluriel : on écrit lourds.'),
     SupplementalQuestion('bonus_cp2_adj_3','Quel groupe est correctement écrit ?',['une robe rouge','une robe rouges','un robe rouge'],0,'Robe est féminin singulier ; rouge s’accorde au féminin singulier et reste ici sans e supplémentaire.'),
     SupplementalQuestion('bonus_cp2_adj_4','Complète : « des maisons ___ »',['grand','grande','grandes'],2,'Maisons est féminin pluriel : grandes.')]),
  SupplementalLesson('cp2_objets_naturels_fabriques', SchoolLevel.cp2, 'Sciences', 'Distinguer les éléments naturels et les objets fabriqués',
    'Un élément naturel existe dans la nature sans être fabriqué par une personne : un arbre, une pierre ou une coquille. Un objet fabriqué est réalisé ou transformé par les humains pour répondre à un besoin : une chaise, un cahier ou une cuillère. Un objet fabriqué peut être fait avec une matière naturelle, comme une chaise en bois.',
    'Observe autour de toi : l’arbre pousse dans la nature. Le menuisier transforme du bois pour fabriquer une chaise. Le bois vient d’un arbre, mais la chaise est un objet fabriqué.',
    [SupplementalQuestion('bonus_cp2_nature_1','Lequel est un élément naturel ?',['Un cahier','Une pierre','Une chaise'],1,'Une pierre existe dans la nature ; elle n’a pas été fabriquée comme un cahier ou une chaise.'),
     SupplementalQuestion('bonus_cp2_nature_2','Lequel est un objet fabriqué ?',['Un arbre','Une coquille vide','Une cuillère'],2,'Une cuillère est réalisée par des personnes pour servir à manger.'),
     SupplementalQuestion('bonus_cp2_nature_3','Une chaise est fabriquée avec du bois. Quelle affirmation est juste ?',['Le bois est une matière naturelle et la chaise est fabriquée','La chaise pousse comme un arbre','Le bois est toujours fabriqué par les humains'],0,'Le bois vient d’un arbre ; la chaise est construite à partir de ce bois.'),
     SupplementalQuestion('bonus_cp2_nature_4','Quel groupe contient seulement des éléments naturels ?',['Stylo et cahier','Pierre et arbre','Chaise et cuillère'],1,'La pierre et l’arbre sont des éléments naturels.')]),
  SupplementalLesson('cp2_suites_numeriques_pas', SchoolLevel.cp2, 'Mathématiques', 'Compléter des suites numériques simples',
    'Une suite numérique est une liste de nombres rangés dans un ordre. Pour la continuer, observe ce qui change d’un nombre au suivant. On peut compter de 2 en 2, de 5 en 5 ou de 10 en 10. Il faut garder le même pas dans toute la suite.',
    'Exemples : 2, 4, 6, 8… (on ajoute 2) ; 5, 10, 15, 20… (on ajoute 5) ; 10, 20, 30, 40… (on ajoute 10). Pour trouver le nombre suivant, ajoute le pas au dernier nombre.',
    [SupplementalQuestion('bonus_cp2_suite_1','Complète : 2, 4, 6, __',['7','8','9'],1,'On ajoute 2 : 6 + 2 = 8.'),
     SupplementalQuestion('bonus_cp2_suite_2','Complète : 5, 10, 15, __',['20','25','18'],0,'On ajoute 5 : 15 + 5 = 20.'),
     SupplementalQuestion('bonus_cp2_suite_3','Quel nombre manque : 10, 20, __, 40 ?',['25','30','35'],1,'On compte de 10 en 10 : 10, 20, 30, 40.'),
     SupplementalQuestion('bonus_cp2_suite_4','Quel est le pas de la suite 3, 6, 9, 12 ?',['2','3','4'],1,'Chaque nombre augmente de 3 : le pas est 3.')]),
  SupplementalLesson('cp1_animaux_domestiques_sauvages', SchoolLevel.cp1, 'Éveil', 'Distinguer les animaux domestiques et sauvages',
    'Les animaux domestiques vivent souvent près des humains et peuvent être élevés ou soignés par eux : par exemple la poule, la chèvre ou le chien. Les animaux sauvages vivent dans la nature sans être élevés comme des animaux de ferme ou de maison : par exemple le lion ou le singe sauvage. Il faut observer les animaux à distance et ne pas déranger ceux que l’on ne connaît pas.',
    'Dans une ferme, une personne peut nourrir des chèvres et des poules. Dans la forêt, un singe sauvage cherche sa nourriture. Même un animal domestique peut mordre ou griffer : demande toujours à un adulte avant de t’approcher.',
    [SupplementalQuestion('bonus_cp1_domwild_1','Lequel est généralement un animal domestique ?',['La chèvre','Le lion','Le singe sauvage'],0,'La chèvre est souvent élevée par les humains dans une ferme.'),
     SupplementalQuestion('bonus_cp1_domwild_2','Lequel est un animal sauvage ?',['La poule de la ferme','Le lion','Le chien de la maison'],1,'Le lion vit à l’état sauvage et n’est pas un animal de ferme.'),
     SupplementalQuestion('bonus_cp1_domwild_3','Qui peut nourrir les animaux domestiques de la ferme ?',['Un éleveur','Un rocher','Une feuille'],0,'L’éleveur s’occupe des animaux et leur donne les soins nécessaires.'),
     SupplementalQuestion('bonus_cp1_domwild_4','Que faire si l’on rencontre un animal inconnu ?',['Le toucher tout de suite','Le poursuivre','Rester à distance et prévenir un adulte'],2,'On garde ses distances et on demande l’aide d’un adulte pour éviter les morsures ou les griffures.')]),
  SupplementalLesson('ce1_determinants_articles', SchoolLevel.ce1, 'Français', 'Utiliser les déterminants simples',
    'Le déterminant se place généralement devant le nom. Il aide à préciser le nom et s’accorde avec lui en genre et en nombre. On peut utiliser les articles définis le, la, les ou les articles indéfinis un, une, des.',
    'Exemples : le livre, la trousse, les cahiers ; un ballon, une orange, des crayons. « Le » accompagne un nom masculin singulier, « la » un nom féminin singulier et « les » un nom pluriel.',
    [SupplementalQuestion('bonus_ce1_det_1','Complète : « ___ livre »',['La','Le','Les'],1,'Livre est masculin singulier : on écrit « le livre ».'),
     SupplementalQuestion('bonus_ce1_det_2','Complète : « ___ trousse »',['Un','Une','Des'],1,'Trousse est féminin singulier : on écrit « une trousse ».'),
     SupplementalQuestion('bonus_ce1_det_3','Quel déterminant convient à « cahiers » ?',['Le','La','Les'],2,'Cahiers est au pluriel : on utilise « les ».'),
     SupplementalQuestion('bonus_ce1_det_4','Quel groupe est correctement écrit ?',['un orange','une orange','des orange'],1,'Orange est ici un nom féminin singulier : « une orange ».')]),
  SupplementalLesson('ce1_besoins_plantes', SchoolLevel.ce1, 'Sciences', 'Découvrir les besoins des plantes',
    'Pour grandir, une plante a besoin d’eau, de lumière et d’air. Les racines absorbent l’eau et les sels minéraux présents dans le sol. La lumière permet à la plante de fabriquer sa nourriture. Une plante qui manque longtemps d’eau ou de lumière peut dépérir.',
    'Observe une jeune plante : on l’arrose sans la noyer et on la place dans un endroit lumineux. On évite de l’arracher ou de casser ses feuilles. Compare son développement avec celui d’une plante bien entretenue.',
    [SupplementalQuestion('bonus_ce1_plante_1','De quoi une plante a-t-elle besoin pour bien grandir ?',['D’eau et de lumière','De bonbons','De plastique'],0,'L’eau et la lumière sont indispensables au développement de la plupart des plantes.'),
     SupplementalQuestion('bonus_ce1_plante_2','Quelle partie de la plante absorbe surtout l’eau du sol ?',['La fleur','Les racines','Le fruit'],1,'Les racines absorbent l’eau et les sels minéraux du sol.'),
     SupplementalQuestion('bonus_ce1_plante_3','Pourquoi une plante a-t-elle besoin de lumière ?',['Pour fabriquer sa nourriture','Pour marcher','Pour faire du bruit'],0,'La lumière fournit l’énergie nécessaire à la fabrication de la nourriture de la plante.'),
     SupplementalQuestion('bonus_ce1_plante_4','Quel geste aide une plante à pousser ?',['L’arroser raisonnablement et la placer à la lumière','La laisser toujours dans le noir','Arracher ses racines'],0,'Une plante a besoin d’eau, mais il ne faut pas la noyer ; elle a aussi besoin de lumière.')]),
  SupplementalLesson('terminale_variations_derivee', SchoolLevel.terminale, 'Mathématiques', 'Étudier les variations avec la dérivée',
    'La dérivée permet de connaître le sens de variation d’une fonction sur un intervalle. Si f’(x) est positive sur un intervalle, f est croissante ; si f’(x) est négative, f est décroissante. Pour étudier les variations, on calcule f’, on étudie son signe, puis on déduit les variations de f. Les points où f’(x)=0 peuvent correspondre à un extremum.',
    'Exemple : f(x)=x²−4x+3. Alors f’(x)=2x−4. Pour x<2, f’(x)<0 : f décroît. Pour x>2, f’(x)>0 : f croît. En x=2, f(2)=−1 ; la fonction atteint donc son minimum −1 en x=2.',
    [SupplementalQuestion('bonus_term_var_1','Si f’(x)>0 sur un intervalle, f est…',['Décroissante','Croissante','Constante'],1,'Une dérivée positive indique que la fonction est croissante sur cet intervalle.'),
     SupplementalQuestion('bonus_term_var_2','Pour f(x)=x²−4x+3, quelle est la dérivée ?',['2x−4','x−4','2x+3'],0,'La dérivée de x² est 2x et celle de −4x est −4 ; la constante 3 a pour dérivée 0.'),
     SupplementalQuestion('bonus_term_var_3','Pour f’(x)=2x−4, où la dérivée s’annule-t-elle ?',['En x=−2','En x=2','En x=4'],1,'2x−4=0 donne 2x=4, donc x=2.'),
     SupplementalQuestion('bonus_term_var_4','Quel est le minimum de f(x)=x²−4x+3 ?',['−1 en x=2','3 en x=0','0 en x=4'],0,'La fonction décroît jusqu’à x=2 puis croît ; f(2)=4−8+3=−1.')]),
  SupplementalLesson('cm1_reconnaitre_angles', SchoolLevel.cm1, 'Mathématiques', 'Reconnaître les angles droits, aigus et obtus',
    'Un angle est formé par deux demi-droites qui ont la même origine, appelée sommet. Un angle droit mesure 90°. Un angle aigu est plus petit qu’un angle droit ; un angle obtus est plus grand qu’un angle droit mais plus petit qu’un angle plat (180°). On peut comparer un angle à l’angle droit d’une équerre.',
    'Exemples : le coin d’une feuille carrée forme un angle droit. L’ouverture d’une paire de ciseaux peu ouverte peut former un angle aigu. Une porte largement ouverte peut former un angle obtus. Pour vérifier, place le sommet et un côté de l’angle contre ceux de l’équerre.',
    [SupplementalQuestion('bonus_cm1_angle_1','Combien mesure un angle droit ?',['45°','90°','180°'],1,'Un angle droit mesure exactement 90 degrés.'),
     SupplementalQuestion('bonus_cm1_angle_2','Un angle de 35° est…',['Aigu','Droit','Obtus'],0,'35° est inférieur à 90° : l’angle est aigu.'),
     SupplementalQuestion('bonus_cm1_angle_3','Un angle de 120° est…',['Aigu','Droit','Obtus'],2,'120° est supérieur à 90° et inférieur à 180° : l’angle est obtus.'),
     SupplementalQuestion('bonus_cm1_angle_4','Quel outil aide à vérifier un angle droit ?',['Une équerre','Une balance','Un thermomètre'],0,'L’équerre possède un angle droit qui sert de référence pour vérifier un angle.')]),
  SupplementalLesson('sixieme_orienter_carte_points_cardinaux', SchoolLevel.sixieme, 'Géographie', 'S’orienter sur une carte avec les points cardinaux',
    'Les points cardinaux servent à indiquer une direction : le nord (N), le sud (S), l’est (E) et l’ouest (O). Sur une carte classique, le nord se trouve généralement en haut, le sud en bas, l’est à droite et l’ouest à gauche. Une rose des vents indique ces directions.',
    'Pour lire une carte, repère d’abord la rose des vents et la légende. Si la carte indique le nord en haut, un lieu situé à droite d’un autre est à l’est de celui-ci. Le soleil se lève approximativement à l’est et se couche à l’ouest ; cette observation peut aider à s’orienter, mais la rose des vents reste la référence sur la carte.',
    [SupplementalQuestion('bonus_6e_orientation_1','Quel point cardinal se trouve généralement en haut d’une carte ?',['Le nord','Le sud','L’ouest'],0,'Sur une carte classique, le nord est généralement placé en haut.'),
     SupplementalQuestion('bonus_6e_orientation_2','Quelle direction se trouve à droite lorsque le nord est en haut ?',['L’ouest','L’est','Le sud'],1,'Quand le nord est en haut, l’est se trouve à droite.'),
     SupplementalQuestion('bonus_6e_orientation_3','Quelle direction est opposée au sud ?',['L’est','L’ouest','Le nord'],2,'Le nord et le sud sont deux points cardinaux opposés.'),
     SupplementalQuestion('bonus_6e_orientation_4','Quel élément d’une carte aide à repérer les directions ?',['La rose des vents','Le titre seul','La couleur du papier'],0,'La rose des vents indique les points cardinaux et aide à s’orienter.')]),

  SupplementalLesson('cinquieme_melanges_homogenes_heterogenes', SchoolLevel.cinquieme, 'Physique-Chimie', 'Distinguer les mélanges homogènes et hétérogènes',
    'Un mélange contient plusieurs substances. Un mélange homogène paraît uniforme : on ne distingue pas ses constituants à l’œil nu, comme l’eau mélangée au sel après dissolution. Un mélange hétérogène présente plusieurs constituants ou phases visibles, comme l’eau et le sable.',
    'Pour observer un mélange, on peut laisser reposer le contenu d’un récipient transparent. Le sable peut se déposer au fond de l’eau : le mélange est hétérogène. Le sel dissous dans l’eau forme une solution homogène ; le sel est toujours présent même s’il n’est plus visible. Ne goûte jamais une substance utilisée en expérience.',
    [SupplementalQuestion('bonus_5e_melange_1','L’eau et le sable forment généralement un mélange…',['Homogène','Hétérogène','Pur'],1,'On peut distinguer le sable de l’eau : le mélange est hétérogène.'),
     SupplementalQuestion('bonus_5e_melange_2','Après dissolution complète du sel dans l’eau, le mélange paraît…',['Homogène','Hétérogène','Solide uniquement'],0,'Le sel dissous se répartit dans l’eau et le mélange paraît uniforme.'),
     SupplementalQuestion('bonus_5e_melange_3','Dans une solution d’eau salée, le sel…',['A disparu et n’existe plus','Est toujours présent, même s’il n’est plus visible','Devient du sable'],1,'La dissolution ne fait pas disparaître le sel : il est réparti dans l’eau.'),
     SupplementalQuestion('bonus_5e_melange_4','Quel geste est prudent pendant une expérience ?',['Goûter le mélange','Sentir directement le récipient','Ne jamais goûter les substances'],2,'En laboratoire ou en classe, on ne goûte jamais les produits utilisés.')]),

  SupplementalLesson('quatrieme_reproduction_plantes_fleurs', SchoolLevel.quatrieme, 'SVT', 'Comprendre la reproduction des plantes à fleurs',
    'La fleur contient les organes reproducteurs de nombreuses plantes. Les étamines produisent le pollen. Le pistil comprend notamment le stigmate, le style et l’ovaire qui contient les ovules. La pollinisation est le transport du pollen jusqu’au stigmate, souvent grâce aux insectes ou au vent.',
    'Après la pollinisation, le pollen peut permettre la fécondation d’un ovule. L’ovule fécondé devient une graine et l’ovaire se transforme généralement en fruit. Les graines peuvent ensuite germer si les conditions sont favorables : eau, température adaptée et souvent oxygène.',
    [SupplementalQuestion('bonus_4e_plantes_1','Quelle partie de la fleur produit le pollen ?',['Les étamines','Les racines','Les feuilles'],0,'Les étamines portent les sacs polliniques où se forme le pollen.'),
     SupplementalQuestion('bonus_4e_plantes_2','La pollinisation correspond au transport du pollen…',['Vers les racines','Jusqu’au stigmate','Dans les feuilles'],1,'La pollinisation est le dépôt ou transport du pollen jusqu’au stigmate du pistil.'),
     SupplementalQuestion('bonus_4e_plantes_3','Après fécondation, l’ovule devient généralement…',['Une feuille','Une graine','Une racine'],1,'L’ovule fécondé se développe en graine.'),
     SupplementalQuestion('bonus_4e_plantes_4','Quelle partie de la fleur devient généralement le fruit ?',['L’ovaire','L’étamine','Le pétale'],0,'Après la fécondation, l’ovaire se transforme généralement en fruit.')]),

  SupplementalLesson('sixieme_types_phrases', SchoolLevel.sixieme, 'Français', 'Reconnaître les types de phrases',
    'Une phrase déclarative donne une information et se termine généralement par un point. Une phrase interrogative pose une question et se termine par un point d’interrogation. Une phrase impérative exprime un ordre, un conseil ou une consigne. Une phrase exclamative exprime une émotion ou une intensité et se termine par un point d’exclamation.',
    'Exemples : « Le marché ouvre tôt. » est déclarative ; « Quand ouvre le marché ? » est interrogative ; « Écoute attentivement. » est impérative ; « Quelle belle récolte ! » est exclamative. Le type dépend de l’intention du locuteur, pas seulement de la ponctuation.',
    [SupplementalQuestion('bonus_6e_types_1','Quelle phrase pose une question ?',['Le bus arrive.','Où vas-tu ?','Ferme la porte.'],1,'« Où vas-tu ? » demande une information : c’est une phrase interrogative.'),
     SupplementalQuestion('bonus_6e_types_2','« Les élèves travaillent. » est une phrase…',['Déclarative','Interrogative','Exclamative'],0,'Cette phrase donne une information : elle est déclarative.'),
     SupplementalQuestion('bonus_6e_types_3','« Range tes cahiers. » exprime surtout…',['Une question','Une consigne','Une émotion'],1,'Cette phrase donne un ordre ou une consigne : elle est impérative.'),
     SupplementalQuestion('bonus_6e_types_4','Quel signe termine généralement une phrase exclamative ?',['?','!',';'],1,'Le point d’exclamation marque souvent une émotion ou une intensité.')]),

  SupplementalLesson('cinquieme_digestion_absorption_nutriments', SchoolLevel.cinquieme, 'SVT', 'Comprendre la digestion et l’absorption des nutriments',
    'La digestion transforme les aliments en substances plus simples que l’organisme peut utiliser. Elle commence dans la bouche par la mastication et l’action de la salive. Dans l’estomac et l’intestin grêle, les sucs digestifs poursuivent la transformation. Les nutriments obtenus sont de petites molécules utilisables par le corps.',
    'Dans l’intestin grêle, les nutriments traversent la paroi intestinale et passent dans le sang : c’est l’absorption intestinale. Le sang les transporte vers les organes. Les aliments ne deviennent pas tous directement des nutriments : la digestion les transforme. Une alimentation variée, de l’eau et une bonne hygiène favorisent la santé.',
    [SupplementalQuestion('bonus_5e_digestion_1','Quel organe commence la digestion par la mastication ?',['La bouche','Le cœur','Le poumon'],0,'La digestion commence dans la bouche, où les aliments sont mastiqués et mélangés à la salive.'),
     SupplementalQuestion('bonus_5e_digestion_2','Quel est le rôle principal de la digestion ?',['Transformer les aliments en nutriments','Fabriquer l’air','Faire circuler le sang'],0,'La digestion transforme les aliments en nutriments simples que l’organisme peut utiliser.'),
     SupplementalQuestion('bonus_5e_digestion_3','Où se fait principalement l’absorption des nutriments ?',['Dans l’intestin grêle','Dans la bouche','Dans la trachée'],0,'La plupart des nutriments traversent la paroi de l’intestin grêle pour rejoindre le sang.'),
     SupplementalQuestion('bonus_5e_digestion_4','Après leur absorption, les nutriments sont transportés vers les organes par…',['Le sang','Les cheveux','Les os seuls'],0,'Le sang transporte les nutriments absorbés vers les différentes parties du corps.')]),

  SupplementalLesson('troisieme_echelle_ph', SchoolLevel.troisieme, 'Physique-Chimie', 'Classer les solutions selon leur pH',
    'Le pH indique si une solution aqueuse est acide, neutre ou basique. Dans l’échelle usuelle de 0 à 14 (à température ambiante), une solution est acide si son pH est inférieur à 7, neutre si son pH est égal à 7 et basique si son pH est supérieur à 7. Plus le pH est faible, plus la solution est acide ; plus il est élevé, plus elle est basique.',
    'Exemples : le jus de citron est acide, l’eau pure est proche de pH 7 et une solution de bicarbonate peut être basique. On mesure le pH avec du papier indicateur ou un pH-mètre. En laboratoire, ne goûte jamais une solution et ne la touche pas directement. Pour diluer un acide concentré, on verse toujours l’acide dans l’eau, lentement, selon les consignes de l’enseignant.',
    [SupplementalQuestion('bonus_3e_ph_1','Une solution de pH 3 est…',['Acide','Neutre','Basique'],0,'Un pH inférieur à 7 caractérise une solution acide.'),
     SupplementalQuestion('bonus_3e_ph_2','À température ambiante, une solution neutre a généralement un pH de…',['2','7','12'],1,'Le pH 7 correspond à la neutralité dans l’échelle usuelle à température ambiante.'),
     SupplementalQuestion('bonus_3e_ph_3','Une solution de pH 10 est…',['Acide','Neutre','Basique'],2,'Un pH supérieur à 7 caractérise une solution basique.'),
     SupplementalQuestion('bonus_3e_ph_4','Quel instrument mesure précisément le pH ?',['Un pH-mètre','Une balance','Un chronomètre'],0,'Le pH-mètre permet de mesurer le pH d’une solution.')]),

  SupplementalLesson('seconde_cellule_unite_vivant', SchoolLevel.seconde, 'SVT', 'La cellule, unité de base du vivant',
    'Tous les êtres vivants sont constitués d’une ou plusieurs cellules. Une cellule est délimitée par une membrane et contient du cytoplasme. De nombreuses cellules possèdent un noyau qui contient l’information génétique. Les cellules sont très petites et peuvent être observées au microscope.',
    'Les cellules végétales possèdent généralement une paroi autour de la membrane. Les cellules chlorophylliennes des plantes contiennent aussi des chloroplastes, où se déroule la photosynthèse. Pour observer une cellule, on prépare une lame, on la place sur la platine du microscope et on commence avec le plus faible grossissement.',
    [SupplementalQuestion('bonus_2nde_cellule_1','Quelle structure délimite la cellule ?',['La membrane','Le noyau seul','Le chloroplaste'],0,'La membrane plasmique délimite la cellule et contrôle les échanges avec son milieu.'),
     SupplementalQuestion('bonus_2nde_cellule_2','Dans de nombreuses cellules, où se trouve l’information génétique principale ?',['Dans le noyau','Dans la membrane','Dans la paroi'],0,'Le noyau contient l’essentiel de l’information génétique des cellules eucaryotes.'),
     SupplementalQuestion('bonus_2nde_cellule_3','Quelle structure est caractéristique des cellules végétales, en plus de la membrane ?',['Une paroi','Des poumons','Des os'],0,'Les cellules végétales possèdent généralement une paroi située à l’extérieur de la membrane.'),
     SupplementalQuestion('bonus_2nde_cellule_4','Avec quel instrument observe-t-on des cellules très petites ?',['Un microscope','Un thermomètre','Une balance'],0,'Le microscope permet d’observer des structures trop petites pour être vues à l’œil nu.')]),


  SupplementalLesson('premiere_svt_reaction_inflammatoire', SchoolLevel.premiere, 'SVT', 'La réaction inflammatoire, une défense rapide',
    'Lorsqu’un tissu est blessé ou qu’un micro-organisme pénètre dans le corps, une réaction inflammatoire locale peut se déclencher. Elle fait partie de l’immunité innée : elle est rapide et ne dépend pas d’une reconnaissance préalable précise du microbe. Des cellules sentinelles des tissus, dont certains mastocytes, libèrent des médiateurs chimiques comme l’histamine.',
    'Ces médiateurs provoquent notamment la dilatation de petits vaisseaux et une augmentation de leur perméabilité. Le sang afflue davantage et des cellules immunitaires, comme les phagocytes, rejoignent la zone. Les signes classiques sont rougeur, chaleur, gonflement et douleur. Schéma fonctionnel : blessure ou microbe → médiateurs chimiques → vaisseaux dilatés et plus perméables → arrivée des phagocytes → phagocytose. La phagocytose consiste à englober puis digérer un élément étranger. Une inflammation persistante ou importante nécessite un avis médical.',
    [SupplementalQuestion('bonus_1ere_inflammation_1','La réaction inflammatoire appartient principalement à…',['L’immunité innée','La mémoire scolaire','La digestion'],0,'La réaction inflammatoire est une réponse rapide de l’immunité innée.'),
     SupplementalQuestion('bonus_1ere_inflammation_2','Quel médiateur peut être libéré par les mastocytes ?',['L’histamine','L’insuline uniquement','La chlorophylle'],0,'Les mastocytes peuvent libérer de l’histamine, qui participe aux modifications locales des vaisseaux.'),
     SupplementalQuestion('bonus_1ere_inflammation_3','Quel signe est classique lors d’une inflammation locale ?',['Rougeur','Disparition immédiate du sang','Baisse obligatoire de la température locale'],0,'La rougeur et la chaleur sont liées notamment à l’afflux sanguin local.'),
     SupplementalQuestion('bonus_1ere_inflammation_4','La phagocytose consiste à…',['Englober puis digérer un élément étranger','Produire des os','Transporter l’oxygène dans les globules rouges'],0,'Un phagocyte englobe l’élément à éliminer puis le digère.')]),


  SupplementalLesson('terminale_titrage_concentration', SchoolLevel.terminale, 'Physique-Chimie', 'Déterminer une concentration par titrage',
    'Un titrage permet de déterminer la quantité ou la concentration d’une espèce chimique dans une solution inconnue, appelée solution titrée. On la fait réagir avec une solution titrante de concentration connue, ajoutée progressivement. Le titrage doit s’appuyer sur une réaction support rapide, totale et de stoichiométrie connue.',
    'L’équivalence est atteinte lorsque les réactifs ont été introduits dans les proportions stœchiométriques. Pour la réaction a A + b B → produits, à l’équivalence : n(A)/a = n(B)/b. Si A est dans un volume VA de concentration CA et B dans un volume VE de concentration CB, alors CA × VA / a = CB × VE / b. On peut repérer l’équivalence par un changement de couleur d’un indicateur adapté ou par une mesure instrumentale. Schéma de principe : burette contenant le titrant → ajout goutte à goutte dans un erlenmeyer contenant la solution titrée et l’indicateur.',
    [SupplementalQuestion('bonus_terminale_titrage_1','À quoi sert un titrage ?',['À déterminer une concentration inconnue','À mesurer la masse d’un objet sans balance','À séparer toujours tous les solides'],0,'Un titrage permet notamment de déterminer la concentration d’une espèce en solution.'),
     SupplementalQuestion('bonus_terminale_titrage_2','À l’équivalence, les réactifs sont introduits…',['Dans les proportions stœchiométriques','En quantités toujours égales','Sans réaction chimique'],0,'L’équivalence correspond aux proportions stœchiométriques de la réaction support.'),
     SupplementalQuestion('bonus_terminale_titrage_3','Pour a A + b B → produits, la relation à l’équivalence est…',['n(A)/a = n(B)/b','n(A) = a + b','n(A) × n(B) = 0'],0,'La relation exprime l’égalité des quantités de matière rapportées aux coefficients stœchiométriques.'),
     SupplementalQuestion('bonus_terminale_titrage_4','Quel dispositif peut ajouter le titrant progressivement ?',['Une burette','Un microscope','Un thermomètre seul'],0,'La burette permet de verser le titrant avec précision, progressivement.')]),


  SupplementalLesson('quatrieme_coi_complement_indirect', SchoolLevel.quatrieme, 'Français', 'Identifier le complément d’objet indirect (COI)',
    'Le complément d’objet indirect (COI) complète le verbe et est généralement introduit par une préposition, souvent à ou de. Pour le repérer, on pose une question comme « à qui ? », « à quoi ? », « de qui ? » ou « de quoi ? » après le verbe. Exemple : « Awa parle à sa sœur. » → Awa parle à qui ? à sa sœur : « à sa sœur » est le COI.',
    'Le COI peut être un groupe nominal (« Il se souvient de cette histoire ») ou un pronom (« Il lui parle »). Attention : le COI n’est pas toujours un groupe de mots placé après le verbe ; il peut être remplacé par un pronom. Schéma de repérage : sujet + verbe + préposition + complément. À distinguer du COD, qui se construit sans préposition : « Awa lit un livre » → lit quoi ? un livre (COD).',
    [SupplementalQuestion('bonus_4e_coi_1','Dans « Il téléphone à son ami », quel est le COI ?',['Il','à son ami','téléphone'],1,'On demande : il téléphone à qui ? « à son ami » est le COI.'),
     SupplementalQuestion('bonus_4e_coi_2','Le COI est généralement introduit par…',['Une préposition','Un déterminant seul','Un adjectif'],0,'Le COI est souvent introduit par une préposition comme à ou de.'),
     SupplementalQuestion('bonus_4e_coi_3','Dans « Elle se souvient de son enfance », le COI est…',['Elle','se souvient','de son enfance'],2,'Elle se souvient de quoi ? « de son enfance » est le COI.'),
     SupplementalQuestion('bonus_4e_coi_4','Dans « Il lui écrit », le pronom « lui » remplace ici…',['Un COI','Un COD toujours','Le sujet'],0,'« Lui » remplace le complément indirect : il écrit à qui ? à cette personne.')]),


  SupplementalLesson('troisieme_proposition_subordonnee_relative', SchoolLevel.troisieme, 'Français', 'Reconnaître la proposition subordonnée relative',
    'Une proposition subordonnée relative complète généralement un nom ou un pronom appelé antécédent. Elle est introduite par un pronom relatif : qui, que, dont, où, lequel et ses formes. Exemple : « Le livre que tu lis est intéressant. » La relative « que tu lis » précise le nom « livre ». Elle contient un verbe conjugué et dépend de la proposition principale.',
    'Pour analyser la phrase, repère le verbe de la relative, le pronom relatif et son antécédent. « La fille qui chante est ma sœur » : antécédent = « la fille » ; pronom relatif = « qui » ; relative = « qui chante ». « Qui » est sujet du verbe « chante ». « Le film que nous regardons » : « que » est COD de « regardons ». Schéma : nom antécédent + pronom relatif + proposition relative.',
    [SupplementalQuestion('bonus_3e_relative_1','Dans « Le garçon qui court est rapide », quelle est la relative ?',['Le garçon','qui court','est rapide'],1,'La proposition relative commence par le pronom relatif « qui » et précise « le garçon ».'),
     SupplementalQuestion('bonus_3e_relative_2','Quel mot est le pronom relatif dans « le livre que je lis » ?',['livre','que','lis'],1,'« Que » introduit la proposition relative « que je lis ».'),
     SupplementalQuestion('bonus_3e_relative_3','Dans « La maison où je vis », quel est l’antécédent de « où » ?',['La maison','je','vis'],0,'« Où » reprend le nom « la maison », qui est son antécédent.'),
     SupplementalQuestion('bonus_3e_relative_4','Une proposition relative contient généralement…',['Un verbe conjugué','Aucun verbe','Seulement un adjectif'],0,'La proposition relative est une proposition subordonnée et comporte un verbe conjugué.')]),

  SupplementalLesson('cm1_multiplication_10_100', SchoolLevel.cm1, 'Mathématiques', 'Multiplier par 10, 100 ou 1 000',
    'Pour multiplier un nombre entier par 10, 100 ou 1 000, chaque chiffre prend une place de numération plus grande : ×10 correspond à un rang, ×100 à deux rangs et ×1 000 à trois rangs. Pour les entiers, on peut ajouter des zéros à droite lorsque cela convient.',
    'Exemples : 34 × 10 = 340 ; 34 × 100 = 3 400 ; 34 × 1 000 = 34 000. Attention : avec un nombre décimal, on déplace la virgule au lieu d’ajouter simplement des zéros. Schéma : unités → dizaines → centaines → milliers.',
    [SupplementalQuestion('bonus_cm1_mult10_1','26 × 10 = …',['260','206','2 600'],0,'26 multiplié par 10 donne 260.'),
     SupplementalQuestion('bonus_cm1_mult10_2','45 × 100 = …',['450','4 500','45 000'],1,'45 × 100 = 4 500.'),
     SupplementalQuestion('bonus_cm1_mult10_3','7 × 1 000 = …',['700','7 000','70 000'],1,'7 × 1 000 = 7 000.'),
     SupplementalQuestion('bonus_cm1_mult10_4','Quel calcul donne 3 200 ?',['32 × 10','32 × 100','320 × 100'],1,'32 × 100 = 3 200.')]),

  SupplementalLesson('sixieme_continents_oceans', SchoolLevel.sixieme, 'Géographie', 'Repérer les continents et les océans',
    'Un continent est une vaste étendue de terres émergées. Dans le modèle scolaire courant à sept continents, on distingue l’Afrique, l’Europe, l’Asie, l’Amérique du Nord, l’Amérique du Sud, l’Océanie et l’Antarctique.',
    'On nomme généralement cinq océans : Pacifique, Atlantique, Indien, Arctique et Austral. Sur un planisphère, lis le titre, observe l’orientation et utilise la légende. Le Togo se situe en Afrique de l’Ouest, au bord du golfe de Guinée, dans l’océan Atlantique.',
    [SupplementalQuestion('bonus_6e_continents_1','Sur quel continent se trouve le Togo ?',['Afrique','Asie','Europe'],0,'Le Togo se trouve en Afrique de l’Ouest.'),
     SupplementalQuestion('bonus_6e_continents_2','Quel océan borde le golfe de Guinée ?',['Océan Atlantique','Océan Indien','Océan Arctique'],0,'Le golfe de Guinée appartient à l’océan Atlantique.'),
     SupplementalQuestion('bonus_6e_continents_3','Lequel est un océan ?',['Pacifique','Sahara','Alpes'],0,'Le Pacifique est un océan.'),
     SupplementalQuestion('bonus_6e_continents_4','Quel continent entoure le pôle Sud ?',['Antarctique','Europe','Océanie'],0,'L’Antarctique se trouve autour du pôle Sud.')]),

  SupplementalLesson('cinquieme_climats_zones', SchoolLevel.cinquieme, 'Géographie', 'Distinguer météo et climat',
    'La météo décrit l’état de l’atmosphère à un endroit et à un moment précis : pluie aujourd’hui, température de cet après-midi ou vent de demain. Le climat correspond aux conditions météorologiques habituelles d’une région observées sur une longue période, généralement plusieurs décennies.',
    'Les éléments étudiés sont notamment la température et les précipitations. Les climats tropicaux sont souvent chauds ; selon les régions, les pluies peuvent être réparties sur l’année ou concentrées en saison humide. Au Togo, on observe des saisons pluvieuses et sèches, avec des variations régionales. Schéma : observations quotidiennes → données sur plusieurs années → description du climat.',
    [SupplementalQuestion('bonus_5e_climat_1','La météo décrit…',['Le temps à court terme','Le climat sur plusieurs décennies','Uniquement les reliefs'],0,'La météo concerne les conditions atmosphériques à court terme.'),
     SupplementalQuestion('bonus_5e_climat_2','Le climat s’étudie à partir de données recueillies…',['Sur une longue période','Pendant une seule heure','Sans mesure'],0,'Le climat s’appuie sur des observations de longue durée.'),
     SupplementalQuestion('bonus_5e_climat_3','Quel élément est une donnée météorologique ?',['La température','La langue parlée','La population scolaire'],0,'La température décrit l’état de l’atmosphère.'),
     SupplementalQuestion('bonus_5e_climat_4','Au Togo, les saisons sont notamment marquées par…',['Des périodes pluvieuses et sèches','La neige toute l’année','Une absence permanente de pluie'],0,'Le Togo connaît des périodes pluvieuses et sèches.')]),

  SupplementalLesson('seconde_fonction_affine', SchoolLevel.seconde, 'Mathématiques', 'Étudier une fonction affine',
    'Une fonction affine s’écrit f(x) = ax + b, où a et b sont des nombres réels. Le nombre a est le coefficient directeur. Le nombre b est l’ordonnée à l’origine : f(0) = b.',
    'La représentation graphique d’une fonction affine est une droite. Pour la tracer, calcule deux images. Exemple : f(x) = 2x + 1 ; f(0) = 1 et f(2) = 5, donc la droite passe par (0 ; 1) et (2 ; 5). Si a est non nul, f(x) = 0 donne x = −b/a.',
    [SupplementalQuestion('bonus_2nde_affine_1','Dans f(x) = 3x + 4, quel est b ?',['3','4','7'],1,'Le terme constant b est 4.'),
     SupplementalQuestion('bonus_2nde_affine_2','Quelle est l’image de 2 par f(x) = 2x + 1 ?',['3','5','6'],1,'f(2) = 2 × 2 + 1 = 5.'),
     SupplementalQuestion('bonus_2nde_affine_3','La représentation graphique d’une fonction affine est…',['Une droite','Un cercle','Toujours une parabole'],0,'Une fonction de la forme ax + b se représente par une droite.'),
     SupplementalQuestion('bonus_2nde_affine_4','Pour f(x) = 2x − 6, la solution de f(x) = 0 est…',['x = 2','x = 3','x = 6'],1,'2x − 6 = 0, donc x = 3.')]),
  SupplementalLesson('quatrieme_atomes_molecules', SchoolLevel.quatrieme, 'Physique-Chimie', 'Distinguer atome, molécule et ion',
    'La matière est constituée de particules. Un atome est une entité électriquement neutre composée d’un noyau et d’électrons. Une molécule est un assemblage d’atomes liés entre eux. Un ion est une particule qui porte une charge électrique parce qu’elle a perdu ou gagné un ou plusieurs électrons.',
    'Exemples de modèles : O₂ représente une molécule formée de deux atomes d’oxygène ; H₂O contient deux atomes d’hydrogène et un atome d’oxygène. Na⁺ est un ion positif et Cl⁻ un ion négatif. Dans une formule, l’indice indique le nombre d’atomes de l’élément juste avant lui.',
    [SupplementalQuestion('bonus_4e_atom_1','Une molécule est…',['Un assemblage d’atomes liés','Un seul électron','Toujours un ion positif'],0,'Une molécule est formée de plusieurs atomes liés.'),
     SupplementalQuestion('bonus_4e_atom_2','Dans H₂O, combien y a-t-il d’atomes d’hydrogène ?',['1','2','3'],1,'L’indice 2 indique deux atomes d’hydrogène.'),
     SupplementalQuestion('bonus_4e_atom_3','Quel symbole désigne un ion positif ?',['Na⁺','Cl⁻','O₂'],0,'Na⁺ porte une charge positive.'),
     SupplementalQuestion('bonus_4e_atom_4','Un atome est électriquement…',['Neutre','Toujours positif','Toujours négatif'],0,'Un atome possède autant de protons que d’électrons, donc sa charge totale est nulle.')]),

  SupplementalLesson('sixieme_echelle_plan_carte', SchoolLevel.sixieme, 'Géographie', 'Comprendre l’échelle d’un plan ou d’une carte',
    'L’échelle indique le rapport entre une distance mesurée sur une carte et la distance réelle. À l’échelle 1 : 100 000, 1 cm sur la carte représente 100 000 cm dans la réalité, soit 1 km.',
    'Pour convertir, utilise les mêmes unités avant de calculer. Exemple : sur une carte à l’échelle 1 : 50 000, 2 cm représentent 2 × 50 000 = 100 000 cm, soit 1 km. Une échelle graphique permet aussi de comparer directement une distance sur la carte à une distance réelle.',
    [SupplementalQuestion('bonus_6e_echelle_1','À l’échelle 1 : 100 000, 1 cm représente…',['100 m','1 km','10 km'],1,'100 000 cm = 1 000 m = 1 km.'),
     SupplementalQuestion('bonus_6e_echelle_2','À l’échelle 1 : 50 000, 2 cm représentent…',['500 m','1 km','5 km'],1,'2 × 50 000 cm = 100 000 cm = 1 km.'),
     SupplementalQuestion('bonus_6e_echelle_3','Pour calculer une distance réelle, il faut…',['Multiplier la distance de la carte par le dénominateur de l’échelle','Toujours diviser par 100','Ajouter les deux distances'],0,'À l’échelle numérique 1 : n, la distance réelle = distance carte × n, dans la même unité.'),
     SupplementalQuestion('bonus_6e_echelle_4','Avant de convertir une distance, il faut…',['Mettre les unités en cohérence','Ignorer les unités','Changer le titre de la carte'],0,'Les distances doivent être exprimées dans des unités cohérentes avant la conversion.')]),

  SupplementalLesson('premiere_tangente_derivee', SchoolLevel.premiere, 'Mathématiques', 'Déterminer l’équation d’une tangente',
    'Si une fonction f est dérivable en a, la tangente à sa courbe au point d’abscisse a a pour coefficient directeur f′(a). Elle passe par le point (a ; f(a)).',
    'Son équation est : y = f′(a)(x − a) + f(a). Exemple : f(x) = x² et a = 2. Alors f(2) = 4 et f′(2) = 4 ; la tangente a pour équation y = 4(x − 2) + 4, soit y = 4x − 4. Vérifie toujours le point de contact et la pente.',
    [SupplementalQuestion('bonus_1ere_tangente_1','Le coefficient directeur de la tangente en a est…',['f(a)','f′(a)','a + f(a)'],1,'La dérivée en a donne la pente de la tangente.'),
     SupplementalQuestion('bonus_1ere_tangente_2','Quelle est la formule de la tangente en a ?',['y = f′(a)(x − a) + f(a)','y = f(a)x + a','y = x² + a'],0,'La tangente passe par (a ; f(a)) et a pour pente f′(a).'),
     SupplementalQuestion('bonus_1ere_tangente_3','Pour f(x) = x², f′(x) = …',['x','2x','x²'],1,'La dérivée de x² est 2x.'),
     SupplementalQuestion('bonus_1ere_tangente_4','Pour f(x) = x² au point a = 2, la pente est…',['2','4','8'],1,'f′(2) = 2 × 2 = 4.')]),

  SupplementalLesson('terminale_logarithme_neperien', SchoolLevel.terminale, 'Mathématiques', 'Utiliser le logarithme népérien',
    'Le logarithme népérien, noté ln, est défini pour tout réel strictement positif. Il est la fonction réciproque de la fonction exponentielle : ln(eˣ) = x et e^(ln x) = x pour x > 0.',
    'Pour x > 0 et y > 0 : ln(xy) = ln x + ln y ; ln(x/y) = ln x − ln y ; ln(xⁿ) = n ln x pour tout réel n lorsque l’expression est définie. On a ln(1) = 0 et ln(e) = 1. Attention : ln(x + y) n’est généralement pas égal à ln x + ln y.',
    [SupplementalQuestion('bonus_terminale_ln_1','Le logarithme népérien ln(x) est défini pour…',['x > 0','Tout réel x','x < 0 seulement'],0,'Le domaine de ln est l’ensemble des réels strictement positifs.'),
     SupplementalQuestion('bonus_terminale_ln_2','ln(e) vaut…',['0','1','e'],1,'Le logarithme népérien de e est 1.'),
     SupplementalQuestion('bonus_terminale_ln_3','ln(xy) est égal à…',['ln x + ln y','ln x × ln y','ln(x + y)'],0,'Le logarithme d’un produit est la somme des logarithmes.'),
     SupplementalQuestion('bonus_terminale_ln_4','Quelle égalité est généralement fausse ?',['ln(x + y) = ln x + ln y','ln(xy) = ln x + ln y','ln(e) = 1'],0,'La formule du logarithme ne transforme pas une somme en somme de logarithmes.')]),
  SupplementalLesson('ce1_table_multiplication_3', SchoolLevel.ce1, 'Mathématiques', 'Apprendre la table de multiplication de 3',
    'Multiplier par 3, c’est additionner trois fois le même nombre. La table de 3 se construit en comptant de trois en trois : 3, 6, 9, 12, 15, 18, 21, 24, 27, 30.',
    'Exemples : 3 × 4 = 12 ; 3 × 7 = 21. La multiplication est commutative : 3 × 4 = 4 × 3. Pour mémoriser, récite la table puis vérifie avec des groupes de trois objets.',
    [SupplementalQuestion('bonus_ce1_table3_1','3 × 4 = …',['7','12','15'],1,'3 × 4 = 3 + 3 + 3 + 3 = 12.'),
     SupplementalQuestion('bonus_ce1_table3_2','3 × 6 = …',['18','16','21'],0,'3 × 6 = 18.'),
     SupplementalQuestion('bonus_ce1_table3_3','Quel calcul donne 24 ?',['3 × 6','3 × 8','3 × 9'],1,'3 × 8 = 24.'),
     SupplementalQuestion('bonus_ce1_table3_4','3 × 10 = …',['13','30','33'],1,'3 × 10 = 30.')]),

  SupplementalLesson('troisieme_moyenne_mediane', SchoolLevel.troisieme, 'Mathématiques', 'Calculer une moyenne et déterminer une médiane',
    'La moyenne d’une série est la somme de toutes les valeurs divisée par le nombre de valeurs. Elle donne une valeur centrale calculée, mais elle peut être influencée par une valeur très grande ou très petite.',
    'Pour déterminer la médiane, range d’abord les valeurs dans l’ordre croissant. Si l’effectif est impair, la médiane est la valeur du milieu. Si l’effectif est pair, on prend la moyenne des deux valeurs centrales. Exemple : 2, 4, 6, 8, 10 → moyenne = 6 et médiane = 6.',
    [SupplementalQuestion('bonus_3e_stats_1','La moyenne de 4, 6 et 8 est…',['6','8','18'],0,'(4 + 6 + 8) ÷ 3 = 18 ÷ 3 = 6.'),
     SupplementalQuestion('bonus_3e_stats_2','Avant de trouver la médiane, il faut…',['Ranger les valeurs','Multiplier toutes les valeurs','Supprimer la plus petite valeur'],0,'On ordonne les valeurs pour repérer le milieu.'),
     SupplementalQuestion('bonus_3e_stats_3','La médiane de 1, 3, 5, 7, 9 est…',['3','5','7'],1,'La valeur centrale de la série ordonnée est 5.'),
     SupplementalQuestion('bonus_3e_stats_4','La médiane de 2, 4, 6, 8 est…',['4','5','6'],1,'Les deux valeurs centrales sont 4 et 6 ; leur moyenne est 5.')]),

  SupplementalLesson('quatrieme_conservation_atomes_reaction', SchoolLevel.quatrieme, 'Physique-Chimie', 'Comprendre la conservation des atomes lors d’une réaction',
    'Lors d’une transformation chimique, les réactifs sont consommés et de nouvelles espèces chimiques, les produits, se forment. Les atomes ne disparaissent pas et ne sont pas créés : ils se réorganisent pour former les produits.',
    'Une équation chimique doit respecter la conservation des atomes de chaque élément. Exemple : 2 H₂ + O₂ → 2 H₂O. À gauche, il y a 4 atomes d’hydrogène et 2 d’oxygène ; à droite, également 4 hydrogènes et 2 oxygènes. Les coefficients placés devant les formules servent à équilibrer l’équation ; on ne modifie pas les indices des formules.',
    [SupplementalQuestion('bonus_4e_conservation_1','Lors d’une réaction chimique, les atomes…',['Se réorganisent','Disparaissent tous','Se transforment en énergie uniquement'],0,'Les atomes sont conservés et se réorganisent dans les produits.'),
     SupplementalQuestion('bonus_4e_conservation_2','Dans 2 H₂O, combien y a-t-il d’atomes d’hydrogène ?',['2','4','6'],1,'Chaque molécule H₂O contient 2 hydrogènes ; deux molécules en contiennent 4.'),
     SupplementalQuestion('bonus_4e_conservation_3','Pour équilibrer une équation, on modifie…',['Les coefficients','Les indices dans les formules','Les symboles des éléments'],0,'On ajuste les coefficients devant les formules, pas les indices.'),
     SupplementalQuestion('bonus_4e_conservation_4','Dans 2 H₂ + O₂ → 2 H₂O, le nombre d’atomes d’oxygène est…',['1 de chaque côté','2 de chaque côté','4 à gauche et 2 à droite'],1,'O₂ contient 2 oxygènes et 2 H₂O contiennent aussi 2 oxygènes.')]),

  // Renforcement ciblé : ces leçons complètent les niveaux qui avaient le moins de ressources bonus.
  SupplementalLesson('cm1_multiples_diviseurs', SchoolLevel.cm1, 'Mathématiques', 'Multiples et diviseurs',
    'Un multiple d’un nombre s’obtient en le multipliant par un entier. Un diviseur partage un nombre sans reste.',
    '24 est un multiple de 6 car 6 × 4 = 24. 5 est un diviseur de 20 car 20 ÷ 5 = 4.',
    [SupplementalQuestion('cm1_multiples_diviseurs_q1', '24 est un multiple de…', ['5', '6', '7'], 1, '6 × 4 = 24.'),
      SupplementalQuestion('cm1_multiples_diviseurs_q2', '20 est divisible par…', ['3', '5', '6'], 1, '20 ÷ 5 = 4, sans reste.'),
      SupplementalQuestion('cm1_multiples_diviseurs_q3', 'Lequel est un multiple de 8 ?', ['18', '24', '30'], 1, '8 × 3 = 24.')]),
  SupplementalLesson('cm1_mesure_masse', SchoolLevel.cm1, 'Mathématiques', 'Mesurer la masse',
    'La masse se mesure avec une balance. Le kilogramme (kg) et le gramme (g) sont des unités de masse. 1 kg = 1 000 g.',
    'Un sac de 2 kg a une masse de 2 000 g.',
    [SupplementalQuestion('cm1_mesure_masse_q1', '1 kg correspond à…', ['100 g', '1 000 g', '10 000 g'], 1, 'Un kilogramme vaut 1 000 grammes.'),
      SupplementalQuestion('cm1_mesure_masse_q2', '500 g + 500 g = …', ['1 kg', '2 kg', '100 g'], 0, '1 000 g font 1 kg.'),
      SupplementalQuestion('cm1_mesure_masse_q3', 'Quel instrument mesure la masse ?', ['Une balance', 'Une règle', 'Un thermomètre'], 0, 'La balance mesure la masse.')]),
  SupplementalLesson('cm2_aire_parallelogramme', SchoolLevel.cm2, 'Mathématiques', 'Aire du parallélogramme',
    'L’aire d’un parallélogramme se calcule en multipliant la longueur de sa base par sa hauteur perpendiculaire.',
    'Base 8 cm et hauteur 3 cm : A = 8 × 3 = 24 cm².',
    [SupplementalQuestion('cm2_aire_parallelogramme_q1', 'Quelle formule donne l’aire ?', ['base + hauteur', 'base × hauteur', '2 × (base + hauteur)'], 1, 'L’aire vaut base multipliée par hauteur.'),
      SupplementalQuestion('cm2_aire_parallelogramme_q2', 'Base 5 cm, hauteur 4 cm : aire ?', ['9 cm²', '20 cm²', '18 cm²'], 1, '5 × 4 = 20 cm².'),
      SupplementalQuestion('cm2_aire_parallelogramme_q3', 'La hauteur doit être…', ['perpendiculaire à la base', 'toujours égale à la base', 'le côté oblique'], 0, 'La hauteur est la distance perpendiculaire à la base.')]),
  SupplementalLesson('cm2_electricite_circuit', SchoolLevel.cm2, 'Sciences', 'Le circuit électrique simple',
    'Un circuit électrique fermé permet au courant de circuler. Une pile fournit l’énergie et une lampe peut éclairer si le circuit est fermé.',
    'Pile — fils — lampe reliés en boucle fermée : la lampe s’allume.',
    [SupplementalQuestion('cm2_electricite_circuit_q1', 'Quand la lampe s’allume-t-elle ?', ['Circuit fermé', 'Circuit ouvert', 'Sans pile'], 0, 'Le circuit doit être fermé et alimenté.'),
      SupplementalQuestion('cm2_electricite_circuit_q2', 'Quel élément fournit l’énergie ?', ['La pile', 'Le fil', 'Le support'], 0, 'La pile est le générateur.'),
      SupplementalQuestion('cm2_electricite_circuit_q3', 'Si le fil est débranché, le circuit est…', ['fermé', 'ouvert', 'plus puissant'], 1, 'Une coupure ouvre le circuit.')]),
  SupplementalLesson('sixieme_accord_determinant_nom', SchoolLevel.sixieme, 'Français', 'Accorder déterminant et nom',
    'Le déterminant s’accorde en genre et en nombre avec le nom qu’il accompagne : un garçon, une fille, des élèves.',
    'La petite maison ; les grands arbres.',
    [SupplementalQuestion('sixieme_accord_determinant_nom_q1', 'Choisis le groupe correct.', ['les arbre', 'les arbres', 'le arbres'], 1, '« Les » est pluriel : arbres prend -s.'),
      SupplementalQuestion('sixieme_accord_determinant_nom_q2', 'Quel déterminant convient à « école » ?', ['un', 'une', 'des'], 1, 'École est un nom féminin singulier.'),
      SupplementalQuestion('sixieme_accord_determinant_nom_q3', 'Complète : ___ cahiers (pluriel).', ['ce', 'ces', 'cet'], 1, '« Ces » accompagne un nom pluriel.')]),
  SupplementalLesson('sixieme_fraction_unite', SchoolLevel.sixieme, 'Mathématiques', 'Fractions égales à l’unité',
    'Une fraction représente une unité entière lorsque son numérateur est égal à son dénominateur, qui est non nul.',
    '3/3 = 1 ; 5/5 = 1.',
    [SupplementalQuestion('sixieme_fraction_unite_q1', '4/4 vaut…', ['0', '1', '4'], 1, 'Quatre parts sur quatre forment une unité.'),
      SupplementalQuestion('sixieme_fraction_unite_q2', 'Quelle fraction vaut 1 ?', ['2/3', '3/5', '7/7'], 2, 'Le numérateur et le dénominateur sont égaux.'),
      SupplementalQuestion('sixieme_fraction_unite_q3', '5/5 représente…', ['une moitié', 'une unité', 'cinq unités'], 1, 'Toutes les cinq parts sur cinq sont prises.')]),
  SupplementalLesson('cinquieme_energie_renouvelable', SchoolLevel.cinquieme, 'Sciences', 'Énergies renouvelables',
    'Une énergie renouvelable provient d’une source qui se renouvelle naturellement à l’échelle humaine, comme le soleil, le vent ou l’eau en mouvement.',
    'Un panneau solaire transforme l’énergie lumineuse du soleil en énergie électrique.',
    [SupplementalQuestion('cinquieme_energie_renouvelable_q1', 'Quelle source est renouvelable ?', ['Le soleil', 'Le charbon', 'Le pétrole'], 0, 'Le rayonnement solaire se renouvelle naturellement.'),
      SupplementalQuestion('cinquieme_energie_renouvelable_q2', 'Une éolienne utilise…', ['le vent', 'le pétrole', 'le charbon'], 0, 'Les pales tournent grâce au vent.'),
      SupplementalQuestion('cinquieme_energie_renouvelable_q3', 'Le pétrole est…', ['renouvelable', 'non renouvelable', 'inépuisable'], 1, 'Le pétrole se forme très lentement.')]),
  SupplementalLesson('cinquieme_adverbe', SchoolLevel.cinquieme, 'Français', 'Reconnaître l’adverbe',
    'L’adverbe précise souvent un verbe, un adjectif ou un autre adverbe. Il peut indiquer la manière, le temps ou le lieu.',
    'Elle parle doucement. « Doucement » précise le verbe parle.',
    [SupplementalQuestion('cinquieme_adverbe_q1', 'Dans « Il court vite », quel est l’adverbe ?', ['court', 'vite', 'il'], 1, 'Vite précise comment il court.'),
      SupplementalQuestion('cinquieme_adverbe_q2', 'Quel mot est un adverbe ?', ['hier', 'maison', 'beau'], 0, 'Hier indique le temps.'),
      SupplementalQuestion('cinquieme_adverbe_q3', 'L’adverbe « très » précise souvent…', ['un nom', 'un adjectif ou un adverbe', 'un article'], 1, 'Exemple : très grand, très vite.')]),
  SupplementalLesson('quatrieme_puissance_dix', SchoolLevel.quatrieme, 'Mathématiques', 'Puissances de 10',
    'Une puissance de 10 s’écrit 10ⁿ. Pour n positif, 10ⁿ est égal à 1 suivi de n zéros.',
    '10³ = 1 000 et 10⁴ = 10 000.',
    [SupplementalQuestion('quatrieme_puissance_dix_q1', '10² vaut…', ['20', '100', '1 000'], 1, '10 × 10 = 100.'),
      SupplementalQuestion('quatrieme_puissance_dix_q2', '10⁴ vaut…', ['1 000', '10 000', '100 000'], 1, 'Quatre facteurs 10 donnent 10 000.'),
      SupplementalQuestion('quatrieme_puissance_dix_q3', '0,01 s’écrit…', ['10⁻¹', '10⁻²', '10²'], 1, '10⁻² = 1/100 = 0,01.')]),
  SupplementalLesson('quatrieme_reproduction_plantes', SchoolLevel.quatrieme, 'SVT', 'La reproduction des plantes à fleurs',
    'La fleur porte les organes reproducteurs. Après la pollinisation et la fécondation, l’ovule devient une graine et l’ovaire se transforme généralement en fruit.',
    'Le pollen peut être transporté par les insectes ou le vent.',
    [SupplementalQuestion('quatrieme_reproduction_plantes_q1', 'Le pollen est produit par…', ['les étamines', 'les racines', 'les feuilles'], 0, 'Les étamines portent les sacs polliniques.'),
      SupplementalQuestion('quatrieme_reproduction_plantes_q2', 'Après fécondation, l’ovule devient…', ['une graine', 'une racine', 'un pétale'], 0, 'L’ovule fécondé se développe en graine.'),
      SupplementalQuestion('quatrieme_reproduction_plantes_q3', 'La pollinisation correspond au transport…', ['du pollen', 'de l’eau dans la racine', 'des graines dans le fruit'], 0, 'La pollinisation transporte le pollen vers le stigmate.')]),
  SupplementalLesson('troisieme_statistiques_etendue', SchoolLevel.troisieme, 'Mathématiques', 'L’étendue d’une série',
    'L’étendue mesure la dispersion entre la plus grande et la plus petite valeur. On calcule : maximum − minimum.',
    'Pour 4, 7, 9, 12 : étendue = 12 − 4 = 8.',
    [SupplementalQuestion('troisieme_statistiques_etendue_q1', 'Étendue de 2, 5, 8 ?', ['3', '6', '10'], 1, '8 − 2 = 6.'),
      SupplementalQuestion('troisieme_statistiques_etendue_q2', 'Pour calculer l’étendue, on fait…', ['max + min', 'max − min', 'min ÷ max'], 1, 'L’étendue est la différence entre maximum et minimum.'),
      SupplementalQuestion('troisieme_statistiques_etendue_q3', 'Étendue de 10, 10, 15, 20 ?', ['10', '15', '20'], 0, '20 − 10 = 10.')]),
  SupplementalLesson('troisieme_energie_electrique', SchoolLevel.troisieme, 'Physique-Chimie', 'Puissance et énergie électrique',
    'L’énergie électrique consommée se calcule par E = P × t, avec une puissance en watts et un temps en heures pour obtenir des wattheures.',
    'Un appareil de 100 W utilisé 2 h consomme 200 Wh, soit 0,2 kWh.',
    [SupplementalQuestion('troisieme_energie_electrique_q1', '100 W pendant 3 h consomment…', ['100 Wh', '300 Wh', '30 Wh'], 1, 'E = 100 × 3 = 300 Wh.'),
      SupplementalQuestion('troisieme_energie_electrique_q2', '1 kWh correspond à…', ['100 Wh', '1 000 Wh', '10 000 Wh'], 1, 'Le préfixe kilo signifie mille.'),
      SupplementalQuestion('troisieme_energie_electrique_q3', 'Pour calculer l’énergie, on multiplie…', ['P par t', 'P par U', 't par R'], 0, 'La relation est E = P × t.')]),
  SupplementalLesson('seconde_vecteurs_coordonnees', SchoolLevel.seconde, 'Mathématiques', 'Coordonnées d’un vecteur',
    'Dans un repère, si A(xA ; yA) et B(xB ; yB), alors le vecteur AB a pour coordonnées (xB − xA ; yB − yA).',
    'A(1 ; 2), B(4 ; 6) : AB = (3 ; 4).',
    [SupplementalQuestion('seconde_vecteurs_coordonnees_q1', 'A(2;1), B(5;4) : AB = …', ['(3;3)', '(7;5)', '(-3;-3)'], 0, '5 − 2 = 3 et 4 − 1 = 3.'),
      SupplementalQuestion('seconde_vecteurs_coordonnees_q2', 'Les coordonnées de AB se calculent…', ['A − B', 'B − A', 'A + B'], 1, 'On soustrait les coordonnées de A à celles de B.'),
      SupplementalQuestion('seconde_vecteurs_coordonnees_q3', 'A(0;0), B(-2;3) : AB = …', ['(2;-3)', '(-2;3)', '(0;3)'], 1, 'Depuis l’origine, le vecteur a les coordonnées de B.')]),
  SupplementalLesson('seconde_chaines_alimentaires', SchoolLevel.seconde, 'SVT', 'Chaînes alimentaires et réseaux',
    'Une chaîne alimentaire montre qui mange qui. Les flèches vont de l’organisme mangé vers celui qui le mange et indiquent le transfert de matière.',
    'Herbe → criquet → grenouille → serpent.',
    [SupplementalQuestion('seconde_chaines_alimentaires_q1', 'Dans une chaîne, la flèche indique…', ['le transfert vers le consommateur', 'la direction du vent', 'le lieu de vie'], 0, 'Elle va de l’aliment vers l’organisme qui le consomme.'),
      SupplementalQuestion('seconde_chaines_alimentaires_q2', 'Quel organisme est souvent producteur ?', ['une plante verte', 'un lion', 'un champignon'], 0, 'Les plantes fabriquent leur matière organique par photosynthèse.'),
      SupplementalQuestion('seconde_chaines_alimentaires_q3', 'Herbe → lapin → renard. Le lapin mange…', ['le renard', 'l’herbe', 'les deux'], 1, 'Le lapin est consommateur de l’herbe.')]),
  SupplementalLesson('seconde_anglais_present_simple', SchoolLevel.seconde, 'Anglais', 'Le présent simple en anglais',
    'Le présent simple exprime les habitudes et les faits généraux. À la troisième personne du singulier, le verbe prend souvent -s.',
    'I play football. She plays football.',
    [SupplementalQuestion('seconde_anglais_present_simple_q1', 'Complète : He ___ to school.', ['go', 'goes', 'going'], 1, 'À la troisième personne du singulier, go devient goes.'),
      SupplementalQuestion('seconde_anglais_present_simple_q2', 'Le présent simple exprime souvent…', ['une habitude', 'une action passée', 'une action en cours obligatoirement'], 0, 'Il sert notamment à parler des routines.'),
      SupplementalQuestion('seconde_anglais_present_simple_q3', 'Complète : They ___ English.', ['speaks', 'speak', 'speaking'], 1, 'Avec they, le verbe reste à la forme de base.')]),
  SupplementalLesson('premiere_derivation_produit', SchoolLevel.premiere, 'Mathématiques', 'Dérivée d’un produit',
    'Pour deux fonctions dérivables u et v, (uv)’ = u’v + uv’. Il faut dériver chaque facteur à tour de rôle et additionner.',
    '(x² × x)’ = 2x × x + x² × 1 = 3x².',
    [SupplementalQuestion('premiere_derivation_produit_q1', 'Quelle est la formule de (uv)’ ?', ['u’v + uv’', 'u’v’', 'u + v'], 0, 'La dérivée du produit est u’v + uv’.'),
      SupplementalQuestion('premiere_derivation_produit_q2', 'Dérivée de x × x² ?', ['2x', '3x²', 'x³'], 1, 'x × x² = x³, donc la dérivée est 3x².'),
      SupplementalQuestion('premiere_derivation_produit_q3', 'Dérivée de (x+1)(x) ?', ['2x+1', 'x+1', 'x²+1'], 0, 'Développer donne x²+x, puis 2x+1.')]),
  SupplementalLesson('premiere_suite_geometrique', SchoolLevel.premiere, 'Mathématiques', 'Suites géométriques',
    'Une suite est géométrique lorsque chaque terme s’obtient en multipliant le précédent par une constante q appelée raison : uₙ₊₁ = q uₙ.',
    'Si u₀ = 3 et q = 2, alors u₁ = 6 et u₂ = 12.',
    [SupplementalQuestion('premiere_suite_geometrique_q1', 'Une suite géométrique vérifie…', ['uₙ₊₁ = uₙ + q', 'uₙ₊₁ = q × uₙ', 'uₙ₊₁ = n × uₙ'], 1, 'On multiplie chaque terme par la raison.'),
      SupplementalQuestion('premiere_suite_geometrique_q2', 'u₀=4, q=3 : u₁ = …', ['7', '12', '1'], 1, '4 × 3 = 12.'),
      SupplementalQuestion('premiere_suite_geometrique_q3', 'La raison de 5, 10, 20, 40 est…', ['2', '5', '10'], 0, 'Chaque terme est multiplié par 2.')]),
  SupplementalLesson('premiere_probabilite_independante', SchoolLevel.premiere, 'Mathématiques', 'Événements indépendants',
    'Deux événements A et B sont indépendants si P(A∩B) = P(A) × P(B). La réalisation de l’un ne modifie pas la probabilité de l’autre.',
    'Si P(A)=0,5 et P(B)=0,2, alors P(A∩B)=0,1 lorsque A et B sont indépendants.',
    [SupplementalQuestion('premiere_probabilite_independante_q1', 'Pour des événements indépendants…', ['P(A∩B)=P(A)P(B)', 'P(A∩B)=P(A)+P(B)', 'P(A)=P(B)'], 0, 'C’est la relation caractéristique de l’indépendance.'),
      SupplementalQuestion('premiere_probabilite_independante_q2', '0,5 × 0,2 = …', ['0,7', '0,1', '1'], 1, 'La multiplication donne 0,10.'),
      SupplementalQuestion('premiere_probabilite_independante_q3', 'L’indépendance signifie que…', ['A et B sont impossibles', 'A ne change pas la probabilité de B', 'A et B ont la même probabilité'], 1, 'La connaissance de A ne modifie pas P(B).')]),
  SupplementalLesson('premiere_lecture_graphique_derivative', SchoolLevel.premiere, 'Mathématiques', 'Lire le signe de la dérivée',
    'Si la dérivée f’ est positive sur un intervalle, la fonction f y est croissante. Si f’ est négative, f y est décroissante.',
    'f’(x) > 0 sur ]a ; b[ implique que f est croissante sur cet intervalle.',
    [SupplementalQuestion('premiere_lecture_graphique_derivative_q1', 'Si f’ est positive, f est…', ['croissante', 'décroissante', 'constante forcément'], 0, 'Une dérivée positive indique une croissance.'),
      SupplementalQuestion('premiere_lecture_graphique_derivative_q2', 'Si f’ est négative, f est…', ['croissante', 'décroissante', 'toujours nulle'], 1, 'Une dérivée négative indique une décroissance.'),
      SupplementalQuestion('premiere_lecture_graphique_derivative_q3', 'Si f’=0 partout sur un intervalle, f est…', ['constante', 'strictement croissante', 'strictement décroissante'], 0, 'Une dérivée nulle indique une fonction constante.')]),
  SupplementalLesson('terminale_integrale_primitive', SchoolLevel.terminale, 'Mathématiques', 'Primitives et intégrales simples',
    'Une primitive F de f vérifie F’ = f. L’intégrale de a à b de f(x) dx vaut F(b) − F(a) lorsque F est une primitive sur l’intervalle.',
    'Une primitive de 2x est x² ; ∫₀² 2x dx = 4 − 0 = 4.',
    [SupplementalQuestion('terminale_integrale_primitive_q1', 'Une primitive F vérifie…', ['F=f’', 'F’=f', 'F’=0'], 1, 'Par définition, la dérivée de F est f.'),
      SupplementalQuestion('terminale_integrale_primitive_q2', 'Une primitive de 3x² est…', ['x³', '3x³', 'x²'], 0, 'La dérivée de x³ est 3x².'),
      SupplementalQuestion('terminale_integrale_primitive_q3', '∫₀¹ 2 dx vaut…', ['1', '2', '0'], 1, 'La fonction est constante 2 sur un intervalle de longueur 1.')]),
  SupplementalLesson('terminale_loi_binomiale', SchoolLevel.terminale, 'Mathématiques', 'Loi binomiale',
    'Une variable suit une loi binomiale B(n,p) si elle compte les succès de n épreuves de Bernoulli indépendantes, chacune de probabilité p.',
    'Pour X~B(n,p), P(X=k)=C(n,k)pᵏ(1−p)ⁿ⁻ᵏ.',
    [SupplementalQuestion('terminale_loi_binomiale_q1', 'La loi binomiale compte…', ['les succès de n essais indépendants', 'les valeurs d’une fonction continue', 'uniquement les échecs'], 0, 'Elle modélise un nombre de succès.'),
      SupplementalQuestion('terminale_loi_binomiale_q2', 'Pour une épreuve de Bernoulli, il y a…', ['deux issues possibles', 'trois issues obligatoires', 'une issue'], 0, 'Succès ou échec.'),
      SupplementalQuestion('terminale_loi_binomiale_q3', 'L’espérance de B(n,p) est…', ['n+p', 'np', 'n/p'], 1, 'L’espérance vaut n fois p.')]),
  SupplementalLesson('terminale_complexes_module', SchoolLevel.terminale, 'Mathématiques', 'Module d’un nombre complexe',
    'Pour z=a+bi, le module est |z|=√(a²+b²). Il représente la distance du point associé à l’origine du plan complexe.',
    'z=3+4i : |z|=√(9+16)=5.',
    [SupplementalQuestion('terminale_complexes_module_q1', 'Module de 3+4i ?', ['5', '7', '25'], 0, '√(3²+4²)=√25=5.'),
      SupplementalQuestion('terminale_complexes_module_q2', 'Module de a+bi vaut…', ['a+b', '√(a²+b²)', 'a²+b²'], 1, 'Le module est la racine carrée de la somme des carrés.'),
      SupplementalQuestion('terminale_complexes_module_q3', 'Le module est toujours…', ['négatif', 'positif ou nul', 'imaginaire pur'], 1, 'Une distance ne peut pas être négative.')]),
  SupplementalLesson('terminale_philosophie_argumentation', SchoolLevel.terminale, 'Philosophie', 'Construire une argumentation',
    'Une dissertation philosophique présente un problème, développe des arguments organisés, examine des objections et propose une conclusion répondant à la question.',
    'Pour discuter « La liberté consiste-t-elle à faire tout ce que l’on veut ? », distinguer désir, choix et responsabilité.',
    [SupplementalQuestion('terminale_philosophie_argumentation_q1', 'Une dissertation commence par…', ['une problématique claire', 'une liste sans lien', 'la conclusion'], 0, 'L’introduction fait émerger le problème.'),
      SupplementalQuestion('terminale_philosophie_argumentation_q2', 'Un argument doit être…', ['justifié et expliqué', 'seulement répété', 'sans rapport avec le sujet'], 0, 'Il faut soutenir une idée par un raisonnement.'),
      SupplementalQuestion('terminale_philosophie_argumentation_q3', 'Une objection sert à…', ['examiner une limite ou un point de vue contraire', 'remplacer le sujet', 'éviter toute conclusion'], 0, 'L’objection permet de nuancer et discuter la thèse.')]),

  SupplementalLesson('cp1_sons_m_et_n', SchoolLevel.cp1, 'Français', 'Reconnaître les sons m et n',
    'Écoute le début des mots. La lettre m fait le son /m/ comme maman ; la lettre n fait le son /n/ comme nez.',
    'm → moto, maman ; n → nez, nuit.',
    [SupplementalQuestion('cp1_sons_m_n_q1', 'Quel mot commence par m ?', ['moto', 'nez', 'nid'], 0, 'Moto commence par m.'),
      SupplementalQuestion('cp1_sons_m_n_q2', 'Quel mot commence par n ?', ['maman', 'nuit', 'papa'], 1, 'Nuit commence par n.'),
      SupplementalQuestion('cp1_sons_m_n_q3', 'Quelle lettre fait le son /m/ ?', ['n', 'm', 's'], 1, 'La lettre m fait le son /m/.')]),
  SupplementalLesson('cp2_lire_heure_pleine', SchoolLevel.cp2, 'Mathématiques', 'Lire l’heure pleine',
    'La petite aiguille indique les heures et la grande aiguille indique les minutes. Quand la grande aiguille est sur 12, il est une heure pleine.',
    'Petite aiguille sur 4 et grande sur 12 : 4 heures.',
    [SupplementalQuestion('cp2_heure_pleine_q1', 'La grande aiguille est sur 12. Cela indique…', ['une heure pleine', 'un quart d’heure', 'une demi-heure'], 0, 'Sur 12, la grande aiguille indique zéro minute.'),
      SupplementalQuestion('cp2_heure_pleine_q2', 'La petite aiguille est sur 7 et la grande sur 12. Il est…', ['7 h', '12 h 7', '6 h'], 0, 'Il est sept heures.'),
      SupplementalQuestion('cp2_heure_pleine_q3', 'Quelle aiguille indique les heures ?', ['la grande', 'la petite', 'les deux toujours'], 1, 'La petite aiguille indique les heures.')]),
  SupplementalLesson('ce1_monnaie_fcfa', SchoolLevel.ce1, 'Mathématiques', 'Calculer avec les pièces en FCFA',
