    '3² + 4² = 9 + 16 = 25 = 5² : un triangle de côtés 3, 4 et 5 est rectangle.',
    [SupplementalQuestion('troisieme_pythagore_reciproque_q1', 'Pour des côtés 3, 4 et 5, on vérifie…', ['3²+4²=5²', '3+4=5²', '3²+5²=4²'], 0, '9 + 16 = 25.'),
