      SupplementalQuestion('seconde_masse_poids_q2', 'Le poids s’exprime en…', ['kg', 'N', 'L'], 1, 'Le poids est une force, exprimée en newtons.'),
      SupplementalQuestion('seconde_masse_poids_q3', 'Avec m=3 kg et g=10 N/kg, P vaut…', ['30 N', '3 N', '13 N'], 0, 'P = 3 × 10 = 30 N.')]),
  SupplementalLesson('premiere_oxydoreduction', SchoolLevel.premiere, 'Chimie', 'Reconnaître une réaction d’oxydoréduction',
