      SupplementalQuestion('premiere_redox_q2', 'Une oxydation correspond à…', ['un gain d’électrons', 'une perte d’électrons', 'un gain de neutrons'], 1, 'Oxydation = perte d’électrons.'),
      SupplementalQuestion('premiere_redox_q3', 'Zn → Zn²⁺ + 2e⁻ est…', ['une oxydation', 'une réduction', 'une dissolution sans échange'], 0, 'Le zinc perd deux électrons.')]),
  SupplementalLesson('terminale_genetique_expression', SchoolLevel.terminale, 'SVT', 'Comprendre l’expression d’un gène',
