    [SupplementalQuestion('terminale_expression_gene_q1', 'L’information génétique est portée par…', ['l’ADN', 'le glucose', 'le dioxyde de carbone'], 0, 'L’ADN porte l’information génétique.'),
      SupplementalQuestion('terminale_expression_gene_q2', 'La transcription produit…', ['un ARN', 'une protéine directement', 'un lipide'], 0, 'La transcription copie l’information d’ADN en ARN.'),
      SupplementalQuestion('terminale_expression_gene_q3', 'La traduction permet la synthèse…', ['d’une protéine', 'd’un chromosome entier', 'de l’eau'], 0, 'Le ribosome traduit l’ARN messager en chaîne polypeptidique.')]),

