      SupplementalQuestion('terminale_ph_q3', 'Une solution de pH 10 est…', ['basique', 'acide', 'neutre'], 0, 'Un pH supérieur à 7 indique une solution basique.')]),
  SupplementalLesson("cp1_renforcement_annuel_1", SchoolLevel.cp1, "Français", "Écouter et raconter une petite histoire",
