      SupplementalQuestion("extra_ce2_renforcement_annuel_7_q3", "Quel pays se trouve à l’est du Togo ?", ["Le Bénin", "Le Ghana", "Le Sénégal"], 0, "Le Bénin est voisin à l’est.")]),
