    "Le Togo comprend plusieurs régions administratives. Les paysages et les activités varient du littoral aux régions du nord.",
    "Le littoral est au sud ; les régions septentrionales sont plus au nord.",
    [SupplementalQuestion("extra_cm1_renforcement_annuel_10_q1", "Le littoral togolais se situe…", ["Au nord", "Au sud", "À l’est du Ghana"], 1, "Le Togo possède une façade maritime au sud."),
      SupplementalQuestion("extra_cm1_renforcement_annuel_10_q2", "Les régions du nord sont…", ["Au sud du littoral", "Dans l’océan", "Au-dessus du centre sur une carte orientée au nord"], 2, "Le nord se situe en haut d’une carte orientée au nord."),
      SupplementalQuestion("extra_cm1_renforcement_annuel_10_q3", "Les activités et paysages peuvent…", ["Varier selon les régions", "Être exactement identiques partout", "Ne dépendre jamais du milieu"], 0, "Le milieu géographique influence les activités et paysages.")]),
  SupplementalLesson("cm1_renforcement_annuel_11", SchoolLevel.cm1, "Sciences", "Les aliments et une alimentation équilibrée",
    "Les aliments apportent énergie et éléments nécessaires au corps. Varier les aliments aide à couvrir les besoins nutritionnels.",
    "Associer céréales, légumes, fruits et sources de protéines contribue à une alimentation variée.",
    [SupplementalQuestion("extra_cm1_renforcement_annuel_11_q1", "Pourquoi mange-t-on ?", ["Pour remplacer l’air", "Pour fournir énergie et nutriments", "Pour arrêter de grandir"], 1, "Les aliments apportent énergie et nutriments."),
      SupplementalQuestion("extra_cm1_renforcement_annuel_11_q2", "Une alimentation équilibrée doit être…", ["Composée d’un seul aliment", "Sans eau", "Variée"], 2, "La variété aide à couvrir différents besoins."),
      SupplementalQuestion("extra_cm1_renforcement_annuel_11_q3", "Quel aliment peut apporter des protéines ?", ["Haricots", "Sucre seul", "Eau pure"], 0, "Les haricots sont une source végétale de protéines.")]),
  SupplementalLesson("cm2_renforcement_annuel_12", SchoolLevel.cm2, "Mathématiques", "Additionner et soustraire des nombres décimaux",
    "Aligne les virgules, puis additionne ou soustrais les chiffres de même rang. Ajoute des zéros si nécessaire.",
    "12,5 + 3,25 = 15,75.",
    [SupplementalQuestion("extra_cm2_renforcement_annuel_12_q1", "12,5 + 3,25 = …", ["15,25", "15,75", "16,75"], 1, "12,50 + 3,25 = 15,75."),
      SupplementalQuestion("extra_cm2_renforcement_annuel_12_q2", "8,4 − 2,15 = …", ["6,35", "5,25", "6,25"], 2, "8,40 − 2,15 = 6,25."),
      SupplementalQuestion("extra_cm2_renforcement_annuel_12_q3", "Pour calculer correctement, il faut…", ["Aligner les virgules", "Supprimer les virgules", "Aligner seulement les unités"], 0, "Les virgules doivent être alignées.")]),
  SupplementalLesson("cm2_renforcement_annuel_13", SchoolLevel.cm2, "Éducation civique", "Droits et devoirs de l’élève",
    "L’élève a droit à l’éducation, à la protection et au respect. Il doit aussi respecter les règles, les personnes et le matériel scolaire.",
    "J’ai le droit d’apprendre et le devoir de respecter mes camarades.",
    [SupplementalQuestion("extra_cm2_renforcement_annuel_13_q1", "Quel est un droit de l’élève ?", ["Casser le matériel", "Recevoir une éducation", "Empêcher les autres d’apprendre"], 1, "L’éducation est un droit de l’enfant."),
      SupplementalQuestion("extra_cm2_renforcement_annuel_13_q2", "Quel est un devoir à l’école ?", ["Insulter les camarades", "Abîmer les livres", "Respecter les règles"], 2, "Respecter les règles favorise la vie scolaire."),
      SupplementalQuestion("extra_cm2_renforcement_annuel_13_q3", "Le matériel commun doit être…", ["Protégé et partagé", "Détruit", "Caché aux autres"], 0, "Le matériel commun sert à tous.")]),
  SupplementalLesson("sixieme_renforcement_annuel_14", SchoolLevel.sixieme, "Histoire", "Les premières civilisations et les fleuves",
    "Les grandes civilisations anciennes se sont souvent développées près de fleuves qui fournissaient de l’eau, des terres fertiles et des voies de transport.",
    "L’Égypte ancienne s’est développée autour du Nil.",
    [SupplementalQuestion("extra_sixieme_renforcement_annuel_14_q1", "Quel fleuve est associé à l’Égypte ancienne ?", ["Le Niger", "Le Nil", "Le Congo"], 1, "Le Nil a joué un rôle central dans l’Égypte ancienne."),
      SupplementalQuestion("extra_sixieme_renforcement_annuel_14_q2", "Pourquoi les fleuves favorisaient-ils les civilisations ?", ["Absence totale d’agriculture", "Ils empêchaient tout transport", "Eau et terres fertiles"], 2, "Les fleuves soutenaient l’agriculture et les échanges."),
      SupplementalQuestion("extra_sixieme_renforcement_annuel_14_q3", "L’agriculture ancienne dépendait souvent…", ["De l’eau disponible", "Des satellites", "De l’électricité moderne"], 0, "L’eau était essentielle aux cultures.")]),
  SupplementalLesson("sixieme_renforcement_annuel_15", SchoolLevel.sixieme, "Mathématiques", "Mesurer et construire un angle",
    "Un angle se mesure en degrés avec un rapporteur. L’angle droit mesure 90°, l’angle aigu moins de 90° et l’angle obtus plus de 90° et moins de 180°.",
    "Un angle de 45° est aigu ; un angle de 120° est obtus.",
    [SupplementalQuestion("extra_sixieme_renforcement_annuel_15_q1", "Un angle droit mesure…", ["45°", "90°", "180°"], 1, "La mesure d’un angle droit est 90°."),
      SupplementalQuestion("extra_sixieme_renforcement_annuel_15_q2", "Un angle de 35° est…", ["Droit", "Obtus", "Aigu"], 2, "35° est inférieur à 90°."),
      SupplementalQuestion("extra_sixieme_renforcement_annuel_15_q3", "Quel instrument mesure un angle ?", ["Un rapporteur", "Une balance", "Un compas magnétique"], 0, "Le rapporteur sert à mesurer les angles.")]),
  SupplementalLesson("cinquieme_renforcement_annuel_16", SchoolLevel.cinquieme, "Géographie", "Météo et climat dans les régions du Togo",
    "La météo décrit l’état de l’atmosphère à court terme. Le climat correspond aux conditions habituelles observées sur une longue période.",
    "Une pluie aujourd’hui relève de la météo ; les saisons habituelles relèvent du climat.",
    [SupplementalQuestion("extra_cinquieme_renforcement_annuel_16_q1", "La météo décrit…", ["Les conditions sur plusieurs siècles uniquement", "Le temps à court terme", "La population"], 1, "La météo concerne les conditions immédiates ou à court terme."),
      SupplementalQuestion("extra_cinquieme_renforcement_annuel_16_q2", "Le climat s’étudie sur…", ["Une seule minute", "Une seule journée seulement", "Une longue période"], 2, "Le climat repose sur des observations longues."),
      SupplementalQuestion("extra_cinquieme_renforcement_annuel_16_q3", "Une saison sèche régulière fait partie…", ["Du climat", "D’une mesure de masse", "D’une carte routière"], 0, "Les saisons habituelles caractérisent le climat.")]),
  SupplementalLesson("cinquieme_renforcement_annuel_17", SchoolLevel.cinquieme, "SVT", "Le système respiratoire",
    "L’air entre par les voies respiratoires et arrive aux poumons. Les échanges gazeux permettent au corps de prendre de l’oxygène et de rejeter du dioxyde de carbone.",
    "Lors de la respiration, l’oxygène passe des alvéoles vers le sang.",
    [SupplementalQuestion("extra_cinquieme_renforcement_annuel_17_q1", "Quel organe principal permet la respiration ?", ["L’estomac", "Les poumons", "Le foie"], 1, "Les poumons assurent les échanges gazeux."),
      SupplementalQuestion("extra_cinquieme_renforcement_annuel_17_q2", "Quel gaz le corps prélève-t-il dans l’air ?", ["Le dioxyde de carbone uniquement", "L’hélium", "L’oxygène"], 2, "Le corps utilise l’oxygène pour ses activités."),
      SupplementalQuestion("extra_cinquieme_renforcement_annuel_17_q3", "Quel gaz est rejeté en quantité lors de l’expiration ?", ["Le dioxyde de carbone", "L’oxygène uniquement", "L’azote produit par le cœur"], 0, "Le corps rejette le dioxyde de carbone.")]),
  SupplementalLesson("quatrieme_renforcement_annuel_18", SchoolLevel.quatrieme, "Physique-Chimie", "Identifier une transformation chimique",
    "Lors d’une transformation chimique, des réactifs disparaissent et de nouvelles substances, appelées produits, se forment. La masse totale se conserve dans un système fermé.",
    "La combustion transforme un combustible et le dioxygène en nouveaux produits.",
    [SupplementalQuestion("extra_quatrieme_renforcement_annuel_18_q1", "Les substances de départ sont…", ["Les produits", "Les réactifs", "Les instruments"], 1, "Les réactifs sont présents avant la transformation."),
      SupplementalQuestion("extra_quatrieme_renforcement_annuel_18_q2", "Les substances formées sont…", ["Les réactifs", "Les unités", "Les produits"], 2, "Les produits se forment pendant la réaction."),
      SupplementalQuestion("extra_quatrieme_renforcement_annuel_18_q3", "Dans un système fermé, la masse totale…", ["Se conserve", "Disparaît toujours", "Double sans cause"], 0, "La masse se conserve lors d’une transformation chimique en système fermé.")]),
  SupplementalLesson("quatrieme_renforcement_annuel_19", SchoolLevel.quatrieme, "Mathématiques", "Développer une expression simple",
    "La distributivité permet de multiplier un nombre par une somme : a(b+c)=ab+ac. Attention au signe devant les parenthèses.",
    "3(x+4)=3x+12.",
    [SupplementalQuestion("extra_quatrieme_renforcement_annuel_19_q1", "2(x+5) = …", ["2x + 5", "2x + 10", "x + 10"], 1, "On multiplie 2 par x puis par 5."),
      SupplementalQuestion("extra_quatrieme_renforcement_annuel_19_q2", "4(a−2) = …", ["4a − 2", "a − 8", "4a − 8"], 2, "4 × a − 4 × 2 = 4a − 8."),
      SupplementalQuestion("extra_quatrieme_renforcement_annuel_19_q3", "La distributivité sert à…", ["Développer une expression", "Mesurer une masse", "Calculer une durée"], 0, "Elle transforme un produit en somme ou différence.")]),
  SupplementalLesson("troisieme_renforcement_annuel_20", SchoolLevel.troisieme, "Histoire", "Les grandes étapes de l’indépendance du Togo",
    "Le Togo a connu une période de tutelle internationale après la Première Guerre mondiale. Le pays accède à l’indépendance le 27 avril 1960.",
    "La date de l’indépendance du Togo est le 27 avril 1960.",
    [SupplementalQuestion("extra_troisieme_renforcement_annuel_20_q1", "Le Togo devient indépendant le…", ["1er janvier 1950", "27 avril 1960", "13 août 1965"], 1, "L’indépendance du Togo est proclamée le 27 avril 1960."),
      SupplementalQuestion("extra_troisieme_renforcement_annuel_20_q2", "La date du 27 avril est célébrée comme…", ["La rentrée scolaire", "La fête des récoltes", "La fête de l’indépendance"], 2, "Le 27 avril est la fête nationale de l’indépendance."),
      SupplementalQuestion("extra_troisieme_renforcement_annuel_20_q3", "L’indépendance signifie notamment…", ["La souveraineté d’un pays", "La disparition de toutes les lois", "La fin de toute citoyenneté"], 0, "L’indépendance marque la souveraineté nationale.")]),
  SupplementalLesson("troisieme_renforcement_annuel_21", SchoolLevel.troisieme, "Physique-Chimie", "La puissance et l’énergie électrique",
    "La puissance électrique P se mesure en watts. L’énergie consommée dépend de la puissance et de la durée : E = P × t.",
    "Un appareil de 100 W utilisé 2 h consomme 200 Wh.",
    [SupplementalQuestion("extra_troisieme_renforcement_annuel_21_q1", "La puissance électrique se mesure en…", ["Kilogramme", "Watt", "Mètre"], 1, "Le watt est l’unité de puissance."),
      SupplementalQuestion("extra_troisieme_renforcement_annuel_21_q2", "100 W pendant 2 h donnent…", ["50 Wh", "100 W/h", "200 Wh"], 2, "E = 100 × 2 = 200 Wh."),
      SupplementalQuestion("extra_troisieme_renforcement_annuel_21_q3", "Pour diminuer l’énergie consommée, on peut…", ["Réduire la durée d’utilisation", "Laisser l’appareil allumé plus longtemps", "Augmenter toujours la puissance"], 0, "L’énergie dépend de la puissance et de la durée.")]),
  SupplementalLesson("seconde_renforcement_annuel_22", SchoolLevel.seconde, "Géographie", "La population et la densité",
    "La densité de population est le nombre d’habitants par unité de surface. Elle se calcule en divisant la population par la superficie.",
    "100 000 habitants sur 500 km² : densité = 200 habitants/km².",
    [SupplementalQuestion("extra_seconde_renforcement_annuel_22_q1", "La densité de population se calcule par…", ["Superficie ÷ température", "Population ÷ superficie", "Population × âge"], 1, "La densité est le rapport population/superficie."),
      SupplementalQuestion("extra_seconde_renforcement_annuel_22_q2", "1000 habitants sur 10 km² donnent…", ["10 habitants/km²", "1000 km²", "100 habitants/km²"], 2, "1000 ÷ 10 = 100."),
      SupplementalQuestion("extra_seconde_renforcement_annuel_22_q3", "Une forte densité signifie…", ["Beaucoup d’habitants par unité de surface", "Aucun habitant", "Une grande altitude"], 0, "La densité mesure le nombre d’habitants par surface.")]),
  SupplementalLesson("seconde_renforcement_annuel_23", SchoolLevel.seconde, "Physique", "Décrire un mouvement et sa vitesse",
    "La vitesse moyenne est la distance parcourue divisée par la durée. Les unités doivent être cohérentes.",
    "150 km parcourus en 3 h : v = 50 km/h.",
    [SupplementalQuestion("extra_seconde_renforcement_annuel_23_q1", "La vitesse moyenne est…", ["Durée ÷ masse", "Distance ÷ durée", "Distance + temps"], 1, "v = d/t."),
      SupplementalQuestion("extra_seconde_renforcement_annuel_23_q2", "120 km en 2 h donnent…", ["240 km/h", "30 km/h", "60 km/h"], 2, "120 ÷ 2 = 60."),
      SupplementalQuestion("extra_seconde_renforcement_annuel_23_q3", "Si la distance reste la même et la durée diminue, la vitesse moyenne…", ["Augmente", "Diminue toujours", "Reste nécessairement nulle"], 0, "Parcourir la même distance en moins de temps augmente la vitesse moyenne.")]),
  SupplementalLesson("premiere_renforcement_annuel_24", SchoolLevel.premiere, "Français", "Construire un paragraphe argumentatif",
    "Un paragraphe argumentatif présente une idée, la justifie par un argument et l’illustre par un exemple. Les connecteurs organisent le raisonnement.",
    "Thèse : lire est utile. Argument : cela enrichit le vocabulaire. Exemple : un roman fait découvrir de nouveaux mots.",
    [SupplementalQuestion("extra_premiere_renforcement_annuel_24_q1", "Un argument sert à…", ["Remplacer le sujet", "Justifier une idée", "Éviter toute explication"], 1, "Un argument soutient une thèse."),
      SupplementalQuestion("extra_premiere_renforcement_annuel_24_q2", "Un exemple permet de…", ["Supprimer la conclusion", "Changer de langue", "Illustrer l’argument"], 2, "L’exemple rend l’argument concret."),
      SupplementalQuestion("extra_premiere_renforcement_annuel_24_q3", "Quel connecteur exprime une conséquence ?", ["Donc", "Cependant", "D’abord"], 0, "Donc introduit une conséquence.")]),
  SupplementalLesson("premiere_renforcement_annuel_25", SchoolLevel.premiere, "SVT", "Le système nerveux et le message nerveux",
    "Les organes sensoriels détectent les stimuli. Les nerfs transmettent des messages nerveux et le cerveau participe à leur traitement.",
    "Retirer la main d’un objet brûlant est une réponse rapide contrôlée par un circuit nerveux.",
    [SupplementalQuestion("extra_premiere_renforcement_annuel_25_q1", "Quel organe traite de nombreuses informations sensorielles ?", ["Le pancréas", "Le cerveau", "L’estomac"], 1, "Le cerveau reçoit et traite des informations."),
      SupplementalQuestion("extra_premiere_renforcement_annuel_25_q2", "Les nerfs transmettent…", ["Du sang uniquement", "Des aliments", "Des messages nerveux"], 2, "Les nerfs transmettent des signaux nerveux."),
      SupplementalQuestion("extra_premiere_renforcement_annuel_25_q3", "Un stimulus est…", ["Un changement détecté par un récepteur", "Une réponse écrite", "Un os"], 0, "Un stimulus peut déclencher une réponse nerveuse.")]),
  SupplementalLesson("terminale_renforcement_annuel_26", SchoolLevel.terminale, "Mathématiques", "Calculer une probabilité conditionnelle",
    "La probabilité de A sachant B est P(A∩B)/P(B), si P(B)>0. Elle se note P(A|B).",
    "Si P(A∩B)=0,2 et P(B)=0,5, alors P(A|B)=0,4.",
    [SupplementalQuestion("extra_terminale_renforcement_annuel_26_q1", "P(A|B) se calcule par…", ["P(A)+P(B)", "P(A∩B) ÷ P(B)", "P(B) ÷ P(A∩B)"], 1, "La formule conditionnelle divise l’intersection par P(B)."),
      SupplementalQuestion("extra_terminale_renforcement_annuel_26_q2", "0,2 ÷ 0,5 = …", ["0,7", "2,5", "0,4"], 2, "0,2/0,5 = 0,4."),
      SupplementalQuestion("extra_terminale_renforcement_annuel_26_q3", "La formule exige…", ["P(B)>0", "P(A)=0", "P(B)=1 toujours"], 0, "On ne divise pas par zéro.")]),
  SupplementalLesson("terminale_renforcement_annuel_27", SchoolLevel.terminale, "Philosophie", "Construire une introduction de dissertation",
    "Une introduction présente le sujet, clarifie les termes, fait apparaître une difficulté et formule une problématique avant d’annoncer le plan.",
    "Pour un sujet sur la liberté, définis liberté et contrainte puis pose le problème de leurs rapports.",
    [SupplementalQuestion("extra_terminale_renforcement_annuel_27_q1", "Une problématique sert à…", ["Donner uniquement un exemple", "Formuler le problème à examiner", "Répéter le sujet sans réflexion"], 1, "La problématique transforme le sujet en question philosophique."),
      SupplementalQuestion("extra_terminale_renforcement_annuel_27_q2", "Avant d’annoncer le plan, il faut…", ["Écrire la conclusion", "Donner une réponse sans argument", "Présenter et analyser le problème"], 2, "L’introduction conduit progressivement à la problématique et au plan."),
      SupplementalQuestion("extra_terminale_renforcement_annuel_27_q3", "Une dissertation philosophique doit…", ["Argumenter et examiner des idées", "Accumuler des opinions sans justification", "Éviter les concepts"], 0, "La philosophie demande un raisonnement argumenté.")]),
  SupplementalLesson("cp1_renforcement_annuel_plus_1", SchoolLevel.cp1, "Français", "Tracer et reconnaître les lettres",
    "Observe la forme des lettres. Trace chaque lettre en respectant le sens du geste, puis associe-la au son correspondant.",
    "A, a : la lettre A peut s’écrire en majuscule ou en minuscule.",
    [SupplementalQuestion("extra_cp1_renforcement_annuel_plus_1_q1", "Quelle est la minuscule de A ?", ["o", "a", "e"], 1, "La minuscule de A est a."),
      SupplementalQuestion("extra_cp1_renforcement_annuel_plus_1_q2", "Pourquoi trace-t-on les lettres dans le bon sens ?", ["Pour dessiner plus vite sans regarder", "Pour changer leur son", "Pour écrire clairement"], 2, "Le bon geste aide à former des lettres lisibles."), SupplementalQuestion("extra_cp1_renforcement_annuel_plus_1_q3", "Quelle lettre est écrite en majuscule ?", ["A", "a minuscule", "o"], 0, "La lettre A est la majuscule ; a est la minuscule.")]),
  SupplementalLesson("cp1_renforcement_annuel_plus_2", SchoolLevel.cp1, "Mathématiques", "Comparer des nombres jusqu’à 10",
    "Compare deux nombres en comptant. Le nombre qui vient plus tard dans la suite est le plus grand.",
    "7 est plus grand que 4 ; 2 est plus petit que 6.",
    [SupplementalQuestion("extra_cp1_renforcement_annuel_plus_2_q1", "Quel nombre est le plus grand ?", ["5", "3", "8"], 2, "8 est supérieur à 5 et à 3."),
      SupplementalQuestion("extra_cp1_renforcement_annuel_plus_2_q2", "Complète : 4 est … que 9.", ["plus grand", "plus petit", "égal"], 1, "4 est inférieur à 9."), SupplementalQuestion("extra_cp1_renforcement_annuel_plus_2_q3", "Quel signe montre que 7 est plus grand que 4 ? ", [">", "<", "="], 0, "Le signe > signifie « est supérieur à ».")]),
  SupplementalLesson("cp2_renforcement_annuel_plus_3", SchoolLevel.cp2, "Français", "Construire une phrase simple",
    "Une phrase exprime une idée. Elle commence par une majuscule et se termine par un point, un point d’interrogation ou un point d’exclamation.",
    "Ama joue. Le garçon lit.",
    [SupplementalQuestion("extra_cp2_renforcement_annuel_plus_3_q1", "Quelle phrase est correctement écrite ?", ["ama joue", "Ama joue.", "Ama joue!"], 1, "Une phrase commence par une majuscule et se termine par un signe."),
      SupplementalQuestion("extra_cp2_renforcement_annuel_plus_3_q2", "Quel signe termine une question ?", ["!", ";", "?"], 2, "Le point d’interrogation marque une question."), SupplementalQuestion("extra_cp2_renforcement_annuel_plus_3_q3", "Comment termine-t-on une phrase ?", ["Par un signe de ponctuation adapté", "Toujours par une virgule", "Sans aucun signe"], 0, "Une phrase se termine par un signe adapté à son intention.")]),
  SupplementalLesson("cp2_renforcement_annuel_plus_4", SchoolLevel.cp2, "Mathématiques", "Comprendre dizaines et unités",
    "Dix unités forment une dizaine. Dans 34, il y a 3 dizaines et 4 unités.",
    "34 = 30 + 4.",
    [SupplementalQuestion("extra_cp2_renforcement_annuel_plus_4_q1", "Dans 26, combien y a-t-il de dizaines ?", ["6", "26", "2"], 2, "26 contient deux dizaines."),
      SupplementalQuestion("extra_cp2_renforcement_annuel_plus_4_q2", "40 + 7 = …", ["407", "47", "74"], 1, "Quatre dizaines et sept unités font 47."), SupplementalQuestion("extra_cp2_renforcement_annuel_plus_4_q3", "3 dizaines et 5 unités font…", ["35", "305", "53"], 0, "3 dizaines font 30 ; 30 + 5 = 35.")]),
  SupplementalLesson("ce1_renforcement_annuel_plus_5", SchoolLevel.ce1, "Français", "Enrichir le vocabulaire par les synonymes",
    "Des synonymes sont des mots de sens proche. Ils permettent d’éviter les répétitions et de mieux exprimer une idée.",
    "Content et heureux sont des mots de sens proche.",
    [SupplementalQuestion("extra_ce1_renforcement_annuel_plus_5_q1", "Quel mot est proche de « content » ?", ["Fâché", "Heureux", "Lourd"], 1, "Heureux est un synonyme de content."),
      SupplementalQuestion("extra_ce1_renforcement_annuel_plus_5_q2", "Le contraire de « rapide » est…", ["Vif", "Agile", "Lent"], 2, "Lent est l’antonyme de rapide."), SupplementalQuestion("extra_ce1_renforcement_annuel_plus_5_q3", "Le contraire de « grand » est…", ["Petit", "Long", "Haut"], 0, "Petit est un antonyme de grand.")]),
  SupplementalLesson("ce1_renforcement_annuel_plus_6", SchoolLevel.ce1, "Sciences", "Les saisons et les changements du milieu",
    "Au cours de l’année, les conditions météorologiques changent. Observe les pluies, la chaleur, les plantes et les activités selon les saisons locales.",
    "Au Togo, on distingue généralement des saisons pluvieuses et des saisons sèches, dont la répartition varie selon les régions.",
    [SupplementalQuestion("extra_ce1_renforcement_annuel_plus_6_q1", "Que peut-on observer pour reconnaître une saison ?", ["La couleur des cahiers", "Le nombre de fenêtres", "Les pluies et les conditions du temps"], 2, "Les conditions météorologiques caractérisent les saisons."),
      SupplementalQuestion("extra_ce1_renforcement_annuel_plus_6_q2", "Les saisons peuvent influencer…", ["La forme des lettres", "Les cultures et les activités", "La taille des règles"], 1, "Les activités agricoles dépendent souvent des saisons."), SupplementalQuestion("extra_ce1_renforcement_annuel_plus_6_q3", "Au début de la saison des pluies, les agriculteurs peuvent…", ["Préparer les cultures", "Ranger toutes les semences pour toujours", "Ignorer l’état du sol"], 0, "Les pluies influencent le calendrier des cultures.")]),
  SupplementalLesson("ce2_renforcement_annuel_plus_7", SchoolLevel.ce2, "Sciences", "L’eau : états et changements",
    "L’eau peut être liquide, solide (glace) ou gazeuse (vapeur). La chaleur peut provoquer l’évaporation et le refroidissement peut provoquer la solidification.",
    "L’eau liquide chauffée peut s’évaporer ; l’eau refroidie suffisamment peut geler.",
    [SupplementalQuestion("extra_ce2_renforcement_annuel_plus_7_q1", "La glace est de l’eau à l’état…", ["Liquide", "Solide", "Gazeux"], 1, "La glace est l’état solide de l’eau."),
      SupplementalQuestion("extra_ce2_renforcement_annuel_plus_7_q2", "Le passage de l’eau liquide en vapeur s’appelle…", ["Solidification", "Condensation", "Évaporation"], 2, "L’évaporation transforme un liquide en vapeur."), SupplementalQuestion("extra_ce2_renforcement_annuel_plus_7_q3", "Le passage de l’eau liquide à la glace s’appelle…", ["Solidification", "Évaporation", "Fusion"], 0, "Le refroidissement peut transformer l’eau liquide en solide.")]),
  SupplementalLesson("ce2_renforcement_annuel_plus_8", SchoolLevel.ce2, "Éducation civique", "Respecter les règles de sécurité routière",
    "À pied, marche sur le côté sûr de la route, regarde avant de traverser et utilise un passage adapté lorsqu’il existe. Suis les indications des adultes et des signaux.",
    "Avant de traverser, arrête-toi, regarde des deux côtés et traverse sans courir.",
    [SupplementalQuestion("extra_ce2_renforcement_annuel_plus_8_q1", "Avant de traverser, il faut…", ["Courir sans regarder", "Jouer sur la chaussée", "Regarder des deux côtés"], 2, "Il faut vérifier que la traversée est sûre."),
      SupplementalQuestion("extra_ce2_renforcement_annuel_plus_8_q2", "Le feu rouge pour les véhicules signifie…", ["Accélérer", "S’arrêter", "Klaxonner et passer"], 1, "Le rouge indique l’arrêt."), SupplementalQuestion("extra_ce2_renforcement_annuel_plus_8_q3", "Quand il existe un trottoir, le piéton doit…", ["Marcher sur le trottoir", "Marcher au milieu de la chaussée", "Courir derrière les voitures"], 0, "Le trottoir est réservé aux déplacements des piétons.")]),
  SupplementalLesson("cm1_renforcement_annuel_plus_9", SchoolLevel.cm1, "Français", "Rédiger une lettre personnelle",
    "Une lettre personnelle comporte souvent une formule d’appel, un message organisé, une formule de fin et une signature. Adapte le langage au destinataire.",
    "Cher ami, … À bientôt. Ton camarade, …",
    [SupplementalQuestion("extra_cm1_renforcement_annuel_plus_9_q1", "À quoi sert la signature ?", ["À indiquer le prix du papier", "À identifier l’auteur de la lettre", "À remplacer le message"], 1, "La signature permet de savoir qui écrit."),
      SupplementalQuestion("extra_cm1_renforcement_annuel_plus_9_q2", "Une formule d’appel peut être…", ["Au revoir définitif", "Le titre du tableau", "Cher ami,"], 2, "« Cher ami » est une formule d’appel."), SupplementalQuestion("extra_cm1_renforcement_annuel_plus_9_q3", "Dans une lettre, le message doit être…", ["Clair et organisé", "Sans rapport avec le destinataire", "Écrit uniquement en chiffres"], 0, "Le message doit être compréhensible et adapté au destinataire.")]),
  SupplementalLesson("cm1_renforcement_annuel_plus_10", SchoolLevel.cm1, "Mathématiques", "Lire et placer une fraction",
    "Une fraction représente une ou plusieurs parts égales. Le dénominateur indique le nombre de parts égales ; le numérateur indique combien sont prises.",
    "3/4 signifie trois parts prises sur quatre parts égales.",
    [SupplementalQuestion("extra_cm1_renforcement_annuel_plus_10_q1", "Dans 2/5, le dénominateur est…", ["2", "7", "5"], 2, "Le dénominateur est le nombre du bas : 5."),
      SupplementalQuestion("extra_cm1_renforcement_annuel_plus_10_q2", "1/3 représente…", ["Trois parts sur une", "Une part sur trois parts égales", "Une unité et trois"], 1, "Le numérateur 1 indique une part ; le dénominateur 3 indique trois parts égales."), SupplementalQuestion("extra_cm1_renforcement_annuel_plus_10_q3", "Dans la fraction 3/8, le numérateur est…", ["3", "8", "11"], 0, "Le numérateur est le nombre placé au-dessus de la barre.")]),
  SupplementalLesson("cm2_renforcement_annuel_plus_11", SchoolLevel.cm2, "Histoire", "Le Togo avant et pendant la colonisation",
    "L’histoire du territoire togolais comprend des sociétés et royaumes précoloniaux, puis des périodes de domination coloniale. Étudie les événements dans leur contexte et leurs conséquences.",
    "Les dates, les acteurs et les sources permettent de construire un récit historique vérifiable.",
    [SupplementalQuestion("extra_cm2_renforcement_annuel_plus_11_q1", "Pour étudier un événement historique, on utilise…", ["Seulement des rumeurs", "Des sources et des dates", "Des calculs sans contexte"], 1, "Les sources aident à vérifier les faits historiques."),
      SupplementalQuestion("extra_cm2_renforcement_annuel_plus_11_q2", "Une chronologie sert à…", ["Mesurer la température", "Calculer une aire", "Placer les événements dans l’ordre du temps"], 2, "Une chronologie organise les événements par date."), SupplementalQuestion("extra_cm2_renforcement_annuel_plus_11_q3", "Pour vérifier une information historique, il faut…", ["Comparer les sources", "Se fier à une seule rumeur", "Changer les dates"], 0, "Comparer les sources aide à établir la fiabilité d’un fait.")]),
  SupplementalLesson("cm2_renforcement_annuel_plus_12", SchoolLevel.cm2, "Mathématiques", "Calculer l’aire d’un rectangle",
    "L’aire mesure la surface d’une figure. Pour un rectangle, aire = longueur × largeur. Utilise des unités carrées.",
    "Un rectangle de 8 cm sur 3 cm a une aire de 24 cm².",
    [SupplementalQuestion("extra_cm2_renforcement_annuel_plus_12_q1", "Aire d’un rectangle 5 cm × 4 cm = …", ["9 cm²", "20 cm", "20 cm²"], 2, "5 × 4 = 20 ; l’unité est cm²."),
      SupplementalQuestion("extra_cm2_renforcement_annuel_plus_12_q2", "L’aire se mesure en…", ["Unités de temps", "Unités carrées", "Litres"], 1, "Une aire est une surface et s’exprime en unités carrées."), SupplementalQuestion("extra_cm2_renforcement_annuel_plus_12_q3", "L’aire d’un carré de 6 cm de côté est…", ["36 cm²", "12 cm²", "36 cm"], 0, "6 × 6 = 36 ; l’aire s’exprime en cm².")]),
  SupplementalLesson("sixieme_renforcement_annuel_plus_13", SchoolLevel.sixieme, "Français", "Identifier le nom, le déterminant et l’adjectif",
    "Le déterminant accompagne le nom. L’adjectif donne une précision sur le nom. Repère le groupe nominal dans la phrase.",
    "Dans « une grande maison », une est déterminant, maison est nom et grande est adjectif.",
    [SupplementalQuestion("extra_sixieme_renforcement_annuel_plus_13_q1", "Dans « un petit chat », le nom est…", ["petit", "chat", "un"], 1, "Chat désigne l’animal : c’est le nom."),
      SupplementalQuestion("extra_sixieme_renforcement_annuel_plus_13_q2", "Dans « une grande maison », « grande » est…", ["Un déterminant", "Un verbe", "Un adjectif"], 2, "Grande précise le nom maison."), SupplementalQuestion("extra_sixieme_renforcement_annuel_plus_13_q3", "Dans « les élèves », le déterminant est…", ["les", "élèves", "un"], 0, "Les accompagne le nom élèves.")]),
  SupplementalLesson("sixieme_renforcement_annuel_plus_14", SchoolLevel.sixieme, "SVT", "Les organes et les fonctions du corps",
    "Les organes travaillent ensemble pour assurer les fonctions vitales. Le cœur fait circuler le sang ; les poumons participent aux échanges gazeux.",
    "Le cœur, les vaisseaux et le sang forment l’appareil circulatoire.",
    [SupplementalQuestion("extra_sixieme_renforcement_annuel_plus_14_q1", "Quel organe propulse le sang ?", ["Le poumon", "L’estomac", "Le cœur"], 2, "Le cœur pompe le sang."),
      SupplementalQuestion("extra_sixieme_renforcement_annuel_plus_14_q2", "Les poumons servent principalement à…", ["Digérer les aliments", "Échanger les gaz respiratoires", "Filtrer les sons"], 1, "Les poumons permettent les échanges d’oxygène et de dioxyde de carbone."), SupplementalQuestion("extra_sixieme_renforcement_annuel_plus_14_q3", "Les vaisseaux sanguins servent à…", ["Transporter le sang", "Produire les aliments", "Faire entendre les sons"], 0, "Les vaisseaux transportent le sang dans le corps.")]),
  SupplementalLesson("cinquieme_renforcement_annuel_plus_15", SchoolLevel.cinquieme, "Éducation civique", "Les symboles et les valeurs de la République",
    "Les symboles nationaux représentent l’État et l’unité du peuple. Les valeurs civiques incluent le respect, la solidarité et la participation responsable.",
    "Connaître l’hymne, le drapeau et les institutions aide à comprendre la vie citoyenne.",
    [SupplementalQuestion("extra_cinquieme_renforcement_annuel_plus_15_q1", "Un drapeau national est…", ["Un instrument de mesure", "Un symbole du pays", "Un document médical"], 1, "Le drapeau représente la nation."),
      SupplementalQuestion("extra_cinquieme_renforcement_annuel_plus_15_q2", "La solidarité signifie…", ["Ignorer les personnes en difficulté", "Refuser toute coopération", "S’entraider et agir ensemble"], 2, "La solidarité est l’entraide."), SupplementalQuestion("extra_cinquieme_renforcement_annuel_plus_15_q3", "Quel élément est un symbole national ?", ["L’hymne national", "Une facture privée", "Une règle graduée"], 0, "L’hymne national représente la nation.")]),
  SupplementalLesson("cinquieme_renforcement_annuel_plus_16", SchoolLevel.cinquieme, "Physique-Chimie", "Les circuits électriques simples",
    "Un circuit électrique fermé permet au courant de circuler. Une pile, des fils et une lampe peuvent former un circuit simple.",
    "Si le circuit est ouvert, la lampe ne s’allume pas.",
    [SupplementalQuestion("extra_cinquieme_renforcement_annuel_plus_16_q1", "Pour que la lampe s’allume, le circuit doit être…", ["Ouvert", "Sans source d’énergie", "Fermé"], 2, "Le circuit doit être fermé pour que le courant circule."),
      SupplementalQuestion("extra_cinquieme_renforcement_annuel_plus_16_q2", "Quel élément fournit l’énergie électrique dans un circuit simple ?", ["Le fil seul", "La pile", "Le support de lampe seul"], 1, "La pile fournit l’énergie électrique."), SupplementalQuestion("extra_cinquieme_renforcement_annuel_plus_16_q3", "Si l’interrupteur ouvre le circuit, la lampe…", ["S’éteint", "Brille davantage", "Fonctionne sans circuit"], 0, "Un circuit ouvert ne laisse pas circuler le courant.")]),
  SupplementalLesson("quatrieme_renforcement_annuel_plus_17", SchoolLevel.quatrieme, "Géographie", "Les ressources et les activités économiques du Togo",
    "Les activités économiques comprennent l’agriculture, l’élevage, la pêche, l’industrie, le commerce et les services. Elles dépendent des ressources, des infrastructures et des besoins.",
    "Les cultures et les activités varient selon les conditions naturelles et les régions.",
    [SupplementalQuestion("extra_quatrieme_renforcement_annuel_plus_17_q1", "Une activité du secteur primaire est…", ["La banque", "L’agriculture", "La vente en magasin"], 1, "L’agriculture utilise directement les ressources naturelles."),
      SupplementalQuestion("extra_quatrieme_renforcement_annuel_plus_17_q2", "Les services appartiennent principalement au secteur…", ["Primaire", "Uniquement agricole", "Tertiaire"], 2, "Le commerce et les services relèvent du secteur tertiaire."), SupplementalQuestion("extra_quatrieme_renforcement_annuel_plus_17_q3", "La pêche appartient au secteur…", ["Primaire", "Secondaire", "Tertiaire"], 0, "La pêche exploite directement une ressource naturelle.")]),
  SupplementalLesson("quatrieme_renforcement_annuel_plus_18", SchoolLevel.quatrieme, "SVT", "La reproduction des plantes à fleurs",
    "La fleur contient des organes reproducteurs. Après la pollinisation et la fécondation, certaines fleurs donnent des fruits contenant des graines.",
    "Le pollen peut être transporté par le vent ou des animaux pollinisateurs.",
    [SupplementalQuestion("extra_quatrieme_renforcement_annuel_plus_18_q1", "Le pollen est produit par…", ["Les racines", "Les feuilles uniquement", "Les étamines"], 2, "Les étamines sont les organes mâles de la fleur."),
      SupplementalQuestion("extra_quatrieme_renforcement_annuel_plus_18_q2", "Après la fécondation, l’ovaire peut devenir…", ["Une racine", "Un fruit", "Une tige"], 1, "L’ovaire de la fleur se développe souvent en fruit."), SupplementalQuestion("extra_quatrieme_renforcement_annuel_plus_18_q3", "La pollinisation correspond au transport…", ["Du pollen vers le stigmate", "De l’eau vers les racines seulement", "Des graines vers les feuilles"], 0, "La pollinisation permet le dépôt du pollen sur le stigmate.")]),
  SupplementalLesson("troisieme_renforcement_annuel_plus_19", SchoolLevel.troisieme, "Mathématiques", "Calculer une distance dans un triangle rectangle",
    "Dans un triangle rectangle, le théorème de Pythagore relie les carrés des longueurs : hypoténuse² = côté1² + côté2².",
    "Pour les côtés 3 et 4, l’hypoténuse vaut 5 car 3² + 4² = 25.",
    [SupplementalQuestion("extra_troisieme_renforcement_annuel_plus_19_q1", "Dans un triangle rectangle de côtés 6 et 8, l’hypoténuse vaut…", ["14", "10", "8"], 1, "6² + 8² = 36 + 64 = 100, donc la racine vaut 10."),
      SupplementalQuestion("extra_troisieme_renforcement_annuel_plus_19_q2", "L’hypoténuse est…", ["Toujours le plus court côté", "Un angle", "Le côté opposé à l’angle droit"], 2, "L’hypoténuse est le côté le plus long, opposé à l’angle droit."), SupplementalQuestion("extra_troisieme_renforcement_annuel_plus_19_q3", "Dans un triangle rectangle de côtés 5 et 12, l’hypoténuse vaut…", ["13", "17", "12"], 0, "5² + 12² = 25 + 144 = 169 ; √169 = 13.")]),
  SupplementalLesson("troisieme_renforcement_annuel_plus_20", SchoolLevel.troisieme, "Français", "Distinguer thèse, argument et exemple",
    "La thèse est l’idée défendue. L’argument justifie cette idée. L’exemple illustre l’argument de façon concrète.",
    "Thèse : l’école est importante. Argument : elle développe les connaissances. Exemple : on y apprend à lire et à calculer.",
    [SupplementalQuestion("extra_troisieme_renforcement_annuel_plus_20_q1", "La thèse est…", ["Un exemple chiffré seulement", "La signature", "L’idée que l’on défend"], 2, "La thèse exprime la position défendue."),
      SupplementalQuestion("extra_troisieme_renforcement_annuel_plus_20_q2", "Un exemple sert à…", ["Remplacer toute la réflexion", "Illustrer un argument", "Introduire une date obligatoire"], 1, "L’exemple rend l’argument concret."), SupplementalQuestion("extra_troisieme_renforcement_annuel_plus_20_q3", "Un argument sert à…", ["Soutenir la thèse", "Remplacer le sujet", "Faire une signature"], 0, "Un argument justifie l’idée défendue.")]),
  SupplementalLesson("seconde_renforcement_annuel_plus_21", SchoolLevel.seconde, "Physique-Chimie", "Les atomes, molécules et ions",
    "Un atome est une entité électriquement neutre. Une molécule est un assemblage d’atomes. Un ion porte une charge électrique.",
    "Na⁺ est un ion positif ; H₂O est une molécule.",
    [SupplementalQuestion("extra_seconde_renforcement_annuel_plus_21_q1", "Une molécule est…", ["Un seul proton", "Un assemblage d’atomes", "Toujours un métal"], 1, "Une molécule contient plusieurs atomes liés."),
      SupplementalQuestion("extra_seconde_renforcement_annuel_plus_21_q2", "Un ion porte…", ["Toujours aucune charge", "Uniquement une masse nulle", "Une charge électrique"], 2, "Un ion est chargé positivement ou négativement."), SupplementalQuestion("extra_seconde_renforcement_annuel_plus_21_q3", "Un atome non ionisé est…", ["Électriquement neutre", "Toujours positif", "Toujours négatif"], 0, "Un atome possède autant de protons que d’électrons.")]),
  SupplementalLesson("seconde_renforcement_annuel_plus_22", SchoolLevel.seconde, "Français", "Analyser un récit : narrateur et point de vue",
    "Le narrateur raconte l’histoire. Le point de vue indique à travers quelle perception les événements sont présentés : interne, externe ou omniscient.",
    "« Je voyais la pluie » est un récit à la première personne.",
    [SupplementalQuestion("extra_seconde_renforcement_annuel_plus_22_q1", "Le narrateur est celui qui…", ["Lit toujours à haute voix", "Écrit la couverture seulement", "Raconte l’histoire"], 2, "Le narrateur raconte les événements."),
      SupplementalQuestion("extra_seconde_renforcement_annuel_plus_22_q2", "Le point de vue interne donne accès…", ["À toutes les informations sans limite", "Aux pensées ou perceptions d’un personnage", "À aucune information"], 1, "Le point de vue interne suit la perception d’un personnage."), SupplementalQuestion("extra_seconde_renforcement_annuel_plus_22_q3", "Un narrateur à la première personne utilise souvent…", ["Je", "Il uniquement", "Vous uniquement"], 0, "La première personne se reconnaît notamment au pronom je.")]),
  SupplementalLesson("premiere_renforcement_annuel_plus_23", SchoolLevel.premiere, "Mathématiques", "Étudier une fonction affine",
    "Une fonction affine s’écrit f(x)=ax+b. Le coefficient a donne la pente et b l’ordonnée à l’origine.",
    "Pour f(x)=2x+3, f(4)=11.",
    [SupplementalQuestion("extra_premiere_renforcement_annuel_plus_23_q1", "Si f(x)=3x−2, f(2)=…", ["6", "4", "1"], 1, "3×2−2=4."),
      SupplementalQuestion("extra_premiere_renforcement_annuel_plus_23_q2", "Dans f(x)=ax+b, b est…", ["La pente", "La variable", "L’ordonnée à l’origine"], 2, "b est la valeur de f(0)."), SupplementalQuestion("extra_premiere_renforcement_annuel_plus_23_q3", "Si f(x)=2x+5, alors f(3)=…", ["11", "10", "8"], 0, "2 × 3 + 5 = 11.")]),
  SupplementalLesson("premiere_renforcement_annuel_plus_24", SchoolLevel.premiere, "Histoire", "La traite et les échanges atlantiques : repères et conséquences",
    "L’histoire des échanges atlantiques comprend des systèmes commerciaux, la traite transatlantique et l’esclavage. Étudie les acteurs, les violences, les résistances et les conséquences historiques.",
    "L’analyse historique doit replacer les faits dans leur contexte et écouter les traces de différentes populations.",
    [SupplementalQuestion("extra_premiere_renforcement_annuel_plus_24_q1", "La traite transatlantique a impliqué…", ["Un échange uniquement volontaire et égal", "Une migration touristique", "La déportation forcée d’Africains réduits en esclavage"], 2, "La traite a été un système violent de déportation et d’exploitation."),
      SupplementalQuestion("extra_premiere_renforcement_annuel_plus_24_q2", "Une étude historique rigoureuse examine…", ["Seulement une opinion personnelle", "Les causes, les acteurs et les conséquences", "Uniquement les dates sans explication"], 1, "L’histoire analyse les faits et leurs contextes."), SupplementalQuestion("extra_premiere_renforcement_annuel_plus_24_q3", "Une résistance historique peut être…", ["Une action contre une domination ou une injustice", "Une absence totale d’action", "Un événement sans acteurs"], 0, "Les résistances sont des actions menées contre une domination ou une injustice.")]),
  SupplementalLesson("terminale_renforcement_annuel_plus_25", SchoolLevel.terminale, "Physique-Chimie", "Les ondes : fréquence et période",
    "La période T est la durée d’un cycle. La fréquence f est le nombre de cycles par seconde : f=1/T et s’exprime en hertz.",
    "Une période de 0,02 s correspond à une fréquence de 50 Hz.",
    [SupplementalQuestion("extra_terminale_renforcement_annuel_plus_25_q1", "Si T=0,01 s, la fréquence vaut…", ["10 Hz", "100 Hz", "0,01 Hz"], 1, "f=1/0,01=100 Hz."),
      SupplementalQuestion("extra_terminale_renforcement_annuel_plus_25_q2", "L’unité de fréquence est…", ["Joule", "Newton", "Hertz"], 2, "La fréquence se mesure en hertz (Hz)."), SupplementalQuestion("extra_terminale_renforcement_annuel_plus_25_q3", "Si T=0,02 s, la fréquence vaut…", ["50 Hz", "2 Hz", "0,02 Hz"], 0, "f = 1/T = 1/0,02 = 50 Hz.")]),
  SupplementalLesson("terminale_renforcement_annuel_plus_26", SchoolLevel.terminale, "Français", "Réussir une synthèse de documents",
    "Une synthèse confronte les idées essentielles de plusieurs documents, les organise selon des axes communs et reformule sans copier.",
    "Prépare un tableau : idée, document source, convergence ou différence.",
    [SupplementalQuestion("extra_terminale_renforcement_annuel_plus_26_q1", "Une synthèse doit…", ["Copier chaque document intégralement", "Ajouter des opinions sans lien", "Croiser les idées des documents"], 2, "La synthèse organise et confronte les informations."),
      SupplementalQuestion("extra_terminale_renforcement_annuel_plus_26_q2", "Un tableau de confrontation aide à…", ["Remplacer la lecture", "Repérer convergences et différences", "Éviter de citer les sources"], 1, "Le tableau facilite la comparaison des documents."), SupplementalQuestion("extra_terminale_renforcement_annuel_plus_26_q3", "Une bonne synthèse doit…", ["Reformuler et confronter les idées en mentionnant les documents", "Copier un seul texte", "Omettre les sources"], 0, "Une synthèse reformule et met en relation les documents.")]),
  SupplementalLesson("cp1_hygiene_lavage_mains", SchoolLevel.cp1, "Éveil / Santé", "Se laver les mains pour rester en bonne santé",
    "Le lavage des mains avec de l’eau et du savon aide à enlever les microbes. Il faut se laver les mains avant de manger et après les toilettes.",
    "Mouille les mains, mets du savon, frotte les paumes et les doigts, rince puis sèche avec un linge propre.",
    [SupplementalQuestion("annual_cp1_cp1_hygiene_lavage_mains_1", "Avec quoi se lave-t-on les mains ?", ["Avec de l’eau et du savon","Avec du sable seulement","Avec de la peinture"], 0, "L’eau et le savon nettoient les mains."), SupplementalQuestion("annual_cp1_cp1_hygiene_lavage_mains_2", "Quand faut-il se laver les mains ?", ["Jamais avant le repas","Avant de manger","Seulement le dimanche"], 1, "Il faut se laver les mains avant de manger."), SupplementalQuestion("annual_cp1_cp1_hygiene_lavage_mains_3", "Après le lavage, il faut…", ["S’essuyer sur le sol","Toucher la poussière","Sécher les mains proprement"], 2, "Des mains propres doivent être séchées avec un linge propre.")]),
  SupplementalLesson("cp2_securite_route_annual", SchoolLevel.cp2, "Éducation sociale", "Se déplacer en sécurité sur la route",
    "Avant de traverser, arrête-toi, regarde à gauche puis à droite et écoute. Traverse au passage piéton lorsqu’il est possible de le faire sans danger.",
    "Arrêt → regarder → écouter → traverser sans courir avec un adulte si nécessaire.",
    [SupplementalQuestion("annual_cp2_cp2_securite_route_annual_1", "Où traverser de préférence ?", ["Au milieu d’un virage","Sur un passage piéton","Entre deux véhicules arrêtés"], 1, "Le passage piéton est l’endroit prévu pour traverser."), SupplementalQuestion("annual_cp2_cp2_securite_route_annual_2", "Avant de traverser, que faut-il faire ?", ["Courir sans regarder","Jouer sur la chaussée","S’arrêter et regarder des deux côtés"], 2, "Il faut s’arrêter et vérifier la circulation."), SupplementalQuestion("annual_cp2_cp2_securite_route_annual_3", "Sur la route, un enfant doit…", ["Suivre les règles et demander l’aide d’un adulte","Se cacher derrière un camion","Courir en regardant son téléphone"], 0, "Les règles et l’accompagnement réduisent les dangers.")]),
  SupplementalLesson("ce1_economiser_eau_annual", SchoolLevel.ce1, "Sciences / Environnement", "Économiser l’eau au quotidien",
    "L’eau est nécessaire aux êtres vivants. On évite de la gaspiller en fermant le robinet quand on ne l’utilise pas et en réparant les fuites avec l’aide d’un adulte.",
    "Pendant le brossage des dents, ferme le robinet puis rince avec une petite quantité d’eau.",
    [SupplementalQuestion("annual_ce1_ce1_economiser_eau_annual_1", "Pourquoi l’eau est-elle importante ?", ["Elle ne sert à rien","Elle est nécessaire aux êtres vivants","Elle remplace tous les aliments"], 1, "Les humains, les animaux et les plantes ont besoin d’eau."), SupplementalQuestion("annual_ce1_ce1_economiser_eau_annual_2", "Quel geste économise l’eau ?", ["Laisser couler le robinet","Jouer avec l’eau potable","Fermer le robinet pendant le brossage"], 2, "Fermer le robinet évite le gaspillage."), SupplementalQuestion("annual_ce1_ce1_economiser_eau_annual_3", "Une fuite doit être…", ["Signalée à un adulte pour être réparée","Ignorée","Agrandie"], 0, "Une fuite entraîne une perte d’eau.")]),
  SupplementalLesson("ce2_lire_tableau_annual", SchoolLevel.ce2, "Mathématiques", "Lire un tableau de données simple",
    "Un tableau organise des informations en lignes et en colonnes. Lis d’abord le titre, puis les noms des lignes et des colonnes avant de comparer les nombres.",
    "Ventes de fruits : mangues 12, oranges 8, bananes 15. Les bananes sont les plus nombreuses.",
    [SupplementalQuestion("annual_ce2_ce2_lire_tableau_annual_1", "Dans un tableau, les informations sont rangées…", ["Seulement en dessins","En lignes et en colonnes","Sans titre ni repère"], 1, "Les lignes et les colonnes permettent de classer les données."), SupplementalQuestion("annual_ce2_ce2_lire_tableau_annual_2", "12 mangues, 8 oranges et 15 bananes : quel fruit est le plus nombreux ?", ["Les oranges","Les mangues","Les bananes"], 2, "15 est le plus grand nombre."), SupplementalQuestion("annual_ce2_ce2_lire_tableau_annual_3", "Pour comprendre un tableau, il faut d’abord…", ["Lire son titre et ses repères","Choisir un nombre au hasard","Ignorer les colonnes"], 0, "Le titre et les en-têtes expliquent les données.")]),
  SupplementalLesson("cm1_decouvrir_metiers_annual", SchoolLevel.cm1, "Éducation / Orientation", "Découvrir les métiers et les compétences",
    "Un métier répond à un besoin. Chaque métier mobilise des connaissances, des gestes, des outils et des règles de sécurité. Découvrir les métiers relie les apprentissages à la vie réelle.",
    "Le maçon mesure et construit ; l’infirmier soigne ; l’agriculteur cultive ; le mécanicien entretient les véhicules.",
    [SupplementalQuestion("annual_cm1_cm1_decouvrir_metiers_annual_1", "Un métier mobilise généralement…", ["Des compétences et des outils adaptés","Aucune connaissance","Uniquement le hasard"], 0, "Chaque métier demande des compétences et des outils appropriés."), SupplementalQuestion("annual_cm1_cm1_decouvrir_metiers_annual_2", "Pourquoi découvrir plusieurs métiers ?", ["Pour choisir à la place des autres","Pour comprendre les activités et les compétences","Pour arrêter d’apprendre à l’école"], 1, "Découvrir les métiers permet de mieux comprendre le monde du travail."), SupplementalQuestion("annual_cm1_cm1_decouvrir_metiers_annual_3", "Dans une activité pratique, la sécurité consiste à…", ["Ignorer les consignes","Utiliser les outils sans précaution","Respecter les consignes et les protections"], 2, "Les règles de sécurité protègent les personnes.")]),
  SupplementalLesson("cm2_projet_metiers_annual", SchoolLevel.cm2, "Éducation / Orientation", "Préparer un projet de découverte d’un métier",
    "Un projet de découverte commence par une question, puis une recherche, une rencontre ou une observation. On note les tâches, les outils, les compétences et les règles de sécurité du métier.",
    "Question → rechercher une information fiable → observer/interroger → présenter ce que l’on a appris.",
    [SupplementalQuestion("annual_cm2_cm2_projet_metiers_annual_1", "Quelle est une bonne première étape d’un projet ?", ["Choisir une question à explorer","Inventer les réponses","Ne rien planifier"], 0, "Une question claire donne un objectif au projet."), SupplementalQuestion("annual_cm2_cm2_projet_metiers_annual_2", "Pendant une enquête sur un métier, il faut…", ["Photographier sans permission","Respecter la personne et demander son accord","Modifier ses réponses"], 1, "Une enquête respecte la personne interrogée."), SupplementalQuestion("annual_cm2_cm2_projet_metiers_annual_3", "Pour présenter les résultats, on peut…", ["Cacher les informations","Lire des notes sans organisation","Faire un résumé clair avec les étapes"], 2, "Une présentation organisée permet de partager les découvertes.")]),
  SupplementalLesson("sixieme_demarche_scientifique_annual", SchoolLevel.sixieme, "Sciences", "Suivre une démarche scientifique",
    "Une démarche scientifique part d’une observation ou d’une question. On formule une hypothèse, on réalise une observation ou une expérience adaptée, puis on analyse les résultats et on conclut.",
    "Question → hypothèse → protocole → observations/résultats → conclusion.",
    [SupplementalQuestion("annual_sixieme_sixieme_demarche_scientifique_annual_1", "Une hypothèse est…", ["Une réponse provisoire à vérifier","Une conclusion certaine avant l’étude","Un résultat inventé"], 0, "Une hypothèse doit pouvoir être examinée à partir de faits."), SupplementalQuestion("annual_sixieme_sixieme_demarche_scientifique_annual_2", "Pendant une expérience, on doit…", ["Changer toutes les conditions sans les noter","Suivre un protocole et noter les observations","Choisir le résultat avant de commencer"], 1, "Un protocole aide à réaliser et à décrire l’expérience."), SupplementalQuestion("annual_sixieme_sixieme_demarche_scientifique_annual_3", "La conclusion doit s’appuyer sur…", ["Une rumeur","Une préférence personnelle","Les résultats observés"], 2, "La conclusion doit être cohérente avec les résultats.")]),
  SupplementalLesson("cinquieme_energie_solaire_annual", SchoolLevel.cinquieme, "Physique / Environnement", "Comprendre l’énergie solaire",
    "Le Soleil fournit de la lumière et de la chaleur. Des panneaux photovoltaïques convertissent une partie de la lumière en énergie électrique. La production dépend de l’ensoleillement et des équipements.",
    "Lumière du Soleil → panneau photovoltaïque → énergie électrique → appareil.",
    [SupplementalQuestion("annual_cinquieme_cinquieme_energie_solaire_annual_1", "L’énergie solaire provient…", ["Du charbon","Du Soleil","Du pétrole"], 1, "Le rayonnement solaire est la source de cette énergie."), SupplementalQuestion("annual_cinquieme_cinquieme_energie_solaire_annual_2", "Un panneau photovoltaïque transforme…", ["L’eau en sable","Le vent en pluie","La lumière en électricité"], 2, "Les cellules photovoltaïques produisent de l’électricité à partir de la lumière."), SupplementalQuestion("annual_cinquieme_cinquieme_energie_solaire_annual_3", "L’énergie solaire est dite renouvelable car…", ["La source se renouvelle naturellement","Elle est toujours disponible la nuit","Elle ne nécessite aucun équipement"], 0, "Le rayonnement solaire se renouvelle naturellement, même si la production varie.")]),
  SupplementalLesson("quatrieme_experience_variables_annual", SchoolLevel.quatrieme, "Sciences / Méthode", "Réaliser une expérience contrôlée",
    "Pour comparer deux situations, on change un facteur à la fois et on garde les autres conditions identiques. On mesure les résultats et on les note pour pouvoir les comparer.",
    "Pour tester l’effet de la lumière sur une plante, garder la même plante, la même quantité d’eau et la même durée ; modifier seulement la lumière.",
    [SupplementalQuestion("annual_quatrieme_quatrieme_experience_variables_annual_1", "Pour tester l’effet d’un facteur, on doit…", ["Changer tous les facteurs à la fois","Modifier un facteur et contrôler les autres","Ne mesurer aucun résultat"], 1, "Changer un seul facteur facilite l’interprétation."), SupplementalQuestion("annual_quatrieme_quatrieme_experience_variables_annual_2", "Pourquoi noter les mesures ?", ["Pour les oublier plus vite","Pour remplacer l’expérience","Pour comparer les résultats et vérifier"], 2, "Les mesures enregistrées rendent la comparaison possible."), SupplementalQuestion("annual_quatrieme_quatrieme_experience_variables_annual_3", "Une conclusion solide est…", ["Fondée sur les observations et les mesures","Choisie avant l’expérience","Identique dans toutes les expériences"], 0, "Les conclusions dépendent des résultats réellement obtenus.")]),
  SupplementalLesson("troisieme_projet_scientifique_annual", SchoolLevel.troisieme, "Sciences / Technologie", "Construire un projet scientifique ou technique",
    "Un projet scientifique ou technique répond à un besoin ou à une question. Il faut définir le problème, proposer une solution, planifier les étapes, tester, améliorer et présenter les résultats.",
    "Besoin → idées → prototype ou investigation → test → amélioration → présentation.",
    [SupplementalQuestion("annual_troisieme_troisieme_projet_scientifique_annual_1", "Un projet commence par…", ["Une solution sans besoin identifié","Un problème ou un besoin clairement défini","La présentation finale"], 1, "Le problème donne une direction au projet."), SupplementalQuestion("annual_troisieme_troisieme_projet_scientifique_annual_2", "Après avoir testé une solution, il faut…", ["Ignorer les résultats","Interdire toute amélioration","Analyser le test et corriger si nécessaire"], 2, "Le test sert à identifier les points à améliorer."), SupplementalQuestion("annual_troisieme_troisieme_projet_scientifique_annual_3", "Dans un travail d’équipe, il est utile de…", ["Répartir les tâches et partager les résultats","Confier tout à une seule personne","Cacher les difficultés"], 0, "La répartition et la communication facilitent le travail collectif.")]),
  SupplementalLesson("seconde_orientation_parcours_annual", SchoolLevel.seconde, "Orientation", "Comprendre les parcours et construire son orientation",
    "L’orientation se construit en examinant les matières étudiées, les compétences, les intérêts et les possibilités de formation. Les parcours général, scientifique et technique peuvent mener à des formations différentes ; vérifie les informations auprès de ton établissement.",
    "Comparer les matières, les séries et les débouchés avec un conseiller, un enseignant ou les documents officiels.",
    [SupplementalQuestion("annual_seconde_seconde_orientation_parcours_annual_1", "Pour préparer son orientation, il faut…", ["Choisir uniquement selon une rumeur","Comparer ses intérêts, les matières et les formations","Décider sans se renseigner"], 1, "Une orientation réfléchie s’appuie sur des informations et les aptitudes de l’élève."), SupplementalQuestion("annual_seconde_seconde_orientation_parcours_annual_2", "Une information fiable sur une série vient…", ["D’un message anonyme non vérifié","D’une supposition","Des documents officiels et de l’équipe éducative"], 2, "Les documents officiels permettent de vérifier les conditions et les matières."), SupplementalQuestion("annual_seconde_seconde_orientation_parcours_annual_3", "Le parcours technique peut développer…", ["Des compétences pratiques et technologiques","Uniquement des activités sans apprentissage","Aucune compétence transférable"], 0, "Les parcours techniques associent connaissances et compétences professionnelles.")]),
  SupplementalLesson("premiere_revision_active_annual", SchoolLevel.premiere, "Méthodologie", "Réviser avec la pratique active",
    "La pratique active consiste à essayer de retrouver une notion sans regarder immédiatement le cours, puis à vérifier et corriger. Répartir les révisions sur plusieurs jours aide à consolider la mémoire.",
    "Lire un cours, fermer le cahier, expliquer la notion, faire quelques exercices, corriger puis revoir la notion plus tard.",
    [SupplementalQuestion("annual_premiere_premiere_revision_active_annual_1", "La pratique active consiste à…", ["Relire passivement sans réfléchir","Recopier sans vérifier","Rappeler une notion puis vérifier sa réponse"], 2, "Essayer de retrouver l’information renforce l’apprentissage."), SupplementalQuestion("annual_premiere_premiere_revision_active_annual_2", "Une révision espacée signifie…", ["Réviser à plusieurs moments séparés","Tout apprendre en une seule nuit","Ne jamais refaire les exercices"], 0, "Espacer les séances permet de revoir les notions après un délai."), SupplementalQuestion("annual_premiere_premiere_revision_active_annual_3", "Après une erreur dans un exercice, il faut…", ["Cacher la correction","Comprendre l’erreur et refaire un exercice similaire","Arrêter toute révision"], 1, "Analyser l’erreur aide à éviter de la répéter.")]),
  SupplementalLesson("terminale_plan_revision_annual", SchoolLevel.terminale, "Méthodologie / Examens", "Planifier les révisions et les épreuves",
    "Une préparation efficace répartit les matières, les chapitres et les entraînements sur plusieurs semaines. Alterne rappel du cours, exercices, sujets chronométrés et correction des erreurs, tout en préservant le sommeil.",
    "Calendrier hebdomadaire : matière → objectif précis → exercices → correction → reprise des erreurs.",
    [SupplementalQuestion("annual_terminale_terminale_plan_revision_annual_1", "Un planning de révision utile doit…", ["Prévoir des objectifs réalistes et des créneaux","Remplir chaque minute sans pause","Éviter les matières difficiles"], 0, "Des objectifs réalistes rendent le planning utilisable."), SupplementalQuestion("annual_terminale_terminale_plan_revision_annual_2", "Un sujet chronométré sert à…", ["Remplacer tous les cours","S’entraîner à gérer le temps et les consignes","Éviter la correction"], 1, "L’entraînement chronométré prépare aux conditions d’épreuve."), SupplementalQuestion("annual_terminale_terminale_plan_revision_annual_3", "Après un sujet d’entraînement, il faut…", ["Ne regarder que la note","Ignorer les questions ratées","Analyser les erreurs et revoir les notions concernées"], 2, "La correction transforme l’entraînement en apprentissage.")]),
];